# Generated from tools/data/rulebooks/mahjong.json; run tools/compile-rulebooks.rb.
module GameRoomGames
  module MahjongRules
    module GeneratedRulebook
      private

      def generated_rule_sections
        [
          rule_section(:table_aim, GameRoomRules.translate("Mahjong: aim of the game"),
            GameRoomRules.translate("In the default Solitaire game you remove matching pairs and win by clearing the layout. Hong Kong, Riichi and MCR are separate games against other players: you build your own winning hand and score points. Each has its own complete part below, starting with its aim and terms."),
            GameRoomRules.translate("Sounds distinguish dealing, drawing and discarding a tile, declaring a set and ending a hand. Solitaire also sounds pair removal and undo. Passing and browsing tiles are silent. Spoken descriptions still identify the tile and result."),
            GameRoomRules.translate("While responding to a tile, D reads the tile to which Pass, Chow, Pung, Kong or Mahjong applies. It does not change or submit your choice. In Solitaire, D still reads coordinates."),
            GameRoomRules.translate("In Hong Kong, Riichi and MCR, W also reads a subtotal of basic bonuses already present: dragon and scoring-wind triplets, plus the applicable bonus tiles or an accepted Riichi declaration. Concealed triplets count while you keep them together. This is not the value of an unfinished hand: whole-hand patterns may replace basic bonuses. In MCR, flowers are listed separately and do not help reach 8 fan; Riichi lists visible dora separately because dora require yaku. When creating a table, Basic scoring preview under W defaults to Yes; choose No to keep only the legal-win readout. The setting never changes scoring or permission to win. MCR: 2/3/4 concealed pungs = 2/16/64 fan; these awards replace one another. W uses a concise subtotal while incomplete and the full legal-win value when available."),
            GameRoomRules.translate("After a win, Hand value lists the scoring components actually awarded, excluding replaced patterns. In MCR it separates the hand fan from flower/season extras and states their total for payment; extras never count towards the 8-fan qualifying minimum.")),
          rule_section(:aim, GameRoomRules.translate("Solitaire \u2014 terms and aim"),
            GameRoomRules.translate("Remove all 144 tiles in matching pairs. You play alone and win when you remove the last pair."),
            GameRoomRules.translate("In Solitaire, the layout is the whole arrangement of tiles. A pair is two matching pieces; a layer is a height level; rows run across and columns down. A free tile has nothing above it and at least one open side, left or right. A visible tile can still be blocked on both sides."),
            GameRoomRules.translate("You do not build chows, pungs or kongs, or count fan, han or yaku in this variant. Those belong to the multiplayer games. Here you win by removing every pair from the layout.")),
          rule_section(:tiles, GameRoomRules.translate("Solitaire: Matching and free tiles"),
            GameRoomRules.translate("A pair normally contains two tiles with the same suit and number, the same wind, or the same dragon. Any two flowers match each other, as do any two seasons. A flower does not match a season."),
            GameRoomRules.translate("Both tiles must be free: no tile may overlap them from above, and each must have an open left or right side. A visible tile can still be blocked on both sides. Covered tiles are announced without revealing their faces.")),
          rule_section(:play, GameRoomRules.translate("Solitaire: Choosing a pair"),
            GameRoomRules.translate("In Tiles in the layout, Left and Right move between columns; Up and Down move between rows. Press 1, 2 or 3 to switch layers in Terraces; Flat has only layer 1. A layer is a height level, not a row. Press D to hear the layer, row and column, counted separately within each layer."),
            GameRoomRules.translate("Each visible tile is announced as available from the left, from the right, from both sides, or blocked on both sides. A covered tile is announced without its face. Empty positions remain after removal, so the coordinates of the other tiles do not change."),
            GameRoomRules.translate("Find a free tile and press Enter to mark it. Then find another free matching tile and press Enter to remove both. The first selection alone removes nothing. A mismatched second tile leaves the first selected. Press Enter again on the first tile, or Escape, to cancel the selection. The game does not list matching pairs for you."),
            GameRoomRules.translate("Removing a pair can free tiles underneath or beside it. Consider which tiles your choice will uncover. A new puzzle has a solution, but some choices can leave you without another matching pair."),
            GameRoomRules.translate("Example: find a free bamboo 5 and press Enter to mark it. Find another free bamboo 5, possibly on another layer, and press Enter. Both are removed. If the second 5 is covered or blocked, first free it by removing other pairs."),
            GameRoomRules.translate("When several identical tiles are available, consider which copies to remove. Removing an edge tile may free its neighbour; removing an upper tile uncovers one below. Not every available pair leads to a solution. Undo the last pair lets you return and try another order.")),
          rule_section(:ending, GameRoomRules.translate("Solitaire: Undo, progress and finishing"),
            GameRoomRules.translate("Use Undo the last pair to restore the most recently removed tiles. You can undo several moves, one pair at a time, until the starting layout returns."),
            GameRoomRules.translate("Progress shows how many pairs you have removed and how many tiles remain. Your score is the number of removed pairs, up to 72. When no pair is available, undo a move to try another route or choose End this puzzle. Ending early does not count as clearing the layout."),
            GameRoomRules.translate("S reads your removed-pair score. M reads how many tiles remain in the layout. A new puzzle has 144 tiles; removing one pair leaves 142.")),
          rule_section(:solitaire_points, GameRoomRules.translate("Solitaire \u2014 points for removing pairs"),
            GameRoomRules.translate("Solitaire uses no fan, han or fu. The score is the number of removed pairs: each pair scores 1, and undoing its removal subtracts that point. Clear all 144 tiles, or 72 pairs, to win.")),
          rule_section(:layout, GameRoomRules.translate("Solitaire: Layout choice"),
            GameRoomRules.translate("Terraces is the default layered layout. Flat places all tiles on one layer. The matching rule and the requirement for a free left or right side are the same in both layouts.")),
          rule_section(:table_hk_aim, GameRoomRules.translate("Hong Kong \u2014 Aim and winning conditions"),
            GameRoomRules.translate("Four players compete to complete a winning hand first. The normal shape is four sets and a pair, and it must be worth at least 3 fan: fan measure the hand\u2019s scoring value. Over a full match, the player with the highest total points wins. The terms below explain the sets and scoring units before your first turn.")),
          rule_section(:table_hk_terms, GameRoomRules.translate("Hong Kong \u2014 How the terms work"),
            GameRoomRules.translate("You play against the other players. Tiles in your hand are yours to arrange into a winning pattern; you do not remove matching pairs from a layout as in Solitaire. A hand is one deal and its play. A match may contain many hands."),
            GameRoomRules.translate("- A tile is one piece, such as bamboo 5. Its kind is its suit and number, or its particular wind or dragon. There are four copies of each ordinary kind."),
            GameRoomRules.translate("- Suits are characters, bamboo and circles, numbered 1\u20139. Different suits do not mix in one sequence. Terminals are 1 and 9; simples are 2\u20138."),
            GameRoomRules.translate("- Honors are East, South, West and North winds, and white, green and red dragons. They have no number and cannot form a sequence."),
            GameRoomRules.translate("- A chow or chi is three consecutive numbers in one suit: bamboo 3, 4 and 5. Bamboo 3, circles 4 and bamboo 5 do not qualify. Nor do 8, 9 and 1 of one suit."),
            GameRoomRules.translate("- A pung, also written pong or pon, is three identical tiles, such as three red dragons. Three fives from different suits are not a pung."),
            GameRoomRules.translate("- A kong or kan is four identical tiles. You must declare it through the kong action; simply holding four copies does not declare a kong. It is one set, with an extra replacement draw."),
            GameRoomRules.translate("- A pair is two identical tiles. A set is a chow, pung or kong. An ordinary winning hand needs four sets and one pair, not merely several pairs or a large number of tiles of one suit."),
            GameRoomRules.translate("- The wall is the supply of tiles you draw from. Drawing adds a tile to your hand; discarding removes one tile from your hand and offers it to opponents."),
            GameRoomRules.translate("- A closed hand has no sets claimed from opponents. Claiming a chow, pung or exposed kong opens it. Sets formed entirely from your own tiles can stay concealed. A declared concealed kong keeps your hand closed."),
            GameRoomRules.translate("- A self-draw win uses the tile you have just drawn. A discard win uses an opponent\u2019s discarded tile to finish your hand. Claim Mahjong to win; do not discard the winning tile first."),
            GameRoomRules.translate("- A wait is a tile kind that would finish your hand. With bamboo 4\u20135 you might wait for bamboo 3 or 6. Being one tile from a complete shape is called tenpai. A complete shape must still satisfy this variant\u2019s scoring conditions."),
            GameRoomRules.translate("- Fan are scoring units awarded for patterns and winning circumstances. You need at least 3 fan to win this profile. They are converted into match points; 3 fan does not mean you gain only 3 points."),
            GameRoomRules.translate("- Your seat wind is your current role: the dealer is East, followed by South, West and North. The round wind belongs to the whole table. A pung of your own wind or the round wind can score; a pair of that wind is not enough for that award."),
            GameRoomRules.translate("- Flowers and seasons are bonus tiles. The game exposes and replaces them automatically. They do not fill a chow, pung or the pair and are separate from wind rounds.")),
          rule_section(:table_hk_start, GameRoomRules.translate("Hong Kong \u2014 Starting the hand"),
            GameRoomRules.translate("Balances start at zero; winning hands add payments and losing them subtracts payments."),
            GameRoomRules.translate("The dealer starts with 14 tiles and discards first. Everyone else starts with 13. On a normal turn, choose Draw a tile and press Enter. Drawing is an action; moving through the tile list does not draw.")),
          rule_section(:table_hk_play, GameRoomRules.translate("Hong Kong \u2014 Your first turns"),
            GameRoomRules.translate("Before your first discard, read your hand with Up and Down. Think of numbered tiles as possible sequences, identical tiles as possible pungs, and one pair as your eventual pair. You do not select all four sets in the interface: sets left in your hand are recognised when you declare a win."),
            GameRoomRules.translate("While you browse game fields, a new turn focuses Draw a tile. After drawing, focus moves to the newly drawn tile in your hand, marked just drawn. This does not discard it. You can move to another tile with the arrows or keep the new tile and discard an old one."),
            GameRoomRules.translate("To discard, find one tile in the available-to-discard list and press Enter. You lose that copy from your hand. If you hold several identical copies, discarding one does not remove the others."),
            GameRoomRules.translate("After another player discards, listen to the tile and read the response list. Pass means you do not claim that tile; it does not end your participation or concede the hand. If everyone passes, the next player draws. Passing several times does not mean you must draw each time: it may still be another player\u2019s turn."),
            GameRoomRules.translate("The first field describes the current situation. All available actions follow it: responses, Draw, Declare Mahjong, kong choices or Riichi when applicable. Your tile lists come after those actions. Tab and Shift+Tab move between fields; arrows choose within a list, and Enter confirms. An unavailable action is omitted."),
            GameRoomRules.translate("Read Exposed sets to inspect everyone\u2019s declared sets; each entry names its owner. Discards records which tiles each player has discarded. These fields help you see what is already used and what opponents may need. You can review them without submitting a move."),
            GameRoomRules.translate("If a tile completes an eligible winning hand, choose Declare Mahjong rather than discarding it or passing. The game checks both the shape and this variant\u2019s scoring requirements. If the wall runs out first, the hand is a draw; nobody wins merely for having the most nearly complete hand."),
            GameRoomRules.translate("Press S to hear the current points of every player. Press M to hear how many tiles remain in the wall for drawing. These are read-only announcements: they do not draw, discard or pass, and do not reveal other hands."),
            GameRoomRules.translate("W reads a legal winning hand value: fan or han and fu, and the points gained. Without a legal win it does not give a final hand value. Before a Riichi win it excludes hidden ura-dora, so the final value may be higher. U reads your exposed sets, Shift+U those of the other players, and R the hand number, winds and current situation. In Riichi, I reads dora indicators and tiles, your dora count, Riichi declarations, deposits, honba and your furiten restriction. These keys only read information.")),
          rule_section(:table_hand, GameRoomRules.translate("Hong Kong \u2014 What you must build to win"),
            GameRoomRules.translate("Build four chows, pungs or kongs and a pair, counting both declared and retained sets. A chow has three consecutive numbers in one suit, a pung three identical tiles, a kong four and a pair two. You also need 3 fan. When both conditions hold, choose Declare Mahjong and press Enter. The full scoring reference follows; drawing a matching tile does not end the hand automatically.")),
          rule_section(:table_hk_claims, GameRoomRules.translate("Hong Kong \u2014 Claiming tiles and declaring kongs"),
            GameRoomRules.translate("When another player discards, the response list offers only legal choices. Select Pass if you do not want the tile. To claim it, choose Chow, Pung, Kong or Declare Mahjong and press Enter. A chow may be claimed only from the player immediately before you. A pung or kong can use a discard from any opponent."),
            GameRoomRules.translate("A winning claim takes priority over a set claim; pung and kong take priority over chow. If several players can win on the same tile, the first in turn order after the discarder wins. The hand waits for every required response. After claiming chow or pung, discard without drawing; the claimed set stays exposed."),
            GameRoomRules.translate("After declaring a kong, draw a replacement tile before discarding. If you hold all four copies, the concealed-kong list lets you declare them together. You may also add your fourth tile to an exposed pung. Opponents can claim a win on that added tile before the kong is completed."),
            GameRoomRules.translate("Example: you hold two red dragons and someone discards a red dragon. Pung lets you take it and expose all three. You then discard one of your remaining tiles without first drawing. With bamboo 4\u20135, a bamboo 3 or 6 discarded by the player immediately before you may allow Chow. A matching tile from a different player cannot be claimed for Chow.")),
          rule_section(:table_hk_sets, GameRoomRules.translate("Hong Kong \u2014 complete scoring reference"),
            GameRoomRules.translate("A normal win needs four sets and a pair and at least 3 fan. Seven pairs and thirteen orphans use different shapes. The complete scoring reference for this version follows; entries allow open and closed hands unless restricted. An ordinary single chow, numbered pung or pair has no separate bonus."),
            GameRoomRules.translate("Compatible ordinary bonuses add together. Little and big three dragons replace the component dragon-pung bonuses. Special hands worth 10 fan or more use only the highest applicable special award, without ordinary bonuses. A concealed hand or four concealed pungs has no separate award. All eight bonus tiles give 4 fan; seven pairs give 4 fan.")),
          rule_section(:table_hk_fan_1, GameRoomRules.translate("Hong Kong: 1 fan"),
            GameRoomRules.translate("- 1 fan \u2014 Self-draw: draw the winning tile yourself."),
            GameRoomRules.translate("- 1 fan \u2014 All chows: four sequences and a pair, which may be honours."),
            GameRoomRules.translate("- 1 fan \u2014 Pung or kong of red dragons."),
            GameRoomRules.translate("- 1 fan \u2014 Pung or kong of green dragons."),
            GameRoomRules.translate("- 1 fan \u2014 Pung or kong of white dragons."),
            GameRoomRules.translate("- 1 fan \u2014 Pung or kong of your seat wind."),
            GameRoomRules.translate("- 1 fan \u2014 Pung or kong of the round wind; matching seat and round wind scores 2 fan in total."),
            GameRoomRules.translate("- 1 fan \u2014 Win on a kong replacement tile; self-draw also counts."),
            GameRoomRules.translate("- 1 fan \u2014 Robbing a kong: win on the tile being added to an exposed pung."),
            GameRoomRules.translate("- 1 fan \u2014 Last ordinary wall draw; self-draw also counts."),
            GameRoomRules.translate("- 1 fan \u2014 Win on the last discard after the ordinary wall is empty."),
            GameRoomRules.translate("- 1 fan \u2014 No bonus tiles: neither flowers nor seasons."),
            GameRoomRules.translate("- 1 fan \u2014 Your flower: its number matches your seat wind."),
            GameRoomRules.translate("- 1 fan \u2014 Your season: its number matches your seat wind.")),
          rule_section(:table_hk_fan_2, GameRoomRules.translate("Hong Kong: 2 fan"),
            GameRoomRules.translate("- 2 fan \u2014 All four flowers: replaces the 1 fan for your flower."),
            GameRoomRules.translate("- 2 fan \u2014 All four seasons: replaces the 1 fan for your season.")),
          rule_section(:table_hk_fan_3_8, GameRoomRules.translate("Hong Kong: 3\u20138 fan"),
            GameRoomRules.translate("- 3 fan \u2014 All pungs: four pungs or kongs and a pair."),
            GameRoomRules.translate("- 3 fan \u2014 Half flush: one numbered suit and honours, both present."),
            GameRoomRules.translate("- 4 fan \u2014 Seven pairs: four identical tiles not declared as a kong may count as two pairs."),
            GameRoomRules.translate("- 5 fan \u2014 Little three dragons: two dragon pungs or kongs and a pair of the third; includes dragon-pung bonuses."),
            GameRoomRules.translate("- 7 fan \u2014 Full flush: only Bamboo, only Dots or only Characters, no honours."),
            GameRoomRules.translate("- 8 fan \u2014 Big three dragons: pungs or kongs of all three dragons; includes dragon-pung bonuses.")),
          rule_section(:table_hk_fan_special, GameRoomRules.translate("Hong Kong: 10\u201318 fan"),
            GameRoomRules.translate("- 10 fan \u2014 Little four winds: three wind pungs or kongs and a pair of the fourth."),
            GameRoomRules.translate("- 10 fan \u2014 All honours: a valid winning hand using only winds and dragons."),
            GameRoomRules.translate("- 10 fan \u2014 All terminals: only numbered 1s and 9s, no honours."),
            GameRoomRules.translate("- 13 fan \u2014 Thirteen orphans: every suited 1 and 9, all four winds and three dragons, plus one duplicate for a pair; closed hand."),
            GameRoomRules.translate("- 15 fan \u2014 Big four winds: four wind pungs or kongs and a pair."),
            GameRoomRules.translate("- 15 fan \u2014 Nine gates: concealed exact base 1112345678999 in one suit before the winning draw or claim of another tile of that suit."),
            GameRoomRules.translate("- 18 fan \u2014 Four kongs and a pair.")),
          rule_section(:table_hk_bonus, GameRoomRules.translate("Hong Kong \u2014 flowers and seasons by seat wind"),
            GameRoomRules.translate("Your flower and season follow your seat wind, not the round wind. Number 1 is East, 2 South, 3 West, 4 North. A complete family replaces its own-tile bonus; the two families score separately."),
            GameRoomRules.translate("- East: Plum flower and Spring."),
            GameRoomRules.translate("- South: Orchid flower and Summer."),
            GameRoomRules.translate("- West: Chrysanthemum flower and Autumn."),
            GameRoomRules.translate("- North: Bamboo flower and Winter.")),
          rule_section(:table_hk_payments, GameRoomRules.translate("Hong Kong \u2014 Scoring and payments"),
            GameRoomRules.translate("Payment bases are: 3 fan \u2014 8 points; 4 \u2014 16; 5 \u2014 24; 6 \u2014 32; 7 \u2014 48; 8 or more \u2014 64. A hand may exceed 8 fan, but its payment base does not increase."),
            GameRoomRules.translate("On a discard win, the discarder pays two bases and the other opponents one each. On self-draw, every opponent pays two bases."),
            GameRoomRules.translate("Heavenly and earthly hands are not currently awarded during play. Do not add a special opening-win bonus for them.")),
          rule_section(:table_winds, GameRoomRules.translate("Hong Kong \u2014 Hands and match length"),
            GameRoomRules.translate("The default match has four wind rounds: East, South, West and North. Every player completes a dealer period in each round, making at least sixteen hands. Hand payments accumulate from zero; winning one hand does not necessarily win the match."),
            GameRoomRules.translate("The dealer repeats after their win or any draw, so East takes at least four hands and can take more. Four wind rounds are East, South, West and North: at least 16 hands. Seasons are bonus tiles, not these rounds."),
            GameRoomRules.translate("After a hand, inspect the winner, hand value and point changes. In a longer match everyone chooses Ready for the next hand. A draw changes no hand points in Hong Kong. After the selected rounds, the highest total wins; equal highest totals tie.")),
          rule_section(:table_hk_variants, GameRoomRules.translate("Hong Kong \u2014 Match length options"),
            GameRoomRules.translate("Choose match length in the game options before play. The following shorter settings change how many hands the match contains, not the rules for completing a winning hand."),
            GameRoomRules.translate("One hand ends the game after one win or wall draw. East round means that all four players complete a dealer period. The dealer is East, but the shared round wind also remains East throughout that round. It is not one personal turn.")),
          rule_section(:table_riichi_aim, GameRoomRules.translate("Riichi \u2014 Aim and winning conditions"),
            GameRoomRules.translate("In the standard four-player game you aim to complete your hand before the others. Usually it has four sets and a pair, but it also needs a yaku: a recognised winning condition. A complete shape without yaku may be unable to win. The match winner has the highest final points; the following terms explain these conditions.")),
          rule_section(:table_riichi_terms, GameRoomRules.translate("Riichi \u2014 How the terms work"),
            GameRoomRules.translate("You play against the other players. Tiles in your hand are yours to arrange into a winning pattern; you do not remove matching pairs from a layout as in Solitaire. A hand is one deal and its play. A match may contain many hands."),
            GameRoomRules.translate("- A tile is one piece, such as bamboo 5. Its kind is its suit and number, or its particular wind or dragon. There are four copies of each ordinary kind."),
            GameRoomRules.translate("- Suits are characters, bamboo and circles, numbered 1\u20139. Different suits do not mix in one sequence. Terminals are 1 and 9; simples are 2\u20138."),
            GameRoomRules.translate("- Honors are East, South, West and North winds, and white, green and red dragons. They have no number and cannot form a sequence."),
            GameRoomRules.translate("- A chow or chi is three consecutive numbers in one suit: bamboo 3, 4 and 5. Bamboo 3, circles 4 and bamboo 5 do not qualify. Nor do 8, 9 and 1 of one suit."),
            GameRoomRules.translate("- A pung, also written pong or pon, is three identical tiles, such as three red dragons. Three fives from different suits are not a pung."),
            GameRoomRules.translate("- A kong or kan is four identical tiles. You must declare it through the kong action; simply holding four copies does not declare a kong. It is one set, with an extra replacement draw."),
            GameRoomRules.translate("- A pair is two identical tiles. A set is a chow, pung or kong. An ordinary winning hand needs four sets and one pair, not merely several pairs or a large number of tiles of one suit."),
            GameRoomRules.translate("- The wall is the supply of tiles you draw from. Drawing adds a tile to your hand; discarding removes one tile from your hand and offers it to opponents."),
            GameRoomRules.translate("- A closed hand has no sets claimed from opponents. Claiming a chow, pung or exposed kong opens it. Sets formed entirely from your own tiles can stay concealed. A declared concealed kong keeps your hand closed."),
            GameRoomRules.translate("- A self-draw win uses the tile you have just drawn. A discard win uses an opponent\u2019s discarded tile to finish your hand. Claim Mahjong to win; do not discard the winning tile first."),
            GameRoomRules.translate("- A wait is a tile kind that would finish your hand. With bamboo 4\u20135 you might wait for bamboo 3 or 6. Being one tile from a complete shape is called tenpai. A complete shape must still satisfy this variant\u2019s scoring conditions."),
            GameRoomRules.translate("- Yaku is a named condition that makes a winning shape eligible. You need at least one yaku. For example, a pung of dragons is a yaku; a random complete shape is not necessarily one."),
            GameRoomRules.translate("- Han measure the value of yaku and bonuses. Fu are smaller points for how your sets, pair and wait are built. Han and fu together determine the payment. Fu alone do not supply the required yaku."),
            GameRoomRules.translate("- Ron means a win on an opponent\u2019s discard; tsumo means a win on your own draw. Menzen means closed. Menzen tsumo is therefore a closed-hand self-draw win and is itself a yaku."),
            GameRoomRules.translate("- Riichi is a declaration that your closed hand is one tile from completion. It costs a 1000-point deposit and supplies a yaku, but restricts later changes to your hand."),
            GameRoomRules.translate("- Dora is a bonus tile kind named by an indicator. Each copy adds han after you have a real yaku. Holding dora alone does not permit a win."),
            GameRoomRules.translate("- Furiten is a restriction on winning from other players\u2019 discards. It can arise from your own discards or from declining a winning discard. It does not prevent self-draw wins."),
            GameRoomRules.translate("- Honba is the carry-over counter that adds payments after draws or dealer continuations. Mangan and higher limits are payment levels for valuable hands, not extra sets you must build."),
            GameRoomRules.translate("- Your seat wind is your role relative to the dealer: East for the dealer, then South, West and North. Round wind is shared by the table. A pung of either value wind can score, and one set can serve both roles when they coincide.")),
          rule_section(:table_riichi_start, GameRoomRules.translate("Riichi \u2014 Starting the hand"),
            GameRoomRules.translate("Everyone starts with 30,000 points. Payments and accepted Riichi deposits change that balance."),
            GameRoomRules.translate("The dealer starts with 14 tiles and discards first. Everyone else starts with 13. On a normal turn, choose Draw a tile and press Enter. Drawing is an action; moving through the tile list does not draw.")),
          rule_section(:table_riichi_play, GameRoomRules.translate("Riichi \u2014 Your first turns"),
            GameRoomRules.translate("Before your first discard, read your hand with Up and Down. Think of numbered tiles as possible sequences, identical tiles as possible pungs, and one pair as your eventual pair. You do not select all four sets in the interface: sets left in your hand are recognised when you declare a win."),
            GameRoomRules.translate("While you browse game fields, a new turn focuses Draw a tile. After drawing, focus moves to the newly drawn tile in your hand, marked just drawn. This does not discard it. You can move to another tile with the arrows or keep the new tile and discard an old one."),
            GameRoomRules.translate("To discard, find one tile in the available-to-discard list and press Enter. You lose that copy from your hand. If you hold several identical copies, discarding one does not remove the others."),
            GameRoomRules.translate("After another player discards, listen to the tile and read the response list. Pass means you do not claim that tile; it does not end your participation or concede the hand. If everyone passes, the next player draws. Passing several times does not mean you must draw each time: it may still be another player\u2019s turn."),
            GameRoomRules.translate("The first field describes the current situation. All available actions follow it: responses, Draw, Declare Mahjong, kong choices or Riichi when applicable. Your tile lists come after those actions. Tab and Shift+Tab move between fields; arrows choose within a list, and Enter confirms. An unavailable action is omitted."),
            GameRoomRules.translate("Read Exposed sets to inspect everyone\u2019s declared sets; each entry names its owner. Discards records which tiles each player has discarded. These fields help you see what is already used and what opponents may need. You can review them without submitting a move."),
            GameRoomRules.translate("If a tile completes an eligible winning hand, choose Declare Mahjong rather than discarding it or passing. The game checks both the shape and this variant\u2019s scoring requirements. If the wall runs out first, the hand is a draw; nobody wins merely for having the most nearly complete hand."),
            GameRoomRules.translate("Press S to hear the current points of every player. Press M to hear how many tiles remain in the wall for drawing. These are read-only announcements: they do not draw, discard or pass, and do not reveal other hands."),
            GameRoomRules.translate("W reads a legal winning hand value: fan or han and fu, and the points gained. Without a legal win it does not give a final hand value. Before a Riichi win it excludes hidden ura-dora, so the final value may be higher. U reads your exposed sets, Shift+U those of the other players, and R the hand number, winds and current situation. In Riichi, I reads dora indicators and tiles, your dora count, Riichi declarations, deposits, honba and your furiten restriction. These keys only read information.")),
          rule_section(:table_riichi_build, GameRoomRules.translate("Riichi \u2014 What you must build to win"),
            GameRoomRules.translate("The ordinary shape is four sets and a pair. Seven distinct pairs and thirteen orphans are alternatives. A win requires yaku; dora and fu alone do not qualify. When a legal win is available, choose Declare Mahjong and press Enter. The references below give every awarded yaku and the fu values.")),
          rule_section(:table_riichi_claims, GameRoomRules.translate("Riichi \u2014 Claiming tiles and declaring kongs"),
            GameRoomRules.translate("When another player discards, the response list offers only legal choices. Select Pass if you do not want the tile. To claim it, choose Chow, Pung, Kong or Declare Mahjong and press Enter. A chow may be claimed only from the player immediately before you. A pung or kong can use a discard from any opponent."),
            GameRoomRules.translate("A winning claim takes priority over a set claim; pung and kong take priority over chow. If several players can win on the same tile, the first in turn order after the discarder wins. The hand waits for every required response. After claiming chow or pung, discard without drawing; the claimed set stays exposed."),
            GameRoomRules.translate("After declaring a kong, draw a replacement tile before discarding. If you hold all four copies, the concealed-kong list lets you declare them together. You may also add your fourth tile to an exposed pung. Opponents can claim a win on that added tile before the kong is completed."),
            GameRoomRules.translate("Opening your hand can remove your planned yaku. Riichi and closed self-draw require a closed hand, while dragon pungs still score when exposed. Before claiming Chow or Pung, decide what yaku will remain.")),
          rule_section(:table_riichi, GameRoomRules.translate("Riichi \u2014 declaring readiness, dora and furiten"),
            GameRoomRules.translate("If your closed hand is one tile from winning, the Riichi list offers legal declaration discards. Select one and press Enter. An accepted declaration places 1,000 points on the table. Afterwards you must discard the drawn tile unless it wins; only a kong preserving all required hand interpretations is allowed. The winner collects the deposits; an unclaimed deposit carries to the next hand."),
            GameRoomRules.translate("Furiten prevents winning on a discard when one of your winning tiles appears among your own discards. Passing a legal winning discard also blocks discard wins temporarily; after declaring Riichi, this block lasts for the rest of the hand. You can still win by drawing the tile yourself."),
            GameRoomRules.translate("Suppose you wait for bamboo 3 or 6 but previously discarded bamboo 3. Furiten blocks a discard win on both winning kinds, including 6; it is not limited to the exact tile you discarded. A self-drawn 3 or 6 can still win if the hand qualifies.")),
          rule_section(:table_yaku, GameRoomRules.translate("Riichi \u2014 complete yaku and han reference"),
            GameRoomRules.translate("Riichi needs a valid hand and at least one yaku. Below are all ordinary yaku awarded in this version, with closed and open values. A concealed kong does not open the hand. A pung completed by the winning discard is not concealed when scoring that win."),
            GameRoomRules.translate("- Riichi: a closed ready hand and accepted declaration with a 1000-point deposit. Closed only: 1 han."),
            GameRoomRules.translate("- Double riichi: declaration in the first uninterrupted circuit; replaces ordinary riichi. Closed only: 2 han."),
            GameRoomRules.translate("- Ippatsu: win in the first uninterrupted circuit after riichi. Closed only: 1 han."),
            GameRoomRules.translate("- Menzen tsumo: closed-hand self-draw. Closed only: 1 han."),
            GameRoomRules.translate("- Tanyao: only numbered 2 to 8, without honours. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Yakuhai: each dragon pung or kong separately. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Seat wind pung or kong. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Round wind pung or kong; matching seat wind gives 2 han in total. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Haitei: win on the last ordinary wall draw. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Houtei: win on the last discard. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Rinshan: win on the replacement draw after a kong. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Chankan: robbing a kong. Closed: 1 han; open: 1 han."),
            GameRoomRules.translate("- Pinfu: four chows, a non-value pair and a two-sided wait. Closed only: 1 han."),
            GameRoomRules.translate("- Iipeikou: two identical chows in one suit. Closed only: 1 han."),
            GameRoomRules.translate("- Ryanpeikou: two pairs of identical chows; replaces iipeikou. Closed only: 3 han."),
            GameRoomRules.translate("- Chiitoitsu: seven distinct pairs; four identical tiles cannot count as two pairs. Closed only: 2 han."),
            GameRoomRules.translate("- Toitoi: four pungs or kongs and a pair. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Sanankou: three concealed pungs or kongs; the fourth set may be open. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Sankantsu: three kongs. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Shousangen: two dragon pungs or kongs and a pair of the third; both dragon yakuhai also count. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Sanshoku doujun: the same chow in all three suits. Closed: 2 han; open: 1 han."),
            GameRoomRules.translate("- Sanshoku doukou: pungs of the same number in all three suits. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Ittsu: chows 123, 456 and 789 in one suit. Closed: 2 han; open: 1 han."),
            GameRoomRules.translate("- Chanta: every set and pair contains a terminal or honour, with both chows and honours present. Closed: 2 han; open: 1 han."),
            GameRoomRules.translate("- Junchan: every set and pair contains a 1 or 9, with chows and no honours. Closed: 3 han; open: 2 han."),
            GameRoomRules.translate("- Honroutou: only terminals and honours. Closed: 2 han; open: 2 han."),
            GameRoomRules.translate("- Honitsu: one numbered suit and honours. Closed: 3 han; open: 2 han."),
            GameRoomRules.translate("- Chinitsu: one numbered suit without honours. Closed: 6 han; open: 5 han.")),
          rule_section(:table_riichi_dora, GameRoomRules.translate("Riichi \u2014 bonus han from dora"),
            GameRoomRules.translate("Dora add 1 han for each owned dora tile, but only to a hand with a real yaku. Dora are not yaku. An indicator points to the next tile in its cycle; every copy in the hand or own sets counts. After accepted riichi, hidden ura-dora may add to the final win; the pre-win preview does not reveal them.")),
          rule_section(:table_riichi_yakuman, GameRoomRules.translate("Riichi \u2014 complete yakuman reference"),
            GameRoomRules.translate("Each entry below awards 1 yakuman and replaces ordinary han and fu. Different compatible yakuman can stack. This version does not double a yakuman for a special wait or for big four winds."),
            GameRoomRules.translate("- 1 yakuman \u2014 Thirteen orphans: all terminals and honours plus one duplicate; closed hand."),
            GameRoomRules.translate("- 1 yakuman \u2014 Four concealed pungs or kongs: a discard win must complete the pair."),
            GameRoomRules.translate("- 1 yakuman \u2014 Big three dragons: pungs or kongs of all three dragons."),
            GameRoomRules.translate("- 1 yakuman \u2014 Big four winds: four wind pungs or kongs."),
            GameRoomRules.translate("- 1 yakuman \u2014 Little four winds: three wind pungs or kongs and a pair of the fourth."),
            GameRoomRules.translate("- 1 yakuman \u2014 All honours: only winds and dragons."),
            GameRoomRules.translate("- 1 yakuman \u2014 All terminals: only 1s and 9s."),
            GameRoomRules.translate("- 1 yakuman \u2014 All green: only Bamboo 2, 3, 4, 6, 8 and green dragons."),
            GameRoomRules.translate("- 1 yakuman \u2014 Four kongs and a pair."),
            GameRoomRules.translate("- 1 yakuman \u2014 Nine gates: closed single-suit hand, 1112345678999 plus one extra tile of that suit."),
            GameRoomRules.translate("Heavenly and earthly hands are not currently awarded during play. Do not add a special opening-win bonus for them.")),
          rule_section(:table_fu, GameRoomRules.translate("Riichi: fu for sets and waits"),
            GameRoomRules.translate("Han measure yaku and bonuses; fu measure features of the hand\u2019s construction. A chow gives 0 fu. An ordinary pair also gives 0; a dragon, seat-wind or round-wind pair gives 2. This game still awards 2 fu when the same wind is both your seat and the round wind."),
            GameRoomRules.translate("Pung and kong values depend on exposure and tile type:"),
            GameRoomRules.translate("- Pung of simples, numbers 2\u20138: exposed 2 fu, concealed 4 fu."),
            GameRoomRules.translate("- Pung of terminals or honors: exposed 4 fu, concealed 8 fu."),
            GameRoomRules.translate("- Kong of simples: exposed 8 fu, concealed 16 fu."),
            GameRoomRules.translate("- Kong of terminals or honors: exposed 16 fu, concealed 32 fu."),
            GameRoomRules.translate("A pung completed by the winning discard counts as exposed for fu. Other pungs held in your hand stay concealed. Adding a fourth tile to an exposed pung makes an exposed kong."),
            GameRoomRules.translate("Ordinary calculation starts at 20 fu. A closed discard win adds 10; self-draw adds 2. A pair wait, closed wait or edge wait adds 2. Edge means waiting for 3 with 1\u20132, or 7 with 8\u20139; a closed wait means, for example, 5 with 4\u20136. A two-sided wait such as 3 or 6 with 4\u20135 adds no fu."),
            GameRoomRules.translate("Round the total up to a multiple of ten: 32 becomes 40. Seven pairs is always 25 fu. Pinfu self-draw is 20 fu without the extra 2 for self-draw. Any other hand that would have only 20 receives a minimum of 30."),
            GameRoomRules.translate("For example, 20 base, 10 for a closed discard win, 4 for a concealed pung of fives and 2 for a dragon pair total 36, rounded to 40 fu. You still need a yaku: fu alone cannot make the hand eligible to win.")),
          rule_section(:table_riichi_payments, GameRoomRules.translate("Riichi: converting han and fu to points"),
            GameRoomRules.translate("For an ordinary win the base is fu multiplied by 2 to the power of han plus 2, capped at 2000. With 1 han and 30 fu it is 30 times 8, or 240. Round each final payment up to hundreds."),
            GameRoomRules.translate("On a discard, a non-dealer winner receives four bases from the discarder; a dealer receives six. On self-draw, a non-dealer receives two bases from the dealer and one from each other player. When the dealer wins, everyone pays two bases."),
            GameRoomRules.translate("For 1 han 30 fu without bonuses, a non-dealer wins 1000 on a discard, or 500 from the dealer and 300 from each other opponent on self-draw, totaling 1100. A dealer wins 1500 on a discard or 500 from each opponent, also 1500."),
            GameRoomRules.translate("- Mangan: 5 han or reaching the base cap; this game also includes 3 han 60 fu and 4 han 30 fu. Discard payments are 8000 for a non-dealer or 12,000 for a dealer."),
            GameRoomRules.translate("- Haneman: 6\u20137 han, respectively 12,000 or 18,000 on a discard."),
            GameRoomRules.translate("- Baiman: 8\u201310 han, respectively 16,000 or 24,000."),
            GameRoomRules.translate("- Sanbaiman: 11\u201312 han, respectively 24,000 or 36,000."),
            GameRoomRules.translate("- Yakuman or at least 13 han: respectively 32,000 or 48,000. Multiple compatible yakuman multiply that payment."),
            GameRoomRules.translate("Each honba adds 300 to a discard payment or 100 from each opponent on self-draw. Riichi deposits are awarded to the winner in addition. Honba increases after a draw or dealer repeat and resets after another player wins.")),
          rule_section(:table_riichi_match, GameRoomRules.translate("Riichi \u2014 Hands and match length"),
            GameRoomRules.translate("The default is four players and East and South rounds, with 30,000 starting points each. Everyone completes a dealer period in East, then in South: at least eight hands, with dealer continuations adding more. Payments and accepted Riichi deposits change the balances during the match."),
            GameRoomRules.translate("The dealer repeats after a dealer win or an exhaustive draw with a tenpai dealer."),
            GameRoomRules.translate("On a wall draw, 3000 points move from noten to tenpai hands, unless everyone or nobody is tenpai. After each hand everyone confirms readiness. The selected rounds decide the end; this version does not stop early for a negative score or a leading final dealer. Highest final points wins, with tied highest scores a draw.")),
          rule_section(:table_riichi_variants, GameRoomRules.translate("Riichi \u2014 three-player variant and match length"),
            GameRoomRules.translate("Choose match length in the game options before play. The following shorter settings change how many hands the match contains, not the rules for completing a winning hand."),
            GameRoomRules.translate("One hand ends after one win or wall draw. East round gives each player a dealer period: at least four hands with four players or three in sanma. East and South gives two such rounds: at least eight or six hands. The dealer repeats after winning, or after a draw when tenpai, so the actual count may be larger."),
            GameRoomRules.translate("The seat wind follows the current dealer: East, South, West, then North with four players. The round wind stays East until everyone has completed a dealer period, then becomes South in a two-round match. Value-wind sets may therefore score differently later. Sanma removes characters 2\u20138 and does not provide a separate North extraction action in this version."),
            GameRoomRules.translate("In sanma you cannot claim Chow, but you may form sequences from your own numbered tiles."),
            GameRoomRules.translate("In sanma the absent fourth player does not pay, and that share is not redistributed. Self-draw can therefore earn less than with four players. Draw settlements divide 2000 between tenpai and noten players, instead of 3000 with four players.")),
          rule_section(:table_mcr_aim, GameRoomRules.translate("MCR \u2014 Aim and winning conditions"),
            GameRoomRules.translate("Four players try to finish a winning hand first. The usual shape is four sets and a pair, with at least 8 fan before flower bonuses. Fan are the value of compatible scoring patterns. A hand win earns a payment; the match winner is the player with the highest combined balance.")),
          rule_section(:table_mcr_terms, GameRoomRules.translate("MCR \u2014 How the terms work"),
            GameRoomRules.translate("You play against the other players. Tiles in your hand are yours to arrange into a winning pattern; you do not remove matching pairs from a layout as in Solitaire. A hand is one deal and its play. A match may contain many hands."),
            GameRoomRules.translate("- A tile is one piece, such as bamboo 5. Its kind is its suit and number, or its particular wind or dragon. There are four copies of each ordinary kind."),
            GameRoomRules.translate("- Suits are characters, bamboo and circles, numbered 1\u20139. Different suits do not mix in one sequence. Terminals are 1 and 9; simples are 2\u20138."),
            GameRoomRules.translate("- Honors are East, South, West and North winds, and white, green and red dragons. They have no number and cannot form a sequence."),
            GameRoomRules.translate("- A chow or chi is three consecutive numbers in one suit: bamboo 3, 4 and 5. Bamboo 3, circles 4 and bamboo 5 do not qualify. Nor do 8, 9 and 1 of one suit."),
            GameRoomRules.translate("- A pung, also written pong or pon, is three identical tiles, such as three red dragons. Three fives from different suits are not a pung."),
            GameRoomRules.translate("- A kong or kan is four identical tiles. You must declare it through the kong action; simply holding four copies does not declare a kong. It is one set, with an extra replacement draw."),
            GameRoomRules.translate("- A pair is two identical tiles. A set is a chow, pung or kong. An ordinary winning hand needs four sets and one pair, not merely several pairs or a large number of tiles of one suit."),
            GameRoomRules.translate("- The wall is the supply of tiles you draw from. Drawing adds a tile to your hand; discarding removes one tile from your hand and offers it to opponents."),
            GameRoomRules.translate("- A closed hand has no sets claimed from opponents. Claiming a chow, pung or exposed kong opens it. Sets formed entirely from your own tiles can stay concealed. A declared concealed kong keeps your hand closed."),
            GameRoomRules.translate("- A self-draw win uses the tile you have just drawn. A discard win uses an opponent\u2019s discarded tile to finish your hand. Claim Mahjong to win; do not discard the winning tile first."),
            GameRoomRules.translate("- A wait is a tile kind that would finish your hand. With bamboo 4\u20135 you might wait for bamboo 3 or 6. Being one tile from a complete shape is called tenpai. A complete shape must still satisfy this variant\u2019s scoring conditions."),
            GameRoomRules.translate("- MCR means Mahjong Competition Rules. Fan measure scoring patterns. You need at least 8 fan before flower bonuses. Fan are then used in the payment calculation; they are not the same as your total match score."),
            GameRoomRules.translate("- A scoring pattern describes a feature of the whole hand or its sets. Some patterns can combine; others already include a smaller pattern and exclude its extra points. Do not sum every name that seems to fit."),
            GameRoomRules.translate("- Flowers and seasons are exposed and replaced automatically. Each adds 1 fan to a valid win but does not help reach the required 8. A 7-fan hand plus a flower cannot win."),
            GameRoomRules.translate("- Seat wind is your role relative to the dealer; round wind is shared by everyone. A pung of your seat wind or round wind is a scoring pattern. Seasons are bonus tiles, unrelated to the four wind rounds.")),
          rule_section(:table_mcr_start, GameRoomRules.translate("MCR \u2014 Starting the hand"),
            GameRoomRules.translate("Balances start at zero; winning hands add payments and losing them subtracts payments."),
            GameRoomRules.translate("The dealer starts with 14 tiles and discards first. Everyone else starts with 13. On a normal turn, choose Draw a tile and press Enter. Drawing is an action; moving through the tile list does not draw.")),
          rule_section(:table_mcr_play, GameRoomRules.translate("MCR \u2014 Your first turns"),
            GameRoomRules.translate("Before your first discard, read your hand with Up and Down. Think of numbered tiles as possible sequences, identical tiles as possible pungs, and one pair as your eventual pair. You do not select all four sets in the interface: sets left in your hand are recognised when you declare a win."),
            GameRoomRules.translate("While you browse game fields, a new turn focuses Draw a tile. After drawing, focus moves to the newly drawn tile in your hand, marked just drawn. This does not discard it. You can move to another tile with the arrows or keep the new tile and discard an old one."),
            GameRoomRules.translate("To discard, find one tile in the available-to-discard list and press Enter. You lose that copy from your hand. If you hold several identical copies, discarding one does not remove the others."),
            GameRoomRules.translate("After another player discards, listen to the tile and read the response list. Pass means you do not claim that tile; it does not end your participation or concede the hand. If everyone passes, the next player draws. Passing several times does not mean you must draw each time: it may still be another player\u2019s turn."),
            GameRoomRules.translate("The first field describes the current situation. All available actions follow it: responses, Draw, Declare Mahjong, kong choices or Riichi when applicable. Your tile lists come after those actions. Tab and Shift+Tab move between fields; arrows choose within a list, and Enter confirms. An unavailable action is omitted."),
            GameRoomRules.translate("Read Exposed sets to inspect everyone\u2019s declared sets; each entry names its owner. Discards records which tiles each player has discarded. These fields help you see what is already used and what opponents may need. You can review them without submitting a move."),
            GameRoomRules.translate("If a tile completes an eligible winning hand, choose Declare Mahjong rather than discarding it or passing. The game checks both the shape and this variant\u2019s scoring requirements. If the wall runs out first, the hand is a draw; nobody wins merely for having the most nearly complete hand."),
            GameRoomRules.translate("Press S to hear the current points of every player. Press M to hear how many tiles remain in the wall for drawing. These are read-only announcements: they do not draw, discard or pass, and do not reveal other hands."),
            GameRoomRules.translate("W reads a legal winning hand value: fan or han and fu, and the points gained. Without a legal win it does not give a final hand value. Before a Riichi win it excludes hidden ura-dora, so the final value may be higher. U reads your exposed sets, Shift+U those of the other players, and R the hand number, winds and current situation. In Riichi, I reads dora indicators and tiles, your dora count, Riichi declarations, deposits, honba and your furiten restriction. These keys only read information.")),
          rule_section(:table_mcr_build, GameRoomRules.translate("MCR \u2014 What you must build to win"),
            GameRoomRules.translate("The normal shape is four sets and a pair; MCR also allows seven pairs, thirteen orphans and the knitted hands defined in the reference. You need at least 8 fan without flowers. When eligible, choose Declare Mahjong and press Enter. Each catalog entry gives its name, value and exposure requirement.")),
          rule_section(:table_mcr_claims, GameRoomRules.translate("MCR \u2014 Claiming tiles and declaring kongs"),
            GameRoomRules.translate("When another player discards, the response list offers only legal choices. Select Pass if you do not want the tile. To claim it, choose Chow, Pung, Kong or Declare Mahjong and press Enter. A chow may be claimed only from the player immediately before you. A pung or kong can use a discard from any opponent."),
            GameRoomRules.translate("A winning claim takes priority over a set claim; pung and kong take priority over chow. If several players can win on the same tile, the first in turn order after the discarder wins. The hand waits for every required response. After claiming chow or pung, discard without drawing; the claimed set stays exposed."),
            GameRoomRules.translate("After declaring a kong, draw a replacement tile before discarding. If you hold all four copies, the concealed-kong list lets you declare them together. You may also add your fourth tile to an exposed pung. Opponents can claim a win on that added tile before the kong is completed."),
            GameRoomRules.translate("Suppose you have two white dragons and a third is discarded. Pung exposes them and secures a 2-fan dragon pattern, but you still need the rest of your hand to reach 8. Claiming a tile changes which concealed-hand patterns remain available. A legal Pung button does not promise that your eventual hand will meet the winning minimum.")),
          rule_section(:table_mcr_sets, GameRoomRules.translate("MCR \u2014 using the 81-entry reference"),
            GameRoomRules.translate("The following 81 entries describe MCR scoring elements. A valid hand shape and at least 8 fan excluding flowers are required. A kong also qualifies wherever a pung of that kind is required. The three numbered suits are Characters, Dots and Bamboo; honours are winds and dragons."),
            GameRoomRules.translate("A closed hand has no sets claimed from discards; a declared concealed kong does not open it. A pung completed by the winning discard counts as exposed; other retained pungs remain concealed. A knitted set uses 147 in one suit, 258 in another and 369 in the third, in any suit assignment."),
            GameRoomRules.translate("Do not add every matching name without checking exclusions. A larger pattern can include a smaller one, and the same sets cannot be freely reused for compound bonuses. The game selects compatible patterns. Numbers in the exclusion list refer to MCR catalog entries, not a sequence of moves.")),
          rule_section(:table_mcr_fan_88, GameRoomRules.translate("MCR: 88 fan"),
            GameRoomRules.translate("- MCR 1: 88 fan \u2014 Big four winds: four wind pungs. Open or closed hand."),
            GameRoomRules.translate("- MCR 2: 88 fan \u2014 Big three dragons: three dragon pungs. Open or closed hand."),
            GameRoomRules.translate("- MCR 3: 88 fan \u2014 All green: only Bamboo 2, 3, 4, 6, 8 and green dragons. Open or closed hand."),
            GameRoomRules.translate("- MCR 4: 88 fan \u2014 Nine gates: concealed 1112345678999 in one suit, completed with another tile of that suit. Closed hand only."),
            GameRoomRules.translate("- MCR 5: 88 fan \u2014 Four kongs. Open or closed hand."),
            GameRoomRules.translate("- MCR 6: 88 fan \u2014 Seven consecutive pairs in one suit. Closed hand only."),
            GameRoomRules.translate("- MCR 7: 88 fan \u2014 Thirteen orphans: all different terminals and honours, plus one duplicate forming a pair. Closed hand only.")),
          rule_section(:table_mcr_fan_64, GameRoomRules.translate("MCR: 64 fan"),
            GameRoomRules.translate("- MCR 8: 64 fan \u2014 All terminals: only numbered 1s and 9s. Open or closed hand."),
            GameRoomRules.translate("- MCR 9: 64 fan \u2014 Little four winds: three wind pungs and a pair of the fourth wind. Open or closed hand."),
            GameRoomRules.translate("- MCR 10: 64 fan \u2014 Little three dragons: two dragon pungs and a pair of the third dragon. Open or closed hand."),
            GameRoomRules.translate("- MCR 11: 64 fan \u2014 All honours: only winds and dragons. Open or closed hand."),
            GameRoomRules.translate("- MCR 12: 64 fan \u2014 Four concealed pungs. All four pungs concealed."),
            GameRoomRules.translate("- MCR 13: 64 fan \u2014 Pure terminal chows: 123, 123, 789, 789 and pair 55, all in one suit. Open or closed hand.")),
          rule_section(:table_mcr_fan_48, GameRoomRules.translate("MCR: 48 fan"),
            GameRoomRules.translate("- MCR 14: 48 fan \u2014 Four identical chows in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 15: 48 fan \u2014 Four consecutive numbered pungs in one suit. Open or closed hand.")),
          rule_section(:table_mcr_fan_32, GameRoomRules.translate("MCR: 32 fan"),
            GameRoomRules.translate("- MCR 16: 32 fan \u2014 Four shifted chows in one suit: every shift is 1, or every shift is 2. Open or closed hand."),
            GameRoomRules.translate("- MCR 17: 32 fan \u2014 Three kongs. Open or closed hand."),
            GameRoomRules.translate("- MCR 18: 32 fan \u2014 All terminals and honours, with both types present. Open or closed hand.")),
          rule_section(:table_mcr_fan_24, GameRoomRules.translate("MCR: 24 fan"),
            GameRoomRules.translate("- MCR 19: 24 fan \u2014 Seven pairs. Closed hand only."),
            GameRoomRules.translate("- MCR 20: 24 fan \u2014 Greater honours and knitted tiles: all seven honours and seven different tiles from a knitted set. Closed hand only."),
            GameRoomRules.translate("- MCR 21: 24 fan \u2014 All even pungs: pungs or kongs and a pair, using only 2, 4, 6 and 8. Open or closed hand."),
            GameRoomRules.translate("- MCR 22: 24 fan \u2014 Full flush: one numbered suit without honours. Open or closed hand."),
            GameRoomRules.translate("- MCR 23: 24 fan \u2014 Three identical chows in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 24: 24 fan \u2014 Three consecutive numbered pungs in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 25: 24 fan \u2014 Only numbers 7 to 9. Open or closed hand."),
            GameRoomRules.translate("- MCR 26: 24 fan \u2014 Only numbers 4 to 6. Open or closed hand."),
            GameRoomRules.translate("- MCR 27: 24 fan \u2014 Only numbers 1 to 3. Open or closed hand.")),
          rule_section(:table_mcr_fan_16, GameRoomRules.translate("MCR: 16 fan"),
            GameRoomRules.translate("- MCR 28: 16 fan \u2014 Pure straight: 123, 456 and 789 in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 29: 16 fan \u2014 Three-suited terminal chows: 123 and 789 in each of two suits, pair 55 in the third. Open or closed hand."),
            GameRoomRules.translate("- MCR 30: 16 fan \u2014 Three shifted chows in one suit, with equal steps of 1 or 2. Open or closed hand."),
            GameRoomRules.translate("- MCR 31: 16 fan \u2014 Every set and the pair contain a numbered 5. Open or closed hand."),
            GameRoomRules.translate("- MCR 32: 16 fan \u2014 Three pungs of the same number, one in each suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 33: 16 fan \u2014 Three concealed pungs. These three pungs concealed; the fourth set may be exposed.")),
          rule_section(:table_mcr_fan_12, GameRoomRules.translate("MCR: 12 fan"),
            GameRoomRules.translate("- MCR 34: 12 fan \u2014 Lesser honours and knitted tiles: 14 different tiles chosen from all seven honours and a nine-tile knitted set. Closed hand only."),
            GameRoomRules.translate("- MCR 35: 12 fan \u2014 Knitted straight: 147, 258 and 369, each group in a different suit, plus a set and a pair. The nine knitted tiles concealed; the additional set may be exposed."),
            GameRoomRules.translate("- MCR 36: 12 fan \u2014 Only numbers 6 to 9. Open or closed hand."),
            GameRoomRules.translate("- MCR 37: 12 fan \u2014 Only numbers 1 to 4. Open or closed hand."),
            GameRoomRules.translate("- MCR 38: 12 fan \u2014 Three pungs of different winds. Open or closed hand.")),
          rule_section(:table_mcr_fan_8, GameRoomRules.translate("MCR: 8 fan"),
            GameRoomRules.translate("- MCR 39: 8 fan \u2014 Mixed straight: 123, 456 and 789, each chow in a different suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 40: 8 fan \u2014 Reversible tiles: Dots 1 to 5, 8, 9; Bamboo 2, 4, 5, 6, 8, 9; white dragon. Open or closed hand."),
            GameRoomRules.translate("- MCR 41: 8 fan \u2014 Three identical chows, one in each suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 42: 8 fan \u2014 Three consecutive numbered pungs, each in a different suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 43: 8 fan \u2014 Chicken hand: no other scoring element, disregarding flowers; open hand won on a discard. Open hand; win on a discard."),
            GameRoomRules.translate("- MCR 44: 8 fan \u2014 Win on the last ordinary wall draw. Open or closed hand."),
            GameRoomRules.translate("- MCR 45: 8 fan \u2014 Win on the discard following the last ordinary wall draw. Open or closed hand."),
            GameRoomRules.translate("- MCR 46: 8 fan \u2014 Win on a replacement tile drawn after a kong, not a flower replacement. Open or closed hand."),
            GameRoomRules.translate("- MCR 47: 8 fan \u2014 Robbing a kong: win on the tile added to an exposed pung. Open or closed hand."),
            GameRoomRules.translate("- MCR 48: 8 fan \u2014 Two concealed kongs. Both kongs concealed; other sets may be exposed.")),
          rule_section(:table_mcr_fan_6, GameRoomRules.translate("MCR: 6 fan"),
            GameRoomRules.translate("- MCR 49: 6 fan \u2014 All pungs: four pungs or kongs and a pair. Open or closed hand."),
            GameRoomRules.translate("- MCR 50: 6 fan \u2014 Half flush: one numbered suit and honours, both present. Open or closed hand."),
            GameRoomRules.translate("- MCR 51: 6 fan \u2014 Three chows shifted by 1 each time, each in a different suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 52: 6 fan \u2014 All types: all three suits, at least one wind and one dragon. Open or closed hand."),
            GameRoomRules.translate("- MCR 53: 6 fan \u2014 Melded hand: all four sets claimed from discards, pair completed on a discard; no concealed kong. Open hand; win on a discard."),
            GameRoomRules.translate("- MCR 54: 6 fan \u2014 Two dragon pungs. Open or closed hand.")),
          rule_section(:table_mcr_fan_4, GameRoomRules.translate("MCR: 4 fan"),
            GameRoomRules.translate("- MCR 55: 4 fan \u2014 Outside hand: every set and the pair contain a terminal or honour. Open or closed hand."),
            GameRoomRules.translate("- MCR 56: 4 fan \u2014 Fully concealed hand won by self-draw. Closed hand only."),
            GameRoomRules.translate("- MCR 57: 4 fan \u2014 Two exposed kongs. Both kongs exposed."),
            GameRoomRules.translate("- MCR 58: 4 fan \u2014 Last of its kind: the other three identical tiles are already publicly visible. Open or closed hand.")),
          rule_section(:table_mcr_fan_2, GameRoomRules.translate("MCR: 2 fan"),
            GameRoomRules.translate("- MCR 59: 2 fan \u2014 Dragon pung. Open or closed hand."),
            GameRoomRules.translate("- MCR 60: 2 fan \u2014 Round wind pung. Open or closed hand."),
            GameRoomRules.translate("- MCR 61: 2 fan \u2014 Seat wind pung. Open or closed hand."),
            GameRoomRules.translate("- MCR 62: 2 fan \u2014 Concealed hand won on a discard; concealed kongs are allowed. Closed hand only."),
            GameRoomRules.translate("- MCR 63: 2 fan \u2014 All chows: four chows and a numbered pair, without honours. Open or closed hand."),
            GameRoomRules.translate("- MCR 64: 2 fan \u2014 Four identical tiles used outside a declared kong. Open or closed hand. For each tile kind separately."),
            GameRoomRules.translate("- MCR 65: 2 fan \u2014 Two pungs of the same number in different suits. Open or closed hand."),
            GameRoomRules.translate("- MCR 66: 2 fan \u2014 Two concealed pungs. These two pungs concealed; other sets may be exposed."),
            GameRoomRules.translate("- MCR 67: 2 fan \u2014 One concealed kong. This kong concealed; other sets may be exposed."),
            GameRoomRules.translate("- MCR 68: 2 fan \u2014 All simples: only numbers 2 to 8, without honours. Open or closed hand.")),
          rule_section(:table_mcr_fan_1, GameRoomRules.translate("MCR: 1 fan"),
            GameRoomRules.translate("- MCR 69: 1 fan \u2014 Two identical chows in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 70: 1 fan \u2014 Two matching chows in different suits. Open or closed hand."),
            GameRoomRules.translate("- MCR 71: 1 fan \u2014 Short straight: two chows making six consecutive numbers in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 72: 1 fan \u2014 Two terminal chows: 123 and 789 in one suit. Open or closed hand."),
            GameRoomRules.translate("- MCR 73: 1 fan \u2014 Pung of 1s, 9s or a wind that is neither seat nor round wind. Open or closed hand."),
            GameRoomRules.translate("- MCR 74: 1 fan \u2014 One exposed kong. This kong exposed."),
            GameRoomRules.translate("- MCR 75: 1 fan \u2014 One voided suit: exactly two numbered suits are present and the third is absent; honours are allowed. Open or closed hand."),
            GameRoomRules.translate("- MCR 76: 1 fan \u2014 No honours. Open or closed hand."),
            GameRoomRules.translate("- MCR 77: 1 fan \u2014 Edge wait: 12 waiting for 3, or 89 waiting for 7; the only winning tile kind. Open or closed hand."),
            GameRoomRules.translate("- MCR 78: 1 fan \u2014 Closed wait: a middle tile, such as 24 waiting for 3; the only winning tile kind. Open or closed hand."),
            GameRoomRules.translate("- MCR 79: 1 fan \u2014 Pair wait: the only winning tile kind completes the pair. Open or closed hand."),
            GameRoomRules.translate("- MCR 80: 1 fan \u2014 Self-draw: draw the winning tile yourself. Open or closed hand."),
            GameRoomRules.translate("- MCR 81: 1 fan \u2014 Each flower or season: one extra point, excluded from the eight-fan minimum. Open or closed hand.")),
          rule_section(:table_mcr_mixed_kongs, GameRoomRules.translate("MCR \u2014 two mixed kongs: 6 fan"),
            GameRoomRules.translate("Two mixed kongs \u2014 6 fan: one exposed and one concealed kong. This replaces the individual kong bonuses. This version distinguishes that combination in addition to the standard 81 named entries.")),
          rule_section(:table_mcr_exclusions, GameRoomRules.translate("MCR \u2014 bonuses included in larger patterns"),
            GameRoomRules.translate("Do not add every matching name without checking exclusions. A larger pattern can include a smaller one, and the same sets cannot be freely reused for compound bonuses. The game selects compatible patterns. Numbers in the exclusion list refer to MCR catalog entries, not a sequence of moves."),
            GameRoomRules.translate("- Do not add to entry 1: 9, 38, 49, 60, 61, 73."),
