      def localized_rule_sections
        case GameRoomLocalization.primary_language
        when "cs"
          [
            rule_section(:table_aim, "Mahjong \u2014 c\u00EDl hry",
              "Ve v\u00FDchoz\u00EDm solitaire odeb\u00EDr\u00E1\u0161 odpov\u00EDdaj\u00EDc\u00ED p\u00E1ry a vyhraje\u0161 vypr\u00E1zdn\u011Bn\u00EDm rozlo\u017Een\u00ED. Hong Kong, Riichi a MCR jsou samostatn\u00E9 hry proti ostatn\u00EDm: sestavuje\u0161 v\u00EDt\u011Bznou ruku a z\u00EDsk\u00E1v\u00E1\u0161 body. Ka\u017Ed\u00E1 m\u00E1 n\u00ED\u017Ee vlastn\u00ED \u00FAplnou \u010D\u00E1st od c\u00EDle a pojm\u016F.",
              "Zvuky rozli\u0161uj\u00ED rozd\u00E1n\u00ED, dobr\u00E1n\u00ED a odhozen\u00ED kamene, vylo\u017Een\u00ED sestavy a konec rozd\u00E1n\u00ED. V pasi\u00E1nsu zazn\u00ED tak\u00E9 odebr\u00E1n\u00ED p\u00E1ru a vr\u00E1cen\u00ED tahu. Pasov\u00E1n\u00ED a proch\u00E1zen\u00ED kamen\u016F jsou tich\u00E9. Slovn\u00ED popis d\u00E1l uv\u00E1d\u00ED druh kamene a v\u00FDsledek.",
              "P\u0159i odpov\u011Bdi na k\u00E1men kl\u00E1vesa D p\u0159e\u010Dte k\u00E1men, kter\u00E9ho se t\u00FDk\u00E1 Pas, Chow, Pung, Kong nebo Mahjong. Nezm\u011Bn\u00ED ani nepotvrd\u00ED volbu. V pasi\u00E1nsu D d\u00E1l \u010Dte sou\u0159adnice.",
              "W stru\u010Dn\u011B p\u0159e\u010Dte aktu\u00E1ln\u00ED sou\u010Det rozpoznan\u00FDch pr\u00E9mi\u00ED a d\u016Fvody. U skryt\u00FDch sad p\u0159ipomene, \u017Ee je mus\u00EDte zachovat skryt\u00E9. V MCR dva, t\u0159i a \u010Dty\u0159i skryt\u00E9 pungy d\u00E1vaj\u00ED 2, 16 a 64 fan; tyto pr\u00E9mie se nahrazuj\u00ED, nes\u010D\u00EDtaj\u00ED. Nejde o \u00FAplnou hodnotu nedokon\u010Den\u00E9 ruky. Kv\u011Btiny v MCR a dora v Riichi jsou zvl\u00E1\u0161\u0165. Pokud lze vyhl\u00E1sit Mahjong, W p\u0159e\u010Dte \u00FAplnou hodnotu v\u00FDhry. Volba n\u00E1hledu pod W je standardn\u011B Ano; Ne ponech\u00E1 jen hodnotu leg\u00E1ln\u00ED v\u00FDhry. Bodov\u00E1n\u00ED se nem\u011Bn\u00ED.",
              "Po v\u00FDh\u0159e Hodnota ruky uv\u00E1d\u00ED skute\u010Dn\u011B p\u0159iznan\u00E9 pr\u00E9mie bez nahrazen\u00FDch vzor\u016F. V MCR odd\u011Bluje fan za ruku od kv\u011Btin a ro\u010Dn\u00EDch obdob\u00ED a uv\u00E1d\u00ED jejich sou\u010Det pro platbu. Dodate\u010Dn\u00E9 body se nepo\u010D\u00EDtaj\u00ED do minima 8 fan."),
            rule_section(:aim, "Solitaire \u2014 pojmy a c\u00EDl",
              "Odstra\u0148 v\u0161ech 144 kamen\u016F po shodn\u00FDch dvojic\u00EDch. Hraje\u0161 s\u00E1m a vyhraje\u0161 odebr\u00E1n\u00EDm posledn\u00ED dvojice.",
              "V solitaire je rozlo\u017Een\u00ED cel\u00E1 sestava kamen\u016F na plo\u0161e. P\u00E1r jsou dva odpov\u00EDdaj\u00EDc\u00ED kusy, vrstva v\u00FD\u0161kov\u00E1 \u00FArove\u0148, \u0159\u00E1dky vedou vodorovn\u011B a sloupce svisle. Voln\u00FD k\u00E1men nem\u00E1 nic nad sebou a m\u00E1 alespo\u0148 jeden otev\u0159en\u00FD bok, lev\u00FD nebo prav\u00FD. I viditeln\u00FD k\u00E1men m\u016F\u017Ee b\u00FDt z obou bok\u016F blokov\u00E1n.",
              "V t\u00E9to variant\u011B netvo\u0159\u00ED\u0161 chow, pungy ani kongy a nepo\u010D\u00EDt\u00E1\u0161 fan, han \u010Di yaku. Tyto pojmy pat\u0159\u00ED hr\u00E1m proti ostatn\u00EDm. Tady vyhraje\u0161 odebr\u00E1n\u00EDm v\u0161ech p\u00E1r\u016F z plochy."),
            rule_section(:tiles, "Solitaire: Shodn\u00E9 a voln\u00E9 kameny",
              "Dvojici tvo\u0159\u00ED dva kameny stejn\u00E9 barvy a \u010D\u00EDsla, dva stejn\u00E9 v\u011Btry nebo dva stejn\u00ED draci. Libovoln\u00E9 dv\u011B kv\u011Btiny se shoduj\u00ED, stejn\u011B jako libovoln\u00E1 dv\u011B ro\u010Dn\u00ED obdob\u00ED. Kv\u011Btinu nelze spojit s ro\u010Dn\u00EDm obdob\u00EDm.",
              "Oba kameny mus\u00ED b\u00FDt voln\u00E9: nesm\u00ED je p\u0159ekr\u00FDvat k\u00E1men shora a ka\u017Ed\u00FD mus\u00ED m\u00EDt volnou levou nebo pravou stranu. I viditeln\u00FD k\u00E1men m\u016F\u017Ee b\u00FDt z obou stran zablokovan\u00FD. U zakryt\u00FDch kamen\u016F se jejich hodnota neprozrazuje."),
            rule_section(:play, "Solitaire: V\u00FDb\u011Br dvojice",
              "V poli Kameny v rozlo\u017Een\u00ED p\u0159ech\u00E1z\u00ED\u0161 \u0161ipkami vlevo a vpravo mezi sloupci, nahoru a dol\u016F mezi \u0159\u00E1dky. Kl\u00E1vesy 1, 2 a 3 p\u0159ep\u00EDnaj\u00ED vrstvy Teras; ploch\u00E9 rozlo\u017Een\u00ED m\u00E1 jen vrstvu 1. Vrstva ur\u010Duje v\u00FD\u0161ku, nikoli \u0159\u00E1dek. Kl\u00E1vesa D p\u0159e\u010Dte vrstvu, \u0159\u00E1dek a sloupec, po\u010D\u00EDtan\u00E9 zvl\u00E1\u0161\u0165 v ka\u017Ed\u00E9 vrstv\u011B.",
              "U odkryt\u00E9ho kamene usly\u0161\u00ED\u0161, zda je voln\u00FD zleva, zprava \u010Di z obou stran, nebo blokovan\u00FD z obou stran. Zakryt\u00FD k\u00E1men neprozrad\u00ED sv\u016Fj druh. Po odebr\u00E1n\u00ED z\u016Fst\u00E1vaj\u00ED pr\u00E1zdn\u00E1 pole, tak\u017Ee sou\u0159adnice ostatn\u00EDch kamen\u016F se nem\u011Bn\u00ED.",
              "Najdi voln\u00FD k\u00E1men a ozna\u010D jej Enterem. Potom najdi druh\u00FD voln\u00FD k\u00E1men, kter\u00FD k n\u011Bmu pat\u0159\u00ED, a Enterem oba odeber. Prvn\u00ED ozna\u010Den\u00ED samo nic neodeb\u00EDr\u00E1. Pokud druh\u00FD k\u00E1men nepat\u0159\u00ED do p\u00E1ru, prvn\u00ED z\u016Fstane vybran\u00FD. V\u00FDb\u011Br zru\u0161\u00ED\u0161 dal\u0161\u00EDm Enterem na prvn\u00EDm kameni nebo kl\u00E1vesou Escape. Hra nenab\u00EDz\u00ED hotov\u00FD seznam p\u00E1r\u016F.",
              "Odebr\u00E1n\u00ED p\u00E1ru m\u016F\u017Ee uvolnit kameny pod n\u00EDm \u010Di vedle n\u011Bj. Zva\u017E, co tv\u016Fj tah odkryje. Nov\u00E9 rozlo\u017Een\u00ED m\u00E1 \u0159e\u0161en\u00ED, ale n\u011Bkter\u00E9 volby mohou v\u00E9st k situaci bez dal\u0161\u00EDho p\u00E1ru.",
              "P\u0159\u00EDklad: najdi voln\u00FD bambus 5 a Enterem jej ozna\u010D. Najdi druh\u00FD voln\u00FD bambus 5, t\u0159eba v jin\u00E9 vrstv\u011B, a stiskni Enter. Oba zmiz\u00ED. Je-li druh\u00E1 p\u011Btka zakryt\u00E1 \u010Di blokovan\u00E1, nejprve ji uvolni odebr\u00E1n\u00EDm jin\u00FDch p\u00E1r\u016F.",
              "Je-li stejn\u00FDch kamen\u016F v\u00EDce, zva\u017E, kter\u00E9 kusy odebrat. Krajn\u00ED k\u00E1men m\u016F\u017Ee uvolnit souseda, horn\u00ED odkryje spodn\u00ED. Ne ka\u017Ed\u00FD dostupn\u00FD p\u00E1r vede k \u0159e\u0161en\u00ED. Vr\u00E1cen\u00ED posledn\u00EDho p\u00E1ru umo\u017En\u00ED zkusit jinou cestu."),
            rule_section(:ending, "Solitaire: Vr\u00E1cen\u00ED tahu a konec hry",
              "Tla\u010D\u00EDtko pro vr\u00E1cen\u00ED posledn\u00ED dvojice obnov\u00ED dva naposledy odebran\u00E9 kameny. Opakovan\u011B m\u016F\u017Ee\u0161 vracet p\u0159edchoz\u00ED tahy a\u017E k po\u010D\u00E1te\u010Dn\u00EDmu rozlo\u017Een\u00ED.",
              "Pr\u016Fb\u011Bh ukazuje po\u010Det odebran\u00FDch dvojic a zb\u00FDvaj\u00EDc\u00EDch kamen\u016F. Sk\u00F3re je po\u010Det odebran\u00FDch dvojic, nejv\u00FD\u0161e 72. Pokud \u017E\u00E1dn\u00E1 dvojice nen\u00ED dostupn\u00E1, vra\u0165 tah a zkus jinou cestu, nebo ukon\u010Di hlavolam p\u0159\u00EDslu\u0161n\u00FDm tla\u010D\u00EDtkem. P\u0159ed\u010Dasn\u00E9 ukon\u010Den\u00ED nen\u00ED v\u00FDhra.",
              "S p\u0159e\u010Dte sk\u00F3re, tedy po\u010Det odebran\u00FDch p\u00E1r\u016F. M po\u010Det zb\u00FDvaj\u00EDc\u00EDch kamen\u016F. Nov\u00E9 rozlo\u017Een\u00ED m\u00E1 144 kamen\u016F, po odebr\u00E1n\u00ED p\u00E1ru 142."),
            rule_section(:solitaire_points, "Pasij\u00E1ns \u2014 body za odstran\u011Bn\u00E9 p\u00E1ry",
              "Pasij\u00E1ns nepou\u017E\u00EDv\u00E1 fan, han ani fu. Sk\u00F3re je po\u010Det odstran\u011Bn\u00FDch p\u00E1r\u016F: ka\u017Ed\u00FD d\u00E1v\u00E1 1 bod a vr\u00E1cen\u00ED tahu tento bod odebere. Vyhraje\u0161 odstran\u011Bn\u00EDm v\u0161ech 144 kamen\u016F, tedy 72 p\u00E1r\u016F."),
            rule_section(:layout, "Solitaire: Volba rozlo\u017Een\u00ED",
              "V\u00FDchoz\u00ED terasov\u00E9 rozlo\u017Een\u00ED m\u00E1 n\u011Bkolik vrstev. Ploch\u00E9 rozlo\u017Een\u00ED m\u00E1 jedinou vrstvu. Pravidla shody i po\u017Eadavek voln\u00E9 lev\u00E9 nebo prav\u00E9 strany plat\u00ED v obou p\u0159\u00EDpadech."),
            rule_section(:table_hk_aim, "Hong Kong \u2014 C\u00EDl a podm\u00EDnky v\u00FDhry",
              "\u010Cty\u0159i hr\u00E1\u010Di sout\u011B\u017E\u00ED o prvn\u00ED dokon\u010Denou v\u00EDt\u011Bznou ruku. B\u011B\u017En\u00FD tvar jsou \u010Dty\u0159i sestavy a p\u00E1r nejm\u00E9n\u011B za 3 fan; fan m\u011B\u0159\u00ED bodovou hodnotu ruky. Z\u00E1pas vyhraje nejvy\u0161\u0161\u00ED sou\u010Det bod\u016F. N\u00E1sleduj\u00EDc\u00ED pojmy vysv\u011Btluj\u00ED sestavy i jednotky p\u0159ed prvn\u00EDm tahem."),
            rule_section(:table_hk_terms, "Hong Kong \u2014 V\u00FDznam pojm\u016F",
              "Hraje\u0161 proti ostatn\u00EDm. Ze sv\u00FDch kamen\u016F sestavuje\u0161 v\u00EDt\u011Bznou ruku; neodeb\u00EDr\u00E1\u0161 p\u00E1ry z rozlo\u017Een\u00ED jako v solitaire. Ruka jsou tvoje kameny, rozd\u00E1n\u00ED je hra od jejich rozd\u00E1n\u00ED po v\u00FDhru nebo rem\u00EDzu. Z\u00E1pas m\u016F\u017Ee m\u00EDt v\u00EDce rozd\u00E1n\u00ED.",
              "- K\u00E1men je jeden kus, nap\u0159\u00EDklad bambus 5. Druh ur\u010Duje barva a \u010D\u00EDslo nebo konkr\u00E9tn\u00ED v\u00EDtr \u010Di drak. Od ka\u017Ed\u00E9ho b\u011B\u017En\u00E9ho druhu jsou \u010Dty\u0159i kusy.",
              "- Barvy jsou znaky, bambusy a kruhy, s \u010D\u00EDsly 1\u20139. V jedn\u00E9 postupce se barvy nem\u00EDchaj\u00ED. Jedni\u010Dky a dev\u00EDtky jsou krajn\u00ED kameny, \u010D\u00EDsla 2\u20138 prost\u0159edn\u00ED.",
              "- \u010Cestn\u00E9 kameny jsou v\u011Btry V\u00FDchod, Jih, Z\u00E1pad a Sever a draci b\u00EDl\u00FD, zelen\u00FD a \u010Derven\u00FD. Nemaj\u00ED \u010D\u00EDslo a netvo\u0159\u00ED postupky.",
              "- Chow neboli chi jsou t\u0159i po sob\u011B jdouc\u00ED \u010D\u00EDsla stejn\u00E9 barvy, nap\u0159\u00EDklad bambusy 3, 4 a 5. Bambus 3, kruh 4 a bambus 5 chow netvo\u0159\u00ED; ani \u010D\u00EDsla 8, 9 a 1 stejn\u00E9 barvy.",
              "- Pung, tak\u00E9 pong \u010Di pon, jsou t\u0159i stejn\u00E9 kameny, nap\u0159\u00EDklad t\u0159i \u010Derven\u00ED draci. T\u0159i p\u011Btky r\u016Fzn\u00FDch barev pung netvo\u0159\u00ED.",
              "- Kong neboli kan jsou \u010Dty\u0159i stejn\u00E9 kameny. Mus\u00ED\u0161 jej vyhl\u00E1sit p\u0159\u00EDslu\u0161nou volbou; samotn\u00E9 dr\u017Een\u00ED \u010Dty\u0159 kus\u016F kong nevyhl\u00E1s\u00ED. Po\u010D\u00EDt\u00E1 se jako jedna sestava a n\u00E1sleduje n\u00E1hradn\u00ED dobr\u00E1n\u00ED.",
              "- P\u00E1r jsou dva stejn\u00E9 kameny. Sestava je chow, pung nebo kong. B\u011B\u017En\u00E1 v\u00EDt\u011Bzn\u00E1 ruka pot\u0159ebuje \u010Dty\u0159i sestavy a jeden p\u00E1r, ne jen n\u011Bkolik p\u00E1r\u016F nebo mnoho kamen\u016F jedn\u00E9 barvy.",
              "- Ze\u010F je z\u00E1soba kamen\u016F k dob\u00EDr\u00E1n\u00ED. Dobran\u00FD k\u00E1men p\u0159id\u00E1\u0161 do ruky; odhozen\u00EDm jeden odevzd\u00E1\u0161 a soupe\u0159i jej mohou p\u0159evz\u00EDt.",
              "- Zav\u0159en\u00E1 ruka nem\u00E1 sestavy z\u00EDskan\u00E9 od soupe\u0159e. P\u0159evzet\u00ED chow, pungu nebo otev\u0159en\u00E9ho kongu ji otev\u0159e. Sestavy z vlastn\u00EDch kamen\u016F mohou z\u016Fstat v ruce. Skryt\u00FD kong ruku neotev\u00EDr\u00E1.",
              "- V\u00FDhra z dobr\u00E1n\u00ED pou\u017E\u00EDv\u00E1 pr\u00E1v\u011B dobran\u00FD k\u00E1men. V\u00FDhra na odhoz dokon\u010D\u00ED ruku soupe\u0159ov\u00FDm kamenem. Vyhraj volbou Vyhl\u00E1sit Mahjong; v\u00EDt\u011Bzn\u00FD k\u00E1men nejprve neodhazuj.",
              "- \u010Cek\u00E1n\u00ED je druh kamene, kter\u00FD by ruku dokon\u010Dil. S bambusy 4\u20135 m\u016F\u017Ee\u0161 \u010Dekat na 3 nebo 6. Tenpai znamen\u00E1, \u017Ee k \u00FApln\u00E9mu tvaru chyb\u00ED jeden k\u00E1men. K leg\u00E1ln\u00ED v\u00FDh\u0159e mus\u00ED\u0161 splnit i bodovou podm\u00EDnku varianty.",
              "- Fan jsou jednotky hodnoty ruky za ur\u010Dit\u00E9 vzory a okolnosti v\u00FDhry. V tomto profilu pot\u0159ebuje\u0161 alespo\u0148 3 fan. P\u0159ev\u00E1d\u011Bj\u00ED se na body z\u00E1pasu; 3 fan tedy neznamenaj\u00ED zisk pouh\u00FDch 3 bod\u016F.",
              "- Vlastn\u00ED v\u00EDtr je tvoje role v rozd\u00E1n\u00ED: rozd\u00E1vaj\u00EDc\u00ED m\u00E1 V\u00FDchod, d\u00E1le Jih, Z\u00E1pad a Sever. V\u00EDtr kola plat\u00ED pro cel\u00FD st\u016Fl. Pung vlastn\u00EDho v\u011Btru nebo v\u011Btru kola m\u016F\u017Ee bodovat; pouh\u00FD p\u00E1r tuto pr\u00E9mii ned\u00E1v\u00E1.",
              "- Kv\u011Btiny a ro\u010Dn\u00ED obdob\u00ED jsou bonusov\u00E9 kameny. Hra je sama vylo\u017E\u00ED a nahrad\u00ED. Nenahrazuj\u00ED chow, pung ani z\u00E1v\u011Bre\u010Dn\u00FD p\u00E1r a neur\u010Duj\u00ED kola v\u011Btr\u016F."),
            rule_section(:table_hk_start, "Hong Kong \u2014 Za\u010D\u00E1tek rozd\u00E1n\u00ED",
              "\u00DA\u010Dty za\u010D\u00EDnaj\u00ED od nuly; v\u00FDhry body p\u0159id\u00E1vaj\u00ED a prohry odeb\u00EDraj\u00ED.",
              "Rozd\u00E1vaj\u00EDc\u00ED za\u010D\u00EDn\u00E1 se 14 kameny a nejprve odhazuje, ostatn\u00ED maj\u00ED 13. V b\u011B\u017En\u00E9m tahu zvol Dobrat k\u00E1men a stiskni Enter. Proch\u00E1zen\u00ED seznamu nic nedob\u00EDr\u00E1. Rozd\u00E1vaj\u00EDc\u00ED u\u017E m\u00E1 k\u00E1men nav\u00EDc a dal\u0161\u00ED dobr\u00E1n\u00ED na za\u010D\u00E1tku nehled\u00E1."),
            rule_section(:table_hk_play, "Hong Kong \u2014 Prvn\u00ED tahy krok za krokem",
              "P\u0159ed prvn\u00EDm odhozem si ruku projdi \u0161ipkami nahoru a dol\u016F. Hledej sousedn\u00ED \u010D\u00EDsla pro chow, stejn\u00E9 kameny pro pungy a jeden p\u00E1r na konec. Sestavy ponechan\u00E9 v ruce neozna\u010Duje\u0161 zvl\u00E1\u0161\u0165: hra je pozn\u00E1 p\u0159i vyhl\u00E1\u0161en\u00ED v\u00FDhry.",
              "Kdy\u017E proch\u00E1z\u00ED\u0161 hern\u00ED pole, nov\u00FD vlastn\u00ED tah zam\u011B\u0159\u00ED Dobrat k\u00E1men. Po dobr\u00E1n\u00ED p\u0159ejde fokus na nov\u00FD k\u00E1men s p\u0159\u00EDslu\u0161n\u00FDm ozna\u010Den\u00EDm. T\u00EDm se neodhazuje. \u0160ipkami m\u016F\u017Ee\u0161 p\u0159ej\u00EDt jinam, nov\u00FD k\u00E1men si nechat a odhodit star\u00FD.",
              "Pro odhoz vyber jeden k\u00E1men v seznamu povolen\u00FDch odhoz\u016F a stiskni Enter. Odevzd\u00E1\u0161 jen tento kus. Ze t\u0159\u00ED stejn\u00FDch kamen\u016F ti po odhozu jednoho z\u016Fstanou dva.",
              "Po ciz\u00EDm odhozu usly\u0161\u00ED\u0161 k\u00E1men a dostane\u0161 seznam odpov\u011Bd\u00ED. Pas znamen\u00E1 jen, \u017Ee tento k\u00E1men nechce\u0161; nevzd\u00E1v\u00E1\u0161 rozd\u00E1n\u00ED. Kdy\u017E v\u0161ichni daj\u00ED pas, dob\u00EDr\u00E1 dal\u0161\u00ED hr\u00E1\u010D. Ne\u017E p\u0159ijde tvoje dobr\u00E1n\u00ED, m\u016F\u017Ee\u0161 n\u011Bkolikr\u00E1t odpov\u00EDdat Pas.",
              "Prvn\u00ED pole popisuje situaci. Hned za n\u00EDm jsou v\u0161echny dostupn\u00E9 akce: odpov\u011Bdi, dobr\u00E1n\u00ED, Mahjong, kong \u010Di Riichi, pokud je varianta pou\u017E\u00EDv\u00E1. Pak n\u00E1sleduj\u00ED tvoje kameny. Tab a Shift+Tab m\u011Bn\u00ED pole, \u0161ipky polo\u017Eku a Enter potvrzuje. Nedostupn\u00E1 akce se nezobrazuje.",
              "Ve Vylo\u017Een\u00FDch sestav\u00E1ch najde\u0161 sestavy v\u0161ech hr\u00E1\u010D\u016F se jm\u00E9ny vlastn\u00EDk\u016F. Odhozen\u00E9 kameny ukazuj\u00ED, kdo co odhodil. Pom\u00E1haj\u00ED zjistit, co u\u017E bylo pou\u017Eito a co mohou soupe\u0159i hledat. \u010Cten\u00ED t\u011Bchto pol\u00ED neprov\u00E1d\u00ED tah.",
              "Dokon\u010D\u00ED-li k\u00E1men ruku spl\u0148uj\u00EDc\u00ED podm\u00EDnky, zvol Mahjong m\u00EDsto odhozu \u010Di pasu. Hra ov\u011B\u0159\u00ED tvar i bodov\u00E9 po\u017Eadavky. Dojde-li d\u0159\u00EDv ze\u010F, nastane rem\u00EDza; nejbli\u017E\u0161\u00ED nedokon\u010Den\u00E1 ruka t\u00EDm automaticky nevyhraje.",
              "S p\u0159e\u010Dte pr\u016Fb\u011B\u017En\u00E9 body v\u0161ech hr\u00E1\u010D\u016F. M po\u010Det kamen\u016F zb\u00FDvaj\u00EDc\u00EDch k dobr\u00E1n\u00ED ve zdi. Jde jen o ozn\u00E1men\u00ED: nedob\u00EDraj\u00ED, neodhazuj\u00ED, ned\u00E1vaj\u00ED pas ani neodhaluj\u00ED ciz\u00ED ruce.",
              "W p\u0159e\u010Dte hodnotu platn\u00E9 v\u00FDhry: fan nebo han a fu a z\u00EDskan\u00E9 body. Bez platn\u00E9 v\u00FDhry neuv\u00E1d\u00ED kone\u010Dnou hodnotu ruky. P\u0159ed v\u00FDhrou v riichi nezahrnuje skryt\u00E9 ura-dora, tak\u017Ee kone\u010Dn\u00E1 hodnota m\u016F\u017Ee b\u00FDt vy\u0161\u0161\u00ED. U \u010Dte tv\u00E9 vylo\u017Een\u00E9 sestavy, Shift+U sestavy ostatn\u00EDch a R \u010D\u00EDslo rozd\u00E1n\u00ED, v\u011Btry a aktu\u00E1ln\u00ED situaci. V riichi I \u010Dte ukazatele a kameny dora, po\u010Det tv\u00FDch dora, hl\u00E1\u0161en\u00ED riichi, vklady, honba a tv\u00E9 omezen\u00ED furiten. Tyto kl\u00E1vesy pouze \u010Dtou informace."),
            rule_section(:table_hand, "Hong Kong \u2014 Co sestavit pro v\u00FDhru",
              "Sestav \u010Dty\u0159i \u010Dou, pungy nebo kongy a p\u00E1r, v\u010Detn\u011B vylo\u017Een\u00FDch i ponechan\u00FDch sestav. \u010Cou jsou t\u0159i po sob\u011B jdouc\u00ED \u010D\u00EDsla jedn\u00E9 barvy, pung t\u0159i stejn\u00E9 kameny, kong \u010Dty\u0159i a p\u00E1r dva. Pot\u0159ebuje\u0161 tak\u00E9 3 fan. P\u0159i spln\u011Bn\u00ED obou podm\u00EDnek zvol Vyhl\u00E1sit Mahjong a stiskni Enter. \u00DApln\u00FD p\u0159ehled bodov\u00E1n\u00ED je d\u00E1le; dobr\u00E1n\u00ED vhodn\u00E9ho kamene rozd\u00E1n\u00ED samo neukon\u010D\u00ED."),
            rule_section(:table_hk_claims, "Hong Kong \u2014 P\u0159eb\u00EDr\u00E1n\u00ED kamen\u016F a vyhla\u0161ov\u00E1n\u00ED kong\u016F",
              "Po odhozen\u00ED jin\u00FDm hr\u00E1\u010Dem seznam odpov\u011Bd\u00ED nab\u00EDdne jen povolen\u00E9 mo\u017Enosti. Pokud k\u00E1men nechce\u0161, zvol Pass. Jinak vyber Chow, Pung, Kong nebo ohl\u00E1\u0161en\u00ED mahjongu a stiskni Enter. Chow lze p\u0159evz\u00EDt jen od hr\u00E1\u010De bezprost\u0159edn\u011B p\u0159ed tebou. Pung \u010Di kong m\u016F\u017Ee vyu\u017E\u00EDt odhozen\u00ED kter\u00E9hokoli soupe\u0159e.",
              "V\u00FDhra m\u00E1 p\u0159ednost p\u0159ed p\u0159evzet\u00EDm do skupiny; pung a kong maj\u00ED p\u0159ednost p\u0159ed chow. Pokud na stejn\u00FD k\u00E1men vyhr\u00E1v\u00E1 v\u00EDce hr\u00E1\u010D\u016F, vyhraje prvn\u00ED v po\u0159ad\u00ED za odhazuj\u00EDc\u00EDm. Hra \u010Dek\u00E1 na v\u0161echny po\u017Eadovan\u00E9 odpov\u011Bdi. Po p\u0159evzet\u00ED chow \u010Di pungu odhazuje\u0161 bez dob\u00EDr\u00E1n\u00ED a skupina z\u016Fst\u00E1v\u00E1 odkryt\u00E1.",
              "Po ohl\u00E1\u0161en\u00ED kongu dober n\u00E1hradn\u00ED k\u00E1men a teprve potom odhazuj. Dr\u017E\u00ED\u0161-li v\u0161echny \u010Dty\u0159i kopie, m\u016F\u017Ee\u0161 je ohl\u00E1sit v seznamu skryt\u00FDch kong\u016F. \u010Ctvrt\u00FDm kamenem lze tak\u00E9 roz\u0161\u00ED\u0159it odkryt\u00FD pung. P\u0159ed dokon\u010Den\u00EDm takov\u00E9ho kongu mohou soupe\u0159i ohl\u00E1sit v\u00FDhru na p\u0159id\u00E1van\u00FD k\u00E1men.",
              "M\u00E1\u0161 dva \u010Derven\u00E9 draky a n\u011Bkdo odhod\u00ED t\u0159et\u00EDho: Pung jej p\u0159evezme a vylo\u017E\u00ED v\u0161echny t\u0159i. Potom odhod\u00ED\u0161 bez dobr\u00E1n\u00ED. S bambusy 4\u20135 m\u016F\u017Ee\u0161 vz\u00EDt 3 nebo 6 do chow jen od hr\u00E1\u010De bezprost\u0159edn\u011B p\u0159ed tebou, ne od jin\u00E9ho."),
            rule_section(:table_hk_sets, "Hongkong \u2014 \u00FApln\u00FD p\u0159ehled bodov\u00E1n\u00ED",
              "B\u011B\u017En\u00E1 v\u00FDhra vy\u017Eaduje \u010Dty\u0159i sestavy a p\u00E1r a alespo\u0148 3 fan. Sedm p\u00E1r\u016F a t\u0159in\u00E1ct sirotk\u016F maj\u00ED jin\u00FD tvar. N\u00E1sleduje \u00FApln\u00FD p\u0159ehled pr\u00E9mi\u00ED tohoto vyd\u00E1n\u00ED; bez uveden\u00E9ho omezen\u00ED plat\u00ED pro otev\u0159enou i zav\u0159enou ruku. Samotn\u00E9 b\u011B\u017En\u00E9 \u010Dou, \u010D\u00EDseln\u00FD pung ani p\u00E1r nemaj\u00ED zvl\u00E1\u0161tn\u00ED pr\u00E9mii.",
              "Slu\u010Diteln\u00E9 b\u011B\u017En\u00E9 pr\u00E9mie se s\u010D\u00EDtaj\u00ED. Mal\u00ED a velc\u00ED t\u0159i draci nahrazuj\u00ED body za jednotliv\u00E9 dra\u010D\u00ED pungy. U zvl\u00E1\u0161tn\u00EDch rukou od 10 fan se pou\u017Eije jen nejvy\u0161\u0161\u00ED odpov\u00EDdaj\u00EDc\u00ED zvl\u00E1\u0161tn\u00ED pr\u00E9mie, bez b\u011B\u017En\u00FDch bonus\u016F. Zav\u0159en\u00E1 ruka ani \u010Dty\u0159i skryt\u00E9 pungy nemaj\u00ED zvl\u00E1\u0161tn\u00ED pr\u00E9mii. V\u0161ech osm bonusov\u00FDch kamen\u016F d\u00E1v\u00E1 4 fan a sedm p\u00E1r\u016F 4 fan."),
            rule_section(:table_hk_fan_1, "Hong Kong: 1 fan",
              "- 1 fan \u2014 Vlastn\u00ED dobr\u00E1n\u00ED v\u00FDhern\u00EDho kamene.",
              "- 1 fan \u2014 Sam\u00E1 \u010Dou: \u010Dty\u0159i postupky a p\u00E1r, kter\u00FD m\u016F\u017Ee b\u00FDt \u010Destn\u00FD.",
              "- 1 fan \u2014 Pung nebo kong \u010Derven\u00FDch drak\u016F.",
              "- 1 fan \u2014 Pung nebo kong zelen\u00FDch drak\u016F.",
              "- 1 fan \u2014 Pung nebo kong b\u00EDl\u00FDch drak\u016F.",
              "- 1 fan \u2014 Pung nebo kong vlastn\u00EDho v\u011Btru.",
              "- 1 fan \u2014 Pung nebo kong v\u011Btru kola; shodn\u00FD vlastn\u00ED v\u00EDtr a v\u00EDtr kola d\u00E1vaj\u00ED celkem 2 fan.",
              "- 1 fan \u2014 V\u00FDhra n\u00E1hradn\u00EDm kamenem po kongu; po\u010D\u00EDt\u00E1 se i vlastn\u00ED dobr\u00E1n\u00ED.",
              "- 1 fan \u2014 Okraden\u00ED kongu: v\u00FDhra na kameni p\u0159id\u00E1van\u00E9m k odkryt\u00E9mu pungu.",
              "- 1 fan \u2014 Posledn\u00ED b\u011B\u017En\u00E9 dobr\u00E1n\u00ED ze zdi; po\u010D\u00EDt\u00E1 se i vlastn\u00ED dobr\u00E1n\u00ED.",
              "- 1 fan \u2014 V\u00FDhra na posledn\u00EDm odhozu po vy\u010Derp\u00E1n\u00ED b\u011B\u017En\u00E9 zdi.",
              "- 1 fan \u2014 \u017D\u00E1dn\u00E9 bonusy: ani kv\u011Btina, ani ro\u010Dn\u00ED obdob\u00ED.",
              "- 1 fan \u2014 Vlastn\u00ED kv\u011Btina: jej\u00ED \u010D\u00EDslo odpov\u00EDd\u00E1 tv\u00E9mu v\u011Btru.",
              "- 1 fan \u2014 Vlastn\u00ED ro\u010Dn\u00ED obdob\u00ED: jeho \u010D\u00EDslo odpov\u00EDd\u00E1 tv\u00E9mu v\u011Btru."),
            rule_section(:table_hk_fan_2, "Hong Kong: 2 fan",
              "- 2 fan \u2014 V\u0161echny \u010Dty\u0159i kv\u011Btiny: nahrazuj\u00ED 1 fan za vlastn\u00ED kv\u011Btinu.",
              "- 2 fan \u2014 V\u0161echna \u010Dty\u0159i ro\u010Dn\u00ED obdob\u00ED: nahrazuj\u00ED 1 fan za vlastn\u00ED obdob\u00ED."),
            rule_section(:table_hk_fan_3_8, "Hong Kong: 3\u20138 fan",
              "- 3 fan \u2014 Sam\u00E9 pungy: \u010Dty\u0159i pungy nebo kongy a p\u00E1r.",
              "- 3 fan \u2014 Polovi\u010Dn\u00ED barva: jedna \u010D\u00EDseln\u00E1 barva a \u010Destn\u00E9 kameny, oboj\u00ED p\u0159\u00EDtomno.",
              "- 4 fan \u2014 Sedm p\u00E1r\u016F: \u010Dty\u0159i stejn\u00E9 kameny bez vyhl\u00E1\u0161en\u00E9ho kongu mohou tvo\u0159it dva p\u00E1ry.",
              "- 5 fan \u2014 Mal\u00ED t\u0159i draci: dva pungy nebo kongy drak\u016F a p\u00E1r t\u0159et\u00EDho; zahrnuje bonusy za pungy drak\u016F.",
              "- 7 fan \u2014 \u010Cist\u00E1 barva: jen bambusy, kruhy nebo znaky, bez \u010Destn\u00FDch kamen\u016F.",
              "- 8 fan \u2014 Velc\u00ED t\u0159i draci: pungy nebo kongy v\u0161ech t\u0159\u00ED drak\u016F; zahrnuje bonusy za pungy drak\u016F."),
            rule_section(:table_hk_fan_special, "Hong Kong: 10\u201318 fan",
              "- 10 fan \u2014 Mal\u00E9 \u010Dty\u0159i v\u011Btry: t\u0159i pungy nebo kongy v\u011Btr\u016F a p\u00E1r \u010Dtvrt\u00E9ho.",
              "- 10 fan \u2014 Sam\u00E9 \u010Destn\u00E9 kameny: platn\u00E1 v\u00EDt\u011Bzn\u00E1 ruka pouze z v\u011Btr\u016F a drak\u016F.",
              "- 10 fan \u2014 Sam\u00E9 krajn\u00ED kameny: pouze jedni\u010Dky a dev\u00EDtky, bez \u010Destn\u00FDch.",
              "- 13 fan \u2014 T\u0159in\u00E1ct sirotk\u016F: ka\u017Ed\u00E1 jedni\u010Dka a dev\u00EDtka, \u010Dty\u0159i v\u011Btry, t\u0159i draci a jeden stejn\u00FD k\u00E1men do p\u00E1ru; zav\u0159en\u00E1 ruka.",
              "- 15 fan \u2014 Velk\u00E9 \u010Dty\u0159i v\u011Btry: \u010Dty\u0159i pungy nebo kongy v\u011Btr\u016F a p\u00E1r.",
              "- 15 fan \u2014 Dev\u011Bt bran: skryt\u00FD p\u0159esn\u00FD z\u00E1klad 1112345678999 jedn\u00E9 barvy p\u0159ed dobr\u00E1n\u00EDm nebo p\u0159evzet\u00EDm dal\u0161\u00EDho kamene t\u00E9 barvy.",
              "- 18 fan \u2014 \u010Cty\u0159i kongy a p\u00E1r."),
            rule_section(:table_hk_bonus, "Hongkong \u2014 kv\u011Btiny a obdob\u00ED podle v\u011Btru",
              "Vlastn\u00ED kv\u011Btina a obdob\u00ED se \u0159\u00EDd\u00ED tv\u00FDm v\u011Btrem, ne v\u011Btrem kola. \u010C\u00EDslo 1 je V\u00FDchod, 2 Jih, 3 Z\u00E1pad, 4 Sever. Cel\u00E1 rodina nahrazuje pr\u00E9mii za vlastn\u00ED k\u00E1men; ob\u011B rodiny se boduj\u00ED zvl\u00E1\u0161\u0165.",
              "- V\u00FDchod: kv\u011Bt \u0161vestky a jaro.",
              "- Jih: kv\u011Bt orchideje a l\u00E9to.",
              "- Z\u00E1pad: kv\u011Bt chryzant\u00E9my a podzim.",
              "- Sever: kv\u011Bt bambusu a zima."),
            rule_section(:table_hk_payments, "Hong Kong \u2014 Bodov\u00E1n\u00ED a v\u00FDplaty",
              "Z\u00E1klady v\u00FDplaty: 3 fan \u2014 8 bod\u016F; 4 \u2014 16; 5 \u2014 24; 6 \u2014 32; 7 \u2014 48; 8 a v\u00EDce \u2014 64. Ruka m\u016F\u017Ee p\u0159es\u00E1hnout 8 fan, ale z\u00E1klad v\u00FDplaty u\u017E neroste.",
              "P\u0159i v\u00FDh\u0159e z odhozu plat\u00ED odhazuj\u00EDc\u00ED dva z\u00E1klady, ostatn\u00ED soupe\u0159i po jednom. P\u0159i vlastn\u00EDm dobr\u00E1n\u00ED plat\u00ED ka\u017Ed\u00FD soupe\u0159 dva z\u00E1klady.",
              "Nebesk\u00E1 ani pozemsk\u00E1 ruka se p\u0159i h\u0159e nyn\u00ED nep\u0159izn\u00E1vaj\u00ED. Nep\u0159id\u00E1vej za n\u011B pr\u00E9mii za v\u00FDhru na za\u010D\u00E1tku rozd\u00E1n\u00ED."),
            rule_section(:table_winds, "Hong Kong \u2014 Rozd\u00E1n\u00ED a d\u00E9lka z\u00E1pasu",
              "V\u00FDchoz\u00ED z\u00E1pas m\u00E1 \u010Dty\u0159i kola v\u011Btr\u016F: V\u00FDchod, Jih, Z\u00E1pad a Sever. V ka\u017Ed\u00E9m v\u0161ichni dokon\u010D\u00ED sv\u00E9 rozd\u00E1v\u00E1n\u00ED, tedy nejm\u00E9n\u011B \u0161estn\u00E1ct rozd\u00E1n\u00ED. Platby se s\u010D\u00EDtaj\u00ED od nuly; jedno vyhran\u00E9 rozd\u00E1n\u00ED nemus\u00ED vyhr\u00E1t z\u00E1pas.",
              "Rozd\u00E1vaj\u00EDc\u00ED opakuje po vlastn\u00ED v\u00FDh\u0159e i ka\u017Ed\u00E9 rem\u00EDze. V\u00FDchod proto trv\u00E1 nejm\u00E9n\u011B \u010Dty\u0159i rozd\u00E1n\u00ED, n\u011Bkdy v\u00EDce. \u010Cty\u0159i kola v\u011Btr\u016F jsou V\u00FDchod, Jih, Z\u00E1pad a Sever: nejm\u00E9n\u011B 16 rozd\u00E1n\u00ED. Ro\u010Dn\u00ED obdob\u00ED jsou bonusov\u00E9 kameny, ne tato kola.",
              "Po rozd\u00E1n\u00ED zkontroluj v\u00EDt\u011Bze, hodnotu a zm\u011Bny bod\u016F. V del\u0161\u00EDm z\u00E1pase v\u0161ichni potvrd\u00ED p\u0159ipravenost k dal\u0161\u00EDmu rozd\u00E1n\u00ED. Rem\u00EDza v Hong Kong body za rozd\u00E1n\u00ED nem\u011Bn\u00ED. Po zvolen\u00FDch kolech vyhraje nejvy\u0161\u0161\u00ED sou\u010Det; shodn\u00E1 maxima znamenaj\u00ED rem\u00EDzu."),
            rule_section(:table_hk_variants, "Hong Kong \u2014 Volba d\u00E9lky hry",
              "D\u00E9lku vol\u00ED\u0161 v nastaven\u00ED hry p\u0159ed za\u010D\u00E1tkem. N\u00E1sleduj\u00EDc\u00ED krat\u0161\u00ED nastaven\u00ED m\u011Bn\u00ED po\u010Det rozd\u00E1n\u00ED, nikoli pravidla v\u00EDt\u011Bzn\u00E9 ruky.",
              "Jedno rozd\u00E1n\u00ED kon\u010D\u00ED jednou v\u00FDhrou nebo rem\u00EDzou po vy\u010Derp\u00E1n\u00ED zdi. V\u00FDchodn\u00ED kolo znamen\u00E1, \u017Ee v\u0161ichni \u010Dty\u0159i dokon\u010D\u00ED sv\u00E9 obdob\u00ED rozd\u00E1v\u00E1n\u00ED. Rozd\u00E1vaj\u00EDc\u00ED m\u00E1 vlastn\u00ED V\u00FDchod a spole\u010Dn\u00FD v\u00EDtr kola je b\u011Bhem cel\u00E9 t\u00E9to \u010D\u00E1sti tak\u00E9 V\u00FDchod. Nen\u00ED to jeden tah."),
            rule_section(:table_riichi_aim, "Riichi \u2014 C\u00EDl a podm\u00EDnky v\u00FDhry",
              "V z\u00E1kladn\u00ED h\u0159e pro \u010Dty\u0159i chce\u0161 dokon\u010Dit ruku d\u0159\u00EDv ne\u017E soupe\u0159i. Obvykle m\u00E1 \u010Dty\u0159i sestavy a p\u00E1r, pot\u0159ebuje ale i yaku, uznanou podm\u00EDnku v\u00FDhry. Samotn\u00FD \u00FApln\u00FD tvar bez yaku nemus\u00ED vyhr\u00E1t. Z\u00E1pas vyhraje nejvy\u0161\u0161\u00ED kone\u010Dn\u00FD \u00FA\u010Det; dal\u0161\u00ED kapitola pojmy vysv\u011Btl\u00ED."),
            rule_section(:table_riichi_terms, "Riichi \u2014 V\u00FDznam pojm\u016F",
              "Hraje\u0161 proti ostatn\u00EDm. Ze sv\u00FDch kamen\u016F sestavuje\u0161 v\u00EDt\u011Bznou ruku; neodeb\u00EDr\u00E1\u0161 p\u00E1ry z rozlo\u017Een\u00ED jako v solitaire. Ruka jsou tvoje kameny, rozd\u00E1n\u00ED je hra od jejich rozd\u00E1n\u00ED po v\u00FDhru nebo rem\u00EDzu. Z\u00E1pas m\u016F\u017Ee m\u00EDt v\u00EDce rozd\u00E1n\u00ED.",
              "- K\u00E1men je jeden kus, nap\u0159\u00EDklad bambus 5. Druh ur\u010Duje barva a \u010D\u00EDslo nebo konkr\u00E9tn\u00ED v\u00EDtr \u010Di drak. Od ka\u017Ed\u00E9ho b\u011B\u017En\u00E9ho druhu jsou \u010Dty\u0159i kusy.",
              "- Barvy jsou znaky, bambusy a kruhy, s \u010D\u00EDsly 1\u20139. V jedn\u00E9 postupce se barvy nem\u00EDchaj\u00ED. Jedni\u010Dky a dev\u00EDtky jsou krajn\u00ED kameny, \u010D\u00EDsla 2\u20138 prost\u0159edn\u00ED.",
              "- \u010Cestn\u00E9 kameny jsou v\u011Btry V\u00FDchod, Jih, Z\u00E1pad a Sever a draci b\u00EDl\u00FD, zelen\u00FD a \u010Derven\u00FD. Nemaj\u00ED \u010D\u00EDslo a netvo\u0159\u00ED postupky.",
              "- Chow neboli chi jsou t\u0159i po sob\u011B jdouc\u00ED \u010D\u00EDsla stejn\u00E9 barvy, nap\u0159\u00EDklad bambusy 3, 4 a 5. Bambus 3, kruh 4 a bambus 5 chow netvo\u0159\u00ED; ani \u010D\u00EDsla 8, 9 a 1 stejn\u00E9 barvy.",
              "- Pung, tak\u00E9 pong \u010Di pon, jsou t\u0159i stejn\u00E9 kameny, nap\u0159\u00EDklad t\u0159i \u010Derven\u00ED draci. T\u0159i p\u011Btky r\u016Fzn\u00FDch barev pung netvo\u0159\u00ED.",
              "- Kong neboli kan jsou \u010Dty\u0159i stejn\u00E9 kameny. Mus\u00ED\u0161 jej vyhl\u00E1sit p\u0159\u00EDslu\u0161nou volbou; samotn\u00E9 dr\u017Een\u00ED \u010Dty\u0159 kus\u016F kong nevyhl\u00E1s\u00ED. Po\u010D\u00EDt\u00E1 se jako jedna sestava a n\u00E1sleduje n\u00E1hradn\u00ED dobr\u00E1n\u00ED.",
              "- P\u00E1r jsou dva stejn\u00E9 kameny. Sestava je chow, pung nebo kong. B\u011B\u017En\u00E1 v\u00EDt\u011Bzn\u00E1 ruka pot\u0159ebuje \u010Dty\u0159i sestavy a jeden p\u00E1r, ne jen n\u011Bkolik p\u00E1r\u016F nebo mnoho kamen\u016F jedn\u00E9 barvy.",
              "- Ze\u010F je z\u00E1soba kamen\u016F k dob\u00EDr\u00E1n\u00ED. Dobran\u00FD k\u00E1men p\u0159id\u00E1\u0161 do ruky; odhozen\u00EDm jeden odevzd\u00E1\u0161 a soupe\u0159i jej mohou p\u0159evz\u00EDt.",
              "- Zav\u0159en\u00E1 ruka nem\u00E1 sestavy z\u00EDskan\u00E9 od soupe\u0159e. P\u0159evzet\u00ED chow, pungu nebo otev\u0159en\u00E9ho kongu ji otev\u0159e. Sestavy z vlastn\u00EDch kamen\u016F mohou z\u016Fstat v ruce. Skryt\u00FD kong ruku neotev\u00EDr\u00E1.",
              "- V\u00FDhra z dobr\u00E1n\u00ED pou\u017E\u00EDv\u00E1 pr\u00E1v\u011B dobran\u00FD k\u00E1men. V\u00FDhra na odhoz dokon\u010D\u00ED ruku soupe\u0159ov\u00FDm kamenem. Vyhraj volbou Vyhl\u00E1sit Mahjong; v\u00EDt\u011Bzn\u00FD k\u00E1men nejprve neodhazuj.",
              "- \u010Cek\u00E1n\u00ED je druh kamene, kter\u00FD by ruku dokon\u010Dil. S bambusy 4\u20135 m\u016F\u017Ee\u0161 \u010Dekat na 3 nebo 6. Tenpai znamen\u00E1, \u017Ee k \u00FApln\u00E9mu tvaru chyb\u00ED jeden k\u00E1men. K leg\u00E1ln\u00ED v\u00FDh\u0159e mus\u00ED\u0161 splnit i bodovou podm\u00EDnku varianty.",
              "- Yaku je pojmenovan\u00E1 podm\u00EDnka oprav\u0148uj\u00EDc\u00ED \u00FAplnou ruku k v\u00FDh\u0159e. Pot\u0159ebuje\u0161 alespo\u0148 jedno. Nap\u0159\u00EDklad dra\u010D\u00ED pung je yaku, n\u00E1hodn\u00FD \u00FApln\u00FD tvar j\u00EDm b\u00FDt nemus\u00ED.",
              "- Han m\u011B\u0159\u00ED hodnotu yaku a pr\u00E9mi\u00ED. Fu jsou men\u0161\u00ED body za stavbu sestav, p\u00E1ru a \u010Dek\u00E1n\u00ED. Spole\u010Dn\u011B ur\u010Duj\u00ED platbu. Samotn\u00E9 fu pot\u0159ebn\u00E9 yaku nenahrad\u00ED.",
              "- Ron je v\u00FDhra na ciz\u00ED odhoz, tsumo z vlastn\u00EDho dobr\u00E1n\u00ED. Menzen znamen\u00E1 zav\u0159enou ruku. Menzen tsumo tedy je vlastn\u00ED dobr\u00E1n\u00ED se zav\u0159enou rukou a samo tvo\u0159\u00ED yaku.",
              "- Riichi je vyhl\u00E1\u0161en\u00ED zav\u0159en\u00E9 ruky, kter\u00E9 chyb\u00ED jedin\u00FD k\u00E1men. Odlo\u017E\u00ED\u0161 vklad 1000 bod\u016F a z\u00EDsk\u00E1\u0161 yaku, ale pozd\u011Bji u\u017E ruku nem\u016F\u017Ee\u0161 voln\u011B m\u011Bnit.",
              "- Dora je bonusov\u00FD druh kamene ur\u010Den\u00FD ukazatelem. Ka\u017Ed\u00FD kus p\u0159id\u00E1v\u00E1 han a\u017E p\u0159i skute\u010Dn\u00E9m yaku. Samotn\u00E9 dory v\u00FDhru neumo\u017E\u0148uj\u00ED.",
              "- Furiten zakazuje v\u00FDhru na ciz\u00ED odhoz. Vznik\u00E1 kv\u016Fli vlastn\u00EDm odhoz\u016Fm nebo odm\u00EDtnut\u00ED v\u00EDt\u011Bzn\u00E9ho odhozu. Nebr\u00E1n\u00ED v\u00FDh\u0159e z vlastn\u00EDho dobr\u00E1n\u00ED.",
              "- Honba je po\u010D\u00EDtadlo pr\u00E9mi\u00ED po rem\u00EDz\u00E1ch a opakov\u00E1n\u00ED rozd\u00E1vaj\u00EDc\u00EDho. Mangan a vy\u0161\u0161\u00ED limity jsou platebn\u00ED \u00FArovn\u011B cenn\u00FDch rukou, nikoli dal\u0161\u00ED povinn\u00E9 sestavy.",
              "- Vlastn\u00ED v\u00EDtr je tvoje role v\u016F\u010Di rozd\u00E1vaj\u00EDc\u00EDmu: V\u00FDchod pro n\u011Bj, d\u00E1le Jih, Z\u00E1pad a Sever. V\u00EDtr kola plat\u00ED pro cel\u00FD st\u016Fl. Pung obou bodovan\u00FDch v\u011Btr\u016F m\u016F\u017Ee bodovat, p\u0159i jejich shod\u011B jedna sestava spln\u00ED ob\u011B podm\u00EDnky."),
            rule_section(:table_riichi_start, "Riichi \u2014 Za\u010D\u00E1tek rozd\u00E1n\u00ED",
              "Ka\u017Ed\u00FD za\u010D\u00EDn\u00E1 s 30 000 body. Platby a p\u0159ijat\u00E9 vklady Riichi tento \u00FA\u010Det m\u011Bn\u00ED.",
              "Rozd\u00E1vaj\u00EDc\u00ED za\u010D\u00EDn\u00E1 se 14 kameny a nejprve odhazuje, ostatn\u00ED maj\u00ED 13. V b\u011B\u017En\u00E9m tahu zvol Dobrat k\u00E1men a stiskni Enter. Proch\u00E1zen\u00ED seznamu nic nedob\u00EDr\u00E1. Rozd\u00E1vaj\u00EDc\u00ED u\u017E m\u00E1 k\u00E1men nav\u00EDc a dal\u0161\u00ED dobr\u00E1n\u00ED na za\u010D\u00E1tku nehled\u00E1."),
            rule_section(:table_riichi_play, "Riichi \u2014 Prvn\u00ED tahy krok za krokem",
              "P\u0159ed prvn\u00EDm odhozem si ruku projdi \u0161ipkami nahoru a dol\u016F. Hledej sousedn\u00ED \u010D\u00EDsla pro chow, stejn\u00E9 kameny pro pungy a jeden p\u00E1r na konec. Sestavy ponechan\u00E9 v ruce neozna\u010Duje\u0161 zvl\u00E1\u0161\u0165: hra je pozn\u00E1 p\u0159i vyhl\u00E1\u0161en\u00ED v\u00FDhry.",
              "Kdy\u017E proch\u00E1z\u00ED\u0161 hern\u00ED pole, nov\u00FD vlastn\u00ED tah zam\u011B\u0159\u00ED Dobrat k\u00E1men. Po dobr\u00E1n\u00ED p\u0159ejde fokus na nov\u00FD k\u00E1men s p\u0159\u00EDslu\u0161n\u00FDm ozna\u010Den\u00EDm. T\u00EDm se neodhazuje. \u0160ipkami m\u016F\u017Ee\u0161 p\u0159ej\u00EDt jinam, nov\u00FD k\u00E1men si nechat a odhodit star\u00FD.",
              "Pro odhoz vyber jeden k\u00E1men v seznamu povolen\u00FDch odhoz\u016F a stiskni Enter. Odevzd\u00E1\u0161 jen tento kus. Ze t\u0159\u00ED stejn\u00FDch kamen\u016F ti po odhozu jednoho z\u016Fstanou dva.",
              "Po ciz\u00EDm odhozu usly\u0161\u00ED\u0161 k\u00E1men a dostane\u0161 seznam odpov\u011Bd\u00ED. Pas znamen\u00E1 jen, \u017Ee tento k\u00E1men nechce\u0161; nevzd\u00E1v\u00E1\u0161 rozd\u00E1n\u00ED. Kdy\u017E v\u0161ichni daj\u00ED pas, dob\u00EDr\u00E1 dal\u0161\u00ED hr\u00E1\u010D. Ne\u017E p\u0159ijde tvoje dobr\u00E1n\u00ED, m\u016F\u017Ee\u0161 n\u011Bkolikr\u00E1t odpov\u00EDdat Pas.",
              "Prvn\u00ED pole popisuje situaci. Hned za n\u00EDm jsou v\u0161echny dostupn\u00E9 akce: odpov\u011Bdi, dobr\u00E1n\u00ED, Mahjong, kong \u010Di Riichi, pokud je varianta pou\u017E\u00EDv\u00E1. Pak n\u00E1sleduj\u00ED tvoje kameny. Tab a Shift+Tab m\u011Bn\u00ED pole, \u0161ipky polo\u017Eku a Enter potvrzuje. Nedostupn\u00E1 akce se nezobrazuje.",
              "Ve Vylo\u017Een\u00FDch sestav\u00E1ch najde\u0161 sestavy v\u0161ech hr\u00E1\u010D\u016F se jm\u00E9ny vlastn\u00EDk\u016F. Odhozen\u00E9 kameny ukazuj\u00ED, kdo co odhodil. Pom\u00E1haj\u00ED zjistit, co u\u017E bylo pou\u017Eito a co mohou soupe\u0159i hledat. \u010Cten\u00ED t\u011Bchto pol\u00ED neprov\u00E1d\u00ED tah.",
              "Dokon\u010D\u00ED-li k\u00E1men ruku spl\u0148uj\u00EDc\u00ED podm\u00EDnky, zvol Mahjong m\u00EDsto odhozu \u010Di pasu. Hra ov\u011B\u0159\u00ED tvar i bodov\u00E9 po\u017Eadavky. Dojde-li d\u0159\u00EDv ze\u010F, nastane rem\u00EDza; nejbli\u017E\u0161\u00ED nedokon\u010Den\u00E1 ruka t\u00EDm automaticky nevyhraje.",
              "S p\u0159e\u010Dte pr\u016Fb\u011B\u017En\u00E9 body v\u0161ech hr\u00E1\u010D\u016F. M po\u010Det kamen\u016F zb\u00FDvaj\u00EDc\u00EDch k dobr\u00E1n\u00ED ve zdi. Jde jen o ozn\u00E1men\u00ED: nedob\u00EDraj\u00ED, neodhazuj\u00ED, ned\u00E1vaj\u00ED pas ani neodhaluj\u00ED ciz\u00ED ruce.",
              "W p\u0159e\u010Dte hodnotu platn\u00E9 v\u00FDhry: fan nebo han a fu a z\u00EDskan\u00E9 body. Bez platn\u00E9 v\u00FDhry neuv\u00E1d\u00ED kone\u010Dnou hodnotu ruky. P\u0159ed v\u00FDhrou v riichi nezahrnuje skryt\u00E9 ura-dora, tak\u017Ee kone\u010Dn\u00E1 hodnota m\u016F\u017Ee b\u00FDt vy\u0161\u0161\u00ED. U \u010Dte tv\u00E9 vylo\u017Een\u00E9 sestavy, Shift+U sestavy ostatn\u00EDch a R \u010D\u00EDslo rozd\u00E1n\u00ED, v\u011Btry a aktu\u00E1ln\u00ED situaci. V riichi I \u010Dte ukazatele a kameny dora, po\u010Det tv\u00FDch dora, hl\u00E1\u0161en\u00ED riichi, vklady, honba a tv\u00E9 omezen\u00ED furiten. Tyto kl\u00E1vesy pouze \u010Dtou informace."),
            rule_section(:table_riichi_build, "Riichi \u2014 Co sestavit pro v\u00FDhru",
              "B\u011B\u017En\u00FD tvar jsou \u010Dty\u0159i sestavy a p\u00E1r. Alternativami jsou sedm r\u016Fzn\u00FDch p\u00E1r\u016F a t\u0159in\u00E1ct sirotk\u016F. V\u00FDhra vy\u017Eaduje jaku; samotn\u00E9 dora a fu nesta\u010D\u00ED. P\u0159i platn\u00E9 v\u00FDh\u0159e zvol Vyhl\u00E1sit Mahjong a stiskni Enter. P\u0159ehledy d\u00E1le uv\u00E1d\u011Bj\u00ED v\u0161echna p\u0159izn\u00E1van\u00E1 jaku a hodnoty fu."),
            rule_section(:table_riichi_claims, "Riichi \u2014 P\u0159eb\u00EDr\u00E1n\u00ED kamen\u016F a vyhla\u0161ov\u00E1n\u00ED kong\u016F",
              "Po odhozen\u00ED jin\u00FDm hr\u00E1\u010Dem seznam odpov\u011Bd\u00ED nab\u00EDdne jen povolen\u00E9 mo\u017Enosti. Pokud k\u00E1men nechce\u0161, zvol Pass. Jinak vyber Chow, Pung, Kong nebo ohl\u00E1\u0161en\u00ED mahjongu a stiskni Enter. Chow lze p\u0159evz\u00EDt jen od hr\u00E1\u010De bezprost\u0159edn\u011B p\u0159ed tebou. Pung \u010Di kong m\u016F\u017Ee vyu\u017E\u00EDt odhozen\u00ED kter\u00E9hokoli soupe\u0159e.",
              "V\u00FDhra m\u00E1 p\u0159ednost p\u0159ed p\u0159evzet\u00EDm do skupiny; pung a kong maj\u00ED p\u0159ednost p\u0159ed chow. Pokud na stejn\u00FD k\u00E1men vyhr\u00E1v\u00E1 v\u00EDce hr\u00E1\u010D\u016F, vyhraje prvn\u00ED v po\u0159ad\u00ED za odhazuj\u00EDc\u00EDm. Hra \u010Dek\u00E1 na v\u0161echny po\u017Eadovan\u00E9 odpov\u011Bdi. Po p\u0159evzet\u00ED chow \u010Di pungu odhazuje\u0161 bez dob\u00EDr\u00E1n\u00ED a skupina z\u016Fst\u00E1v\u00E1 odkryt\u00E1.",
              "Po ohl\u00E1\u0161en\u00ED kongu dober n\u00E1hradn\u00ED k\u00E1men a teprve potom odhazuj. Dr\u017E\u00ED\u0161-li v\u0161echny \u010Dty\u0159i kopie, m\u016F\u017Ee\u0161 je ohl\u00E1sit v seznamu skryt\u00FDch kong\u016F. \u010Ctvrt\u00FDm kamenem lze tak\u00E9 roz\u0161\u00ED\u0159it odkryt\u00FD pung. P\u0159ed dokon\u010Den\u00EDm takov\u00E9ho kongu mohou soupe\u0159i ohl\u00E1sit v\u00FDhru na p\u0159id\u00E1van\u00FD k\u00E1men.",
              "Otev\u0159en\u00ED m\u016F\u017Ee zru\u0161it pl\u00E1novan\u00E9 yaku. Riichi i zav\u0159en\u00E9 vlastn\u00ED dobr\u00E1n\u00ED vy\u017Eaduj\u00ED zav\u0159enou ruku, dra\u010D\u00ED pung boduje i otev\u0159en\u00FD. P\u0159ed p\u0159evzet\u00EDm si rozmysli zb\u00FDvaj\u00EDc\u00ED yaku."),
            rule_section(:table_riichi, "Riichi \u2014 vyhl\u00E1\u0161en\u00ED p\u0159ipravenosti, dora a furiten",
              "Pokud skryt\u00E9 ruce chyb\u00ED jedin\u00FD k\u00E1men k v\u00FDh\u0159e, seznam Riichi nab\u00EDdne odhozen\u00ED pro ohl\u00E1\u0161en\u00ED p\u0159ipravenosti. Vyber k\u00E1men a stiskni Enter. P\u0159ijat\u00E9 ohl\u00E1\u0161en\u00ED vlo\u017E\u00ED na st\u016Fl 1 000 bod\u016F. Potom mus\u00ED\u0161 odhodit dobran\u00FD k\u00E1men, pokud nevyhr\u00E1v\u00E1\u0161; kong je dovolen jen p\u0159i zachov\u00E1n\u00ED v\u0161ech po\u017Eadovan\u00FDch v\u00FDklad\u016F ruky. V\u00EDt\u011Bz z\u00EDsk\u00E1 vklady; nevyzvednut\u00FD vklad p\u0159ech\u00E1z\u00ED do dal\u0161\u00EDho rozd\u00E1n\u00ED.",
              "Furiten zakazuje v\u00FDhru na odhozen\u00ED, jestli\u017Ee n\u011Bkter\u00FD z v\u00EDt\u011Bzn\u00FDch kamen\u016F le\u017E\u00ED mezi tv\u00FDmi vlastn\u00EDmi odhozen\u00FDmi kameny. Odm\u00EDtnut\u00ED platn\u00E9 v\u00FDhry na ciz\u00ED k\u00E1men rovn\u011B\u017E do\u010Dasn\u011B blokuje takov\u00E9 v\u00FDhry; po ohl\u00E1\u0161en\u00ED Riichi trv\u00E1 z\u00E1kaz do konce rozd\u00E1n\u00ED. St\u00E1le m\u016F\u017Ee\u0161 vyhr\u00E1t vlastn\u00EDm dobr\u00E1n\u00EDm.",
              "P\u0159\u00EDklad furiten: \u010Dek\u00E1\u0161 na bambus 3 nebo 6, ale d\u0159\u00EDve jsi odhodil 3. V\u00FDhra na ciz\u00ED odhoz je blokov\u00E1na i na 6, nejen na odhozenou 3. Vlastn\u00ED dobr\u00E1n\u00ED 3 \u010Di 6 st\u00E1le m\u016F\u017Ee vyhr\u00E1t."),
            rule_section(:table_yaku, "Riichi \u2014 \u00FApln\u00FD p\u0159ehled jaku a han",
              "Riichi vy\u017Eaduje platnou ruku a alespo\u0148 jedno jaku. N\u00ED\u017Ee jsou v\u0161echna b\u011B\u017En\u00E1 jaku p\u0159izn\u00E1van\u00E1 v tomto vyd\u00E1n\u00ED s hodnotami zav\u0159en\u00E9 a otev\u0159en\u00E9 ruky. Skryt\u00FD kong ruku neotev\u00EDr\u00E1. Pung dokon\u010Den\u00FD v\u00FDhern\u00EDm ciz\u00EDm odhozem nen\u00ED p\u0159i hodnocen\u00ED skryt\u00FD.",
              "- Riichi: zav\u0159en\u00E1 p\u0159ipraven\u00E1 ruka a p\u0159ijat\u00E9 vyhl\u00E1\u0161en\u00ED s vkladem 1000 bod\u016F. Pouze zav\u0159en\u00E1: 1 han.",
              "- Dvojit\u00E9 riichi: vyhl\u00E1\u0161en\u00ED v prvn\u00EDm nep\u0159eru\u0161en\u00E9m ob\u011Bhu; nahrazuje b\u011B\u017En\u00E9 riichi. Pouze zav\u0159en\u00E1: 2 han.",
              "- Ippatsu: v\u00FDhra v prvn\u00EDm nep\u0159eru\u0161en\u00E9m ob\u011Bhu po riichi. Pouze zav\u0159en\u00E1: 1 han.",
              "- Menzen tsumo: vlastn\u00ED dobr\u00E1n\u00ED se zav\u0159enou rukou. Pouze zav\u0159en\u00E1: 1 han.",
              "- Tanyao: pouze \u010D\u00EDsla 2 a\u017E 8, bez \u010Destn\u00FDch kamen\u016F. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Yakuhai: za ka\u017Ed\u00FD pung nebo kong drak\u016F zvl\u00E1\u0161\u0165. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Pung nebo kong vlastn\u00EDho v\u011Btru. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Pung nebo kong v\u011Btru kola; p\u0159i shod\u011B s vlastn\u00EDm v\u011Btrem celkem 2 han. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Haitei: v\u00FDhra posledn\u00EDm b\u011B\u017En\u00FDm dobr\u00E1n\u00EDm ze zdi. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Houtei: v\u00FDhra na posledn\u00EDm odhozu. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Rinshan: v\u00FDhra n\u00E1hradn\u00EDm kamenem po kongu. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Chankan: okraden\u00ED kongu. Zav\u0159en\u00E1: 1 han; otev\u0159en\u00E1: 1 han.",
              "- Pinfu: \u010Dty\u0159i \u010Dou, nebodovan\u00FD p\u00E1r a oboustrann\u00E9 \u010Dek\u00E1n\u00ED. Pouze zav\u0159en\u00E1: 1 han.",
              "- Iipeikou: dv\u011B toto\u017En\u00E1 \u010Dou jedn\u00E9 barvy. Pouze zav\u0159en\u00E1: 1 han.",
              "- Ryanpeikou: dva p\u00E1ry toto\u017En\u00FDch \u010Dou; nahrazuje iipeikou. Pouze zav\u0159en\u00E1: 3 han.",
              "- Chiitoitsu: sedm r\u016Fzn\u00FDch p\u00E1r\u016F; \u010Dty\u0159i stejn\u00E9 kameny netvo\u0159\u00ED dva p\u00E1ry. Pouze zav\u0159en\u00E1: 2 han.",
              "- Toitoi: \u010Dty\u0159i pungy nebo kongy a p\u00E1r. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Sanankou: t\u0159i skryt\u00E9 pungy nebo kongy; \u010Dtvrt\u00E1 sestava m\u016F\u017Ee b\u00FDt odkryt\u00E1. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Sankantsu: t\u0159i kongy. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Shousangen: dva pungy nebo kongy drak\u016F a p\u00E1r t\u0159et\u00EDho; po\u010D\u00EDtaj\u00ED se i ob\u011B dra\u010D\u00ED yakuhai. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Sanshoku doujun: stejn\u00E9 \u010Dou ve v\u0161ech t\u0159ech barv\u00E1ch. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 1 han.",
              "- Sanshoku doukou: pungy stejn\u00E9ho \u010D\u00EDsla ve t\u0159ech barv\u00E1ch. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Ittsu: \u010Dou 123, 456 a 789 jedn\u00E9 barvy. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 1 han.",
              "- Chanta: ka\u017Ed\u00E1 sestava i p\u00E1r obsahuj\u00ED krajn\u00ED nebo \u010Destn\u00FD k\u00E1men; p\u0159\u00EDtomna \u010Dou i \u010Destn\u00E9 kameny. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 1 han.",
              "- Junchan: ka\u017Ed\u00E1 sestava i p\u00E1r obsahuj\u00ED 1 nebo 9; jsou \u010Dou, nejsou \u010Destn\u00E9 kameny. Zav\u0159en\u00E1: 3 han; otev\u0159en\u00E1: 2 han.",
              "- Honroutou: pouze krajn\u00ED a \u010Destn\u00E9 kameny. Zav\u0159en\u00E1: 2 han; otev\u0159en\u00E1: 2 han.",
              "- Honitsu: jedna \u010D\u00EDseln\u00E1 barva a \u010Destn\u00E9 kameny. Zav\u0159en\u00E1: 3 han; otev\u0159en\u00E1: 2 han.",
              "- Chinitsu: jedna \u010D\u00EDseln\u00E1 barva bez \u010Destn\u00FDch kamen\u016F. Zav\u0159en\u00E1: 6 han; otev\u0159en\u00E1: 5 han."),
            rule_section(:table_riichi_dora, "Riichi \u2014 dal\u0161\u00ED han za dora",
              "Dora p\u0159id\u00E1vaj\u00ED 1 han za ka\u017Ed\u00FD vlastn\u00ED k\u00E1men dora, ale pouze ruce se skute\u010Dn\u00FDm jaku. Dora nejsou jaku. Ukazatel ur\u010Duje dal\u0161\u00ED k\u00E1men v cyklu; po\u010D\u00EDt\u00E1 se ka\u017Ed\u00E1 kopie v ruce i vlastn\u00EDch sestav\u00E1ch. Po p\u0159ijat\u00E9m riichi mohou p\u0159i kone\u010Dn\u00E9 v\u00FDh\u0159e p\u0159ib\u00FDt skryt\u00E9 ura-dora; n\u00E1hled p\u0159ed v\u00FDhrou je neodhaluje."),
            rule_section(:table_riichi_yakuman, "Riichi \u2014 \u00FApln\u00FD p\u0159ehled yakuman\u016F",
              "Ka\u017Ed\u00E1 polo\u017Eka n\u00ED\u017Ee d\u00E1v\u00E1 1 yakuman m\u00EDsto b\u011B\u017En\u00FDch han a fu. R\u016Fzn\u00E9 slu\u010Diteln\u00E9 yakumany se mohou s\u010D\u00EDtat. Toto vyd\u00E1n\u00ED nezdvojuje yakuman za zvl\u00E1\u0161tn\u00ED \u010Dek\u00E1n\u00ED ani za velk\u00E9 \u010Dty\u0159i v\u011Btry.",
              "- 1 yakuman \u2014 T\u0159in\u00E1ct sirotk\u016F: v\u0161echny krajn\u00ED a \u010Destn\u00E9 kameny a jeden nav\u00EDc; zav\u0159en\u00E1 ruka.",
              "- 1 yakuman \u2014 \u010Cty\u0159i skryt\u00E9 pungy nebo kongy: v\u00FDhra z odhozu mus\u00ED doplnit p\u00E1r.",
              "- 1 yakuman \u2014 Velc\u00ED t\u0159i draci: pungy nebo kongy v\u0161ech t\u0159\u00ED drak\u016F.",
              "- 1 yakuman \u2014 Velk\u00E9 \u010Dty\u0159i v\u011Btry: \u010Dty\u0159i pungy nebo kongy v\u011Btr\u016F.",
              "- 1 yakuman \u2014 Mal\u00E9 \u010Dty\u0159i v\u011Btry: t\u0159i pungy nebo kongy v\u011Btr\u016F a p\u00E1r \u010Dtvrt\u00E9ho.",
              "- 1 yakuman \u2014 Sam\u00E9 \u010Destn\u00E9 kameny: pouze v\u011Btry a draci.",
              "- 1 yakuman \u2014 Sam\u00E9 krajn\u00ED kameny: pouze jedni\u010Dky a dev\u00EDtky.",
              "- 1 yakuman \u2014 Sam\u00E9 zelen\u00E9: pouze bambusy 2, 3, 4, 6, 8 a zelen\u00ED draci.",
              "- 1 yakuman \u2014 \u010Cty\u0159i kongy a p\u00E1r.",
              "- 1 yakuman \u2014 Dev\u011Bt bran: zav\u0159en\u00E1 jednobarevn\u00E1 ruka, 1112345678999 a dal\u0161\u00ED k\u00E1men t\u00E9 barvy.",
              "Nebesk\u00E1 ani pozemsk\u00E1 ruka se p\u0159i h\u0159e nyn\u00ED nep\u0159izn\u00E1vaj\u00ED. Nep\u0159id\u00E1vej za n\u011B pr\u00E9mii za v\u00FDhru na za\u010D\u00E1tku rozd\u00E1n\u00ED."),
            rule_section(:table_fu, "Riichi: fu za sestavy a \u010Dek\u00E1n\u00ED",
              "Han vyjad\u0159uj\u00ED hodnotu yaku a pr\u00E9mi\u00ED, fu hodnot\u00ED stavbu ruky. Chow d\u00E1v\u00E1 0 fu. B\u011B\u017En\u00FD p\u00E1r tak\u00E9 0; p\u00E1r drak\u016F, vlastn\u00EDho v\u011Btru nebo v\u011Btru kola d\u00E1v\u00E1 2 fu. Pokud je stejn\u00FD v\u00EDtr z\u00E1rove\u0148 vlastn\u00ED i v\u011Btrem kola, tato hra st\u00E1le p\u0159id\u00E1 jen 2 fu.",
              "U pung\u016F a kong\u016F z\u00E1le\u017E\u00ED na druhu kamen\u016F a na tom, zda jsou otev\u0159en\u00E9:",
              "- Pung \u010D\u00EDsel 2\u20138: otev\u0159en\u00FD 2 fu, skryt\u00FD 4 fu.",
              "- Pung jedni\u010Dek, dev\u00EDtek nebo \u010Destn\u00FDch kamen\u016F: otev\u0159en\u00FD 4 fu, skryt\u00FD 8 fu.",
              "- Kong \u010D\u00EDsel 2\u20138: otev\u0159en\u00FD 8 fu, skryt\u00FD 16 fu.",
              "- Kong jedni\u010Dek, dev\u00EDtek nebo \u010Destn\u00FDch kamen\u016F: otev\u0159en\u00FD 16 fu, skryt\u00FD 32 fu.",
              "Pung dokon\u010Den\u00FD v\u00EDt\u011Bzn\u00FDm ciz\u00EDm odhozem se pro fu po\u010D\u00EDt\u00E1 jako otev\u0159en\u00FD. Ostatn\u00ED pungy v ruce z\u016Fst\u00E1vaj\u00ED skryt\u00E9. P\u0159id\u00E1n\u00ED \u010Dtvrt\u00E9ho kamene k otev\u0159en\u00E9mu pungu vytvo\u0159\u00ED otev\u0159en\u00FD kong.",
              "B\u011B\u017En\u00FD v\u00FDpo\u010Det za\u010D\u00EDn\u00E1 na 20 fu. V\u00FDhra na odhoz se zav\u0159enou rukou p\u0159id\u00E1v\u00E1 10, vlastn\u00ED dobr\u00E1n\u00ED 2. \u010Cek\u00E1n\u00ED na p\u00E1r, prost\u0159edek nebo okraj postupky p\u0159id\u00E1v\u00E1 2 fu. Okraj znamen\u00E1 3 k 1\u20132 nebo 7 k 8\u20139; prost\u0159edek nap\u0159\u00EDklad 5 k 4\u20136. Oboustrann\u00E9 \u010Dek\u00E1n\u00ED, nap\u0159\u00EDklad 3 nebo 6 k 4\u20135, fu nep\u0159id\u00E1v\u00E1.",
              "Sou\u010Det zaokrouhli nahoru na cel\u00E9 des\u00EDtky: z 32 je 40 fu. Sedm p\u00E1r\u016F m\u00E1 v\u017Edy 25 fu. Pinfu z vlastn\u00EDho dobr\u00E1n\u00ED m\u00E1 20 fu bez dal\u0161\u00EDch 2 za dobr\u00E1n\u00ED. Jin\u00E1 ruka, kter\u00E1 by m\u011Bla jen 20, dostane nejm\u00E9n\u011B 30 fu.",
              "Nap\u0159\u00EDklad z\u00E1klad 20, zav\u0159en\u00E1 v\u00FDhra na odhoz 10, skryt\u00FD pung p\u011Btek 4 a p\u00E1r drak\u016F 2 d\u00E1vaj\u00ED 36, tedy 40 fu. St\u00E1le pot\u0159ebuje\u0161 yaku: samotn\u00E9 fu v\u00FDhru neumo\u017En\u00ED."),
            rule_section(:table_riichi_payments, "Riichi: p\u0159evod han a fu na body",
              "U b\u011B\u017En\u00E9 v\u00FDhry je z\u00E1klad fu kr\u00E1t 2 umocn\u011Bn\u00E9 na han plus 2, nejv\u00FD\u0161e 2000. P\u0159i 1 han a 30 fu je to 30 kr\u00E1t 8, tedy 240. Ka\u017Ed\u00E1 kone\u010Dn\u00E1 platba se zaokrouhluje nahoru na stovky.",
              "Na odhoz dostane nerozd\u00E1vaj\u00EDc\u00ED \u010Dty\u0159n\u00E1sobek z\u00E1kladu od odhazuj\u00EDc\u00EDho, rozd\u00E1vaj\u00EDc\u00ED \u0161estin\u00E1sobek. P\u0159i vlastn\u00EDm dobr\u00E1n\u00ED dostane nerozd\u00E1vaj\u00EDc\u00ED dva z\u00E1klady od rozd\u00E1vaj\u00EDc\u00EDho a po jednom od ostatn\u00EDch. Vyhraje-li rozd\u00E1vaj\u00EDc\u00ED, ka\u017Ed\u00FD plat\u00ED dva z\u00E1klady.",
              "P\u0159i 1 han 30 fu bez pr\u00E9mi\u00ED vyhraje nerozd\u00E1vaj\u00EDc\u00ED 1000 na odhoz, nebo 500 od rozd\u00E1vaj\u00EDc\u00EDho a po 300 od ostatn\u00EDch z dobr\u00E1n\u00ED, celkem 1100. Rozd\u00E1vaj\u00EDc\u00ED dostane 1500 na odhoz nebo po 500 od ka\u017Ed\u00E9ho, tak\u00E9 1500.",
              "- Mangan: 5 han nebo dosa\u017Een\u00ED limitu z\u00E1kladu; zde tak\u00E9 3 han 60 fu a 4 han 30 fu. Na odhoz dostane nerozd\u00E1vaj\u00EDc\u00ED 8000, rozd\u00E1vaj\u00EDc\u00ED 12 000.",
              "- Haneman: 6\u20137 han, na odhoz 12 000 nebo 18 000.",
              "- Baiman: 8\u201310 han, 16 000 nebo 24 000.",
              "- Sanbaiman: 11\u201312 han, 24 000 nebo 36 000.",
              "- Yakuman nebo alespo\u0148 13 han: 32 000 nebo 48 000. V\u00EDce slu\u010Diteln\u00FDch yakuman\u016F tuto platbu n\u00E1sob\u00ED.",
              "Ka\u017Ed\u00E9 honba p\u0159id\u00E1v\u00E1 300 k platb\u011B na odhoz nebo po 100 od ka\u017Ed\u00E9ho soupe\u0159e p\u0159i dobr\u00E1n\u00ED. Vklady Riichi dostane v\u00EDt\u011Bz nav\u00EDc. Honba roste po rem\u00EDze nebo opakov\u00E1n\u00ED rozd\u00E1vaj\u00EDc\u00EDho a po v\u00FDh\u0159e jin\u00E9ho hr\u00E1\u010De se vynuluje."),
            rule_section(:table_riichi_match, "Riichi \u2014 Rozd\u00E1n\u00ED a d\u00E9lka z\u00E1pasu",
              "V\u00FDchoz\u00ED hra je pro \u010Dty\u0159i, ka\u017Ed\u00FD m\u00E1 30 000 bod\u016F a hraj\u00ED se V\u00FDchod a Jih. Ka\u017Ed\u00FD dokon\u010D\u00ED rozd\u00E1v\u00E1n\u00ED v obou kolech: nejm\u00E9n\u011B osm rozd\u00E1n\u00ED, s opakov\u00E1n\u00EDm v\u00EDce. Platby i p\u0159ijat\u00E9 vklady Riichi m\u011Bn\u00ED pr\u016Fb\u011B\u017En\u00FD \u00FA\u010Det.",
              "Rozd\u00E1vaj\u00EDc\u00ED opakuje po vlastn\u00ED v\u00FDh\u0159e nebo rem\u00EDze ze zdi, pokud m\u00E1 tenpai.",
              "P\u0159i rem\u00EDze ze zdi se 3000 bod\u016F p\u0159ev\u00E1d\u00ED od nep\u0159ipraven\u00FDch k tenpai, pokud nejsou p\u0159ipraveni v\u0161ichni nebo nikdo. Potom ka\u017Ed\u00FD potvrd\u00ED dal\u0161\u00ED rozd\u00E1n\u00ED. Z\u00E1pas trv\u00E1 vybran\u00E1 kola; z\u00E1porn\u00FD \u00FA\u010Det ani veden\u00ED posledn\u00EDho rozd\u00E1vaj\u00EDc\u00EDho jej zde nezkr\u00E1t\u00ED. Nejvy\u0161\u0161\u00ED kone\u010Dn\u00FD \u00FA\u010Det v\u00EDt\u011Bz\u00ED, shodn\u00E1 maxima remizuj\u00ED."),
            rule_section(:table_riichi_variants, "Riichi \u2014 hra ve t\u0159ech a d\u00E9lka z\u00E1pasu",
              "D\u00E9lku vol\u00ED\u0161 v nastaven\u00ED hry p\u0159ed za\u010D\u00E1tkem. N\u00E1sleduj\u00EDc\u00ED krat\u0161\u00ED nastaven\u00ED m\u011Bn\u00ED po\u010Det rozd\u00E1n\u00ED, nikoli pravidla v\u00EDt\u011Bzn\u00E9 ruky.",
              "Jedno rozd\u00E1n\u00ED kon\u010D\u00ED v\u00FDhrou nebo rem\u00EDzou po zdi. V\u00FDchodn\u00ED kolo d\u00E1 ka\u017Ed\u00E9mu obdob\u00ED rozd\u00E1v\u00E1n\u00ED: nejm\u00E9n\u011B \u010Dty\u0159i rozd\u00E1n\u00ED ve \u010Dty\u0159ech nebo t\u0159i v sanm\u011B. V\u00FDchod a Jih jsou dv\u011B kola: nejm\u00E9n\u011B osm nebo \u0161est. Rozd\u00E1vaj\u00EDc\u00ED opakuje po v\u00FDh\u0159e \u010Di rem\u00EDze v tenpai, tak\u017Ee m\u016F\u017Ee b\u00FDt rozd\u00E1n\u00ED v\u00EDce.",
              "Vlastn\u00ED v\u011Btry jdou od rozd\u00E1vaj\u00EDc\u00EDho V\u00FDchod, Jih, Z\u00E1pad a ve \u010Dty\u0159ech Sever. V\u00EDtr kola z\u016Fst\u00E1v\u00E1 V\u00FDchod, dokud v\u0161ichni nedokon\u010D\u00ED rozd\u00E1v\u00E1n\u00ED, pak je v del\u0161\u00EDm z\u00E1pase Jih. Bodovan\u00E9 v\u011Btry se tak mohou zm\u011Bnit. Sanma odstra\u0148uje znaky 2\u20138 a zde nem\u00E1 samostatn\u00E9 vykl\u00E1d\u00E1n\u00ED Severu.",
              "V sanm\u011B nelze p\u0159eb\u00EDrat chow, ale postupky z vlastn\u00EDch kamen\u016F tvo\u0159it m\u016F\u017Ee\u0161.",
              "V sanm\u011B chyb\u011Bj\u00EDc\u00ED \u010Dtvrt\u00FD hr\u00E1\u010D neplat\u00ED a jeho pod\u00EDl se nep\u0159en\u00E1\u0161\u00ED na ostatn\u00ED. Vlastn\u00ED dobr\u00E1n\u00ED tak m\u016F\u017Ee p\u0159in\u00E9st m\u00E9n\u011B ne\u017E ve \u010Dty\u0159ech. P\u0159i rem\u00EDze se mezi p\u0159ipraven\u00E9 a nep\u0159ipraven\u00E9 d\u011Bl\u00ED 2000 m\u00EDsto 3000 bod\u016F."),
            rule_section(:table_mcr_aim, "MCR \u2014 C\u00EDl a podm\u00EDnky v\u00FDhry",
              "\u010Cty\u0159i hr\u00E1\u010Di cht\u011Bj\u00ED jako prvn\u00ED dokon\u010Dit v\u00EDt\u011Bznou ruku. B\u011B\u017En\u00FD tvar jsou \u010Dty\u0159i sestavy a p\u00E1r nejm\u00E9n\u011B za 8 fan bez kv\u011Btin. Fan m\u011B\u0159\u00ED slu\u010Diteln\u00E9 bodov\u00E9 vzory. V\u00FDhra rozd\u00E1n\u00ED p\u0159inese platbu, z\u00E1pas vyhraje nejvy\u0161\u0161\u00ED celkov\u00FD \u00FA\u010Det."),
            rule_section(:table_mcr_terms, "MCR \u2014 V\u00FDznam pojm\u016F",
              "Hraje\u0161 proti ostatn\u00EDm. Ze sv\u00FDch kamen\u016F sestavuje\u0161 v\u00EDt\u011Bznou ruku; neodeb\u00EDr\u00E1\u0161 p\u00E1ry z rozlo\u017Een\u00ED jako v solitaire. Ruka jsou tvoje kameny, rozd\u00E1n\u00ED je hra od jejich rozd\u00E1n\u00ED po v\u00FDhru nebo rem\u00EDzu. Z\u00E1pas m\u016F\u017Ee m\u00EDt v\u00EDce rozd\u00E1n\u00ED.",
              "- K\u00E1men je jeden kus, nap\u0159\u00EDklad bambus 5. Druh ur\u010Duje barva a \u010D\u00EDslo nebo konkr\u00E9tn\u00ED v\u00EDtr \u010Di drak. Od ka\u017Ed\u00E9ho b\u011B\u017En\u00E9ho druhu jsou \u010Dty\u0159i kusy.",
              "- Barvy jsou znaky, bambusy a kruhy, s \u010D\u00EDsly 1\u20139. V jedn\u00E9 postupce se barvy nem\u00EDchaj\u00ED. Jedni\u010Dky a dev\u00EDtky jsou krajn\u00ED kameny, \u010D\u00EDsla 2\u20138 prost\u0159edn\u00ED.",
              "- \u010Cestn\u00E9 kameny jsou v\u011Btry V\u00FDchod, Jih, Z\u00E1pad a Sever a draci b\u00EDl\u00FD, zelen\u00FD a \u010Derven\u00FD. Nemaj\u00ED \u010D\u00EDslo a netvo\u0159\u00ED postupky.",
              "- Chow neboli chi jsou t\u0159i po sob\u011B jdouc\u00ED \u010D\u00EDsla stejn\u00E9 barvy, nap\u0159\u00EDklad bambusy 3, 4 a 5. Bambus 3, kruh 4 a bambus 5 chow netvo\u0159\u00ED; ani \u010D\u00EDsla 8, 9 a 1 stejn\u00E9 barvy.",
              "- Pung, tak\u00E9 pong \u010Di pon, jsou t\u0159i stejn\u00E9 kameny, nap\u0159\u00EDklad t\u0159i \u010Derven\u00ED draci. T\u0159i p\u011Btky r\u016Fzn\u00FDch barev pung netvo\u0159\u00ED.",
              "- Kong neboli kan jsou \u010Dty\u0159i stejn\u00E9 kameny. Mus\u00ED\u0161 jej vyhl\u00E1sit p\u0159\u00EDslu\u0161nou volbou; samotn\u00E9 dr\u017Een\u00ED \u010Dty\u0159 kus\u016F kong nevyhl\u00E1s\u00ED. Po\u010D\u00EDt\u00E1 se jako jedna sestava a n\u00E1sleduje n\u00E1hradn\u00ED dobr\u00E1n\u00ED.",
              "- P\u00E1r jsou dva stejn\u00E9 kameny. Sestava je chow, pung nebo kong. B\u011B\u017En\u00E1 v\u00EDt\u011Bzn\u00E1 ruka pot\u0159ebuje \u010Dty\u0159i sestavy a jeden p\u00E1r, ne jen n\u011Bkolik p\u00E1r\u016F nebo mnoho kamen\u016F jedn\u00E9 barvy.",
              "- Ze\u010F je z\u00E1soba kamen\u016F k dob\u00EDr\u00E1n\u00ED. Dobran\u00FD k\u00E1men p\u0159id\u00E1\u0161 do ruky; odhozen\u00EDm jeden odevzd\u00E1\u0161 a soupe\u0159i jej mohou p\u0159evz\u00EDt.",
              "- Zav\u0159en\u00E1 ruka nem\u00E1 sestavy z\u00EDskan\u00E9 od soupe\u0159e. P\u0159evzet\u00ED chow, pungu nebo otev\u0159en\u00E9ho kongu ji otev\u0159e. Sestavy z vlastn\u00EDch kamen\u016F mohou z\u016Fstat v ruce. Skryt\u00FD kong ruku neotev\u00EDr\u00E1.",
              "- V\u00FDhra z dobr\u00E1n\u00ED pou\u017E\u00EDv\u00E1 pr\u00E1v\u011B dobran\u00FD k\u00E1men. V\u00FDhra na odhoz dokon\u010D\u00ED ruku soupe\u0159ov\u00FDm kamenem. Vyhraj volbou Vyhl\u00E1sit Mahjong; v\u00EDt\u011Bzn\u00FD k\u00E1men nejprve neodhazuj.",
              "- \u010Cek\u00E1n\u00ED je druh kamene, kter\u00FD by ruku dokon\u010Dil. S bambusy 4\u20135 m\u016F\u017Ee\u0161 \u010Dekat na 3 nebo 6. Tenpai znamen\u00E1, \u017Ee k \u00FApln\u00E9mu tvaru chyb\u00ED jeden k\u00E1men. K leg\u00E1ln\u00ED v\u00FDh\u0159e mus\u00ED\u0161 splnit i bodovou podm\u00EDnku varianty.",
              "- MCR znamen\u00E1 Mahjong Competition Rules. Fan m\u011B\u0159\u00ED hodnotu bodovan\u00FDch vzor\u016F. Pot\u0159ebuje\u0161 nejm\u00E9n\u011B 8 fan bez kv\u011Btin. Z fan se po\u010D\u00EDt\u00E1 platba; nejsou tot\u00E9\u017E co sou\u010Det bod\u016F z\u00E1pasu.",
              "- Bodov\u00FD vzor popisuje vlastnost cel\u00E9 ruky \u010Di sestav. N\u011Bkter\u00E9 se kombinuj\u00ED, jin\u00E9 zahrnuj\u00ED men\u0161\u00ED vzor a jeho dal\u0161\u00ED body vylu\u010Duj\u00ED. Nes\u010D\u00EDtej v\u0161echny n\u00E1zvy, kter\u00E9 zd\u00E1nliv\u011B sed\u00ED.",
              "- Kv\u011Btiny a ro\u010Dn\u00ED obdob\u00ED se automaticky vylo\u017E\u00ED a nahrad\u00ED. Ka\u017Ed\u00E9 p\u0159id\u00E1 1 fan k platn\u00E9 v\u00FDh\u0159e, ale nepom\u016F\u017Ee dos\u00E1hnout povinn\u00FDch 8. Sedm fan s kv\u011Btinou nesta\u010D\u00ED.",
              "- Vlastn\u00ED v\u00EDtr je role v\u016F\u010Di rozd\u00E1vaj\u00EDc\u00EDmu, v\u00EDtr kola spole\u010Dn\u00FD v\u0161em. Pung vlastn\u00EDho v\u011Btru \u010Di v\u011Btru kola je bodov\u00FD vzor. Ro\u010Dn\u00ED obdob\u00ED jsou bonusov\u00E9 kameny, ne \u010Dty\u0159i kola v\u011Btr\u016F."),
            rule_section(:table_mcr_start, "MCR \u2014 Za\u010D\u00E1tek rozd\u00E1n\u00ED",
              "\u00DA\u010Dty za\u010D\u00EDnaj\u00ED od nuly; v\u00FDhry body p\u0159id\u00E1vaj\u00ED a prohry odeb\u00EDraj\u00ED.",
              "Rozd\u00E1vaj\u00EDc\u00ED za\u010D\u00EDn\u00E1 se 14 kameny a nejprve odhazuje, ostatn\u00ED maj\u00ED 13. V b\u011B\u017En\u00E9m tahu zvol Dobrat k\u00E1men a stiskni Enter. Proch\u00E1zen\u00ED seznamu nic nedob\u00EDr\u00E1. Rozd\u00E1vaj\u00EDc\u00ED u\u017E m\u00E1 k\u00E1men nav\u00EDc a dal\u0161\u00ED dobr\u00E1n\u00ED na za\u010D\u00E1tku nehled\u00E1."),
            rule_section(:table_mcr_play, "MCR \u2014 Prvn\u00ED tahy krok za krokem",
              "P\u0159ed prvn\u00EDm odhozem si ruku projdi \u0161ipkami nahoru a dol\u016F. Hledej sousedn\u00ED \u010D\u00EDsla pro chow, stejn\u00E9 kameny pro pungy a jeden p\u00E1r na konec. Sestavy ponechan\u00E9 v ruce neozna\u010Duje\u0161 zvl\u00E1\u0161\u0165: hra je pozn\u00E1 p\u0159i vyhl\u00E1\u0161en\u00ED v\u00FDhry.",
              "Kdy\u017E proch\u00E1z\u00ED\u0161 hern\u00ED pole, nov\u00FD vlastn\u00ED tah zam\u011B\u0159\u00ED Dobrat k\u00E1men. Po dobr\u00E1n\u00ED p\u0159ejde fokus na nov\u00FD k\u00E1men s p\u0159\u00EDslu\u0161n\u00FDm ozna\u010Den\u00EDm. T\u00EDm se neodhazuje. \u0160ipkami m\u016F\u017Ee\u0161 p\u0159ej\u00EDt jinam, nov\u00FD k\u00E1men si nechat a odhodit star\u00FD.",
              "Pro odhoz vyber jeden k\u00E1men v seznamu povolen\u00FDch odhoz\u016F a stiskni Enter. Odevzd\u00E1\u0161 jen tento kus. Ze t\u0159\u00ED stejn\u00FDch kamen\u016F ti po odhozu jednoho z\u016Fstanou dva.",
              "Po ciz\u00EDm odhozu usly\u0161\u00ED\u0161 k\u00E1men a dostane\u0161 seznam odpov\u011Bd\u00ED. Pas znamen\u00E1 jen, \u017Ee tento k\u00E1men nechce\u0161; nevzd\u00E1v\u00E1\u0161 rozd\u00E1n\u00ED. Kdy\u017E v\u0161ichni daj\u00ED pas, dob\u00EDr\u00E1 dal\u0161\u00ED hr\u00E1\u010D. Ne\u017E p\u0159ijde tvoje dobr\u00E1n\u00ED, m\u016F\u017Ee\u0161 n\u011Bkolikr\u00E1t odpov\u00EDdat Pas.",
              "Prvn\u00ED pole popisuje situaci. Hned za n\u00EDm jsou v\u0161echny dostupn\u00E9 akce: odpov\u011Bdi, dobr\u00E1n\u00ED, Mahjong, kong \u010Di Riichi, pokud je varianta pou\u017E\u00EDv\u00E1. Pak n\u00E1sleduj\u00ED tvoje kameny. Tab a Shift+Tab m\u011Bn\u00ED pole, \u0161ipky polo\u017Eku a Enter potvrzuje. Nedostupn\u00E1 akce se nezobrazuje.",
              "Ve Vylo\u017Een\u00FDch sestav\u00E1ch najde\u0161 sestavy v\u0161ech hr\u00E1\u010D\u016F se jm\u00E9ny vlastn\u00EDk\u016F. Odhozen\u00E9 kameny ukazuj\u00ED, kdo co odhodil. Pom\u00E1haj\u00ED zjistit, co u\u017E bylo pou\u017Eito a co mohou soupe\u0159i hledat. \u010Cten\u00ED t\u011Bchto pol\u00ED neprov\u00E1d\u00ED tah.",
              "Dokon\u010D\u00ED-li k\u00E1men ruku spl\u0148uj\u00EDc\u00ED podm\u00EDnky, zvol Mahjong m\u00EDsto odhozu \u010Di pasu. Hra ov\u011B\u0159\u00ED tvar i bodov\u00E9 po\u017Eadavky. Dojde-li d\u0159\u00EDv ze\u010F, nastane rem\u00EDza; nejbli\u017E\u0161\u00ED nedokon\u010Den\u00E1 ruka t\u00EDm automaticky nevyhraje.",
              "S p\u0159e\u010Dte pr\u016Fb\u011B\u017En\u00E9 body v\u0161ech hr\u00E1\u010D\u016F. M po\u010Det kamen\u016F zb\u00FDvaj\u00EDc\u00EDch k dobr\u00E1n\u00ED ve zdi. Jde jen o ozn\u00E1men\u00ED: nedob\u00EDraj\u00ED, neodhazuj\u00ED, ned\u00E1vaj\u00ED pas ani neodhaluj\u00ED ciz\u00ED ruce.",
              "W p\u0159e\u010Dte hodnotu platn\u00E9 v\u00FDhry: fan nebo han a fu a z\u00EDskan\u00E9 body. Bez platn\u00E9 v\u00FDhry neuv\u00E1d\u00ED kone\u010Dnou hodnotu ruky. P\u0159ed v\u00FDhrou v riichi nezahrnuje skryt\u00E9 ura-dora, tak\u017Ee kone\u010Dn\u00E1 hodnota m\u016F\u017Ee b\u00FDt vy\u0161\u0161\u00ED. U \u010Dte tv\u00E9 vylo\u017Een\u00E9 sestavy, Shift+U sestavy ostatn\u00EDch a R \u010D\u00EDslo rozd\u00E1n\u00ED, v\u011Btry a aktu\u00E1ln\u00ED situaci. V riichi I \u010Dte ukazatele a kameny dora, po\u010Det tv\u00FDch dora, hl\u00E1\u0161en\u00ED riichi, vklady, honba a tv\u00E9 omezen\u00ED furiten. Tyto kl\u00E1vesy pouze \u010Dtou informace."),
            rule_section(:table_mcr_build, "MCR \u2014 Co sestavit pro v\u00FDhru",
              "B\u011B\u017En\u00E1 ruka m\u00E1 \u010Dty\u0159i sestavy a p\u00E1r; MCR dovoluje tak\u00E9 sedm p\u00E1r\u016F, t\u0159in\u00E1ct sirotk\u016F a pleten\u00E9 ruce popsan\u00E9 v p\u0159ehledu. Pot\u0159ebuje\u0161 alespo\u0148 8 fan bez kv\u011Btin. P\u0159i spln\u011Bn\u00ED podm\u00EDnek zvol Vyhl\u00E1sit Mahjong a stiskni Enter. Ka\u017Ed\u00E1 polo\u017Eka m\u00E1 n\u00E1zev, hodnotu a podm\u00EDnku odkryt\u00ED."),
            rule_section(:table_mcr_claims, "MCR \u2014 P\u0159eb\u00EDr\u00E1n\u00ED kamen\u016F a vyhla\u0161ov\u00E1n\u00ED kong\u016F",
              "Po odhozen\u00ED jin\u00FDm hr\u00E1\u010Dem seznam odpov\u011Bd\u00ED nab\u00EDdne jen povolen\u00E9 mo\u017Enosti. Pokud k\u00E1men nechce\u0161, zvol Pass. Jinak vyber Chow, Pung, Kong nebo ohl\u00E1\u0161en\u00ED mahjongu a stiskni Enter. Chow lze p\u0159evz\u00EDt jen od hr\u00E1\u010De bezprost\u0159edn\u011B p\u0159ed tebou. Pung \u010Di kong m\u016F\u017Ee vyu\u017E\u00EDt odhozen\u00ED kter\u00E9hokoli soupe\u0159e.",
              "V\u00FDhra m\u00E1 p\u0159ednost p\u0159ed p\u0159evzet\u00EDm do skupiny; pung a kong maj\u00ED p\u0159ednost p\u0159ed chow. Pokud na stejn\u00FD k\u00E1men vyhr\u00E1v\u00E1 v\u00EDce hr\u00E1\u010D\u016F, vyhraje prvn\u00ED v po\u0159ad\u00ED za odhazuj\u00EDc\u00EDm. Hra \u010Dek\u00E1 na v\u0161echny po\u017Eadovan\u00E9 odpov\u011Bdi. Po p\u0159evzet\u00ED chow \u010Di pungu odhazuje\u0161 bez dob\u00EDr\u00E1n\u00ED a skupina z\u016Fst\u00E1v\u00E1 odkryt\u00E1.",
              "Po ohl\u00E1\u0161en\u00ED kongu dober n\u00E1hradn\u00ED k\u00E1men a teprve potom odhazuj. Dr\u017E\u00ED\u0161-li v\u0161echny \u010Dty\u0159i kopie, m\u016F\u017Ee\u0161 je ohl\u00E1sit v seznamu skryt\u00FDch kong\u016F. \u010Ctvrt\u00FDm kamenem lze tak\u00E9 roz\u0161\u00ED\u0159it odkryt\u00FD pung. P\u0159ed dokon\u010Den\u00EDm takov\u00E9ho kongu mohou soupe\u0159i ohl\u00E1sit v\u00FDhru na p\u0159id\u00E1van\u00FD k\u00E1men.",
              "M\u00E1\u0161 dva b\u00EDl\u00E9 draky a t\u0159et\u00ED padne: Pung je vylo\u017E\u00ED a zajist\u00ED dra\u010D\u00ED vzor za 2 fan. Zbytek ruky mus\u00ED st\u00E1le pomoci k 8. P\u0159evzet\u00ED m\u011Bn\u00ED i dostupn\u00E9 vzory za zav\u0159enou ruku. Dostupn\u00FD Pung nezaru\u010Duje budouc\u00ED minimum."),
            rule_section(:table_mcr_sets, "MCR \u2014 jak \u010D\u00EDst p\u0159ehled 81 polo\u017Eek",
              "N\u00E1sleduj\u00EDc\u00EDch 81 polo\u017Eek popisuje bodovan\u00E9 prvky MCR. Pot\u0159ebuje\u0161 platn\u00FD tvar ruky a alespo\u0148 8 fan bez kv\u011Btin. Kong stejn\u00E9ho druhu spl\u0148uje i po\u017Eadavek na pung. \u010C\u00EDseln\u00E9 barvy jsou znaky, kruhy a bambusy; \u010Destn\u00E9 kameny jsou v\u011Btry a draci.",
              "Zav\u0159en\u00E1 ruka nem\u00E1 sestavy p\u0159evzat\u00E9 z odhoz\u016F; vyhl\u00E1\u0161en\u00FD skryt\u00FD kong ji neotev\u0159e. Pung dopln\u011Bn\u00FD v\u00FDhern\u00EDm ciz\u00EDm odhozem je odkryt\u00FD, ostatn\u00ED ponechan\u00E9 pungy z\u016Fst\u00E1vaj\u00ED skryt\u00E9. Pleten\u00FD z\u00E1klad tvo\u0159\u00ED 147 jedn\u00E9 barvy, 258 druh\u00E9 a 369 t\u0159et\u00ED; barvy lze prohodit.",
              "Nes\u010D\u00EDtej v\u0161echny odpov\u00EDdaj\u00EDc\u00ED n\u00E1zvy bez kontroly v\u00FDluk. Vy\u0161\u0161\u00ED vzor m\u016F\u017Ee zahrnovat ni\u017E\u0161\u00ED a stejn\u00E9 sestavy nelze libovoln\u011B opakovan\u011B pou\u017E\u00EDt pro slo\u017Een\u00E9 pr\u00E9mie. Hra vyb\u00EDr\u00E1 slu\u010Diteln\u00E9 vzory. \u010C\u00EDsla ve v\u00FDluk\u00E1ch odkazuj\u00ED na polo\u017Eky MCR, ne na po\u0159ad\u00ED tah\u016F."),
