            rule_section(:table_aim, "\u041C\u0430\u0434\u0436\u043E\u043D\u0433 \u2014 \u0446\u0435\u043B\u044C \u0438\u0433\u0440\u044B",
              "\u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0442\u044B \u0443\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u043F\u0430\u0440\u044B \u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0448\u044C, \u043E\u0447\u0438\u0441\u0442\u0438\u0432 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0443. \u0413\u043E\u043D\u043A\u043E\u043D\u0433, \u0440\u0438\u0438\u0447\u0438 \u0438 MCR \u2014 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u0435 \u0438\u0433\u0440\u044B \u043F\u0440\u043E\u0442\u0438\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432: \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443 \u0438 \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u043E\u0447\u043A\u0438. \u0414\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0439 \u043D\u0438\u0436\u0435 \u0441\u0432\u043E\u044F \u043F\u043E\u043B\u043D\u0430\u044F \u0447\u0430\u0441\u0442\u044C, \u043D\u0430\u0447\u0438\u043D\u0430\u044F \u0441 \u0446\u0435\u043B\u0438 \u0438 \u0442\u0435\u0440\u043C\u0438\u043D\u043E\u0432.",
              "\u0417\u0432\u0443\u043A\u0438 \u0440\u0430\u0437\u043B\u0438\u0447\u0430\u044E\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0443, \u0432\u0437\u044F\u0442\u0438\u0435 \u0438 \u0441\u0431\u0440\u043E\u0441 \u043A\u0430\u043C\u043D\u044F, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u0438 \u043E\u043A\u043E\u043D\u0447\u0430\u043D\u0438\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438. \u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u0442\u0430\u043A\u0436\u0435 \u0441\u043B\u044B\u0448\u043D\u044B \u0441\u043D\u044F\u0442\u0438\u0435 \u043F\u0430\u0440\u044B \u0438 \u043E\u0442\u043C\u0435\u043D\u0430 \u0445\u043E\u0434\u0430. \u041F\u0430\u0441 \u0438 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043A\u0430\u043C\u043D\u0435\u0439 \u043F\u0440\u043E\u0445\u043E\u0434\u044F\u0442 \u0431\u0435\u0437 \u0437\u0432\u0443\u043A\u043E\u0432. \u0420\u0435\u0447\u0435\u0432\u043E\u0435 \u043E\u043F\u0438\u0441\u0430\u043D\u0438\u0435 \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043D\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u043A\u0430\u043C\u0435\u043D\u044C \u0438 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442.",
              "\u041F\u0440\u0438 \u043E\u0442\u0432\u0435\u0442\u0435 \u043D\u0430 \u043A\u0430\u043C\u0435\u043D\u044C \u043A\u043B\u0430\u0432\u0438\u0448\u0430 D \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u0430\u043C\u0435\u043D\u044C, \u043A \u043A\u043E\u0442\u043E\u0440\u043E\u043C\u0443 \u043E\u0442\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u041F\u0430\u0441, \u0427\u043E\u0443, \u041F\u0430\u043D\u0433, \u041A\u043E\u043D\u0433 \u0438\u043B\u0438 \u041C\u0430\u0434\u0436\u043E\u043D\u0433. \u041E\u043D\u0430 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u0438 \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0432\u044B\u0431\u043E\u0440. \u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 D \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0447\u0438\u0442\u0430\u0435\u0442 \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u044B.",
              "W \u043A\u0440\u0430\u0442\u043A\u043E \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0443\u043C\u043C\u0443 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u043D\u043D\u044B\u0445 \u043F\u0440\u0435\u043C\u0438\u0439 \u0438 \u043F\u0440\u0438\u0447\u0438\u043D\u044B. \u0414\u043B\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043D\u0430\u0431\u043E\u0440\u043E\u0432 \u043D\u0430\u043F\u043E\u043C\u0438\u043D\u0430\u0435\u0442, \u0447\u0442\u043E \u0438\u0445 \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u0412 MCR \u0434\u0432\u0430, \u0442\u0440\u0438 \u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043F\u0430\u043D\u0433\u0430 \u0434\u0430\u044E\u0442 2, 16 \u0438 64 \u0444\u0430\u043D\u044C; \u044D\u0442\u0438 \u043F\u0440\u0435\u043C\u0438\u0438 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0434\u0440\u0443\u0433 \u0434\u0440\u0443\u0433\u0430, \u0430 \u043D\u0435 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u042D\u0442\u043E \u043D\u0435 \u043F\u043E\u043B\u043D\u0430\u044F \u043E\u0446\u0435\u043D\u043A\u0430 \u043D\u0435\u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u043E\u0439 \u0440\u0443\u043A\u0438. \u0426\u0432\u0435\u0442\u044B MCR \u0438 \u0434\u043E\u0440\u0430 Riichi \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u0415\u0441\u043B\u0438 \u043C\u043E\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043C\u0430\u0434\u0436\u043E\u043D\u0433, W \u0447\u0438\u0442\u0430\u0435\u0442 \u043F\u043E\u043B\u043D\u0443\u044E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043F\u043E\u0431\u0435\u0434\u044B. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043F\u043E\u0434 W \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0432\u043A\u043B\u044E\u0447\u0451\u043D; \u041D\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u043E\u0446\u0435\u043D\u043A\u0443 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B. \u041F\u043E\u0434\u0441\u0447\u0451\u0442 \u043E\u0447\u043A\u043E\u0432 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F.",
              "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0431\u0435\u0434\u044B \u0421\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0443\u043A\u0438 \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u044F\u0435\u0442 \u0444\u0430\u043A\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043D\u0430\u0447\u0438\u0441\u043B\u0435\u043D\u043D\u044B\u0435 \u043F\u0440\u0435\u043C\u0438\u0438 \u0431\u0435\u0437 \u0437\u0430\u043C\u0435\u043D\u0451\u043D\u043D\u044B\u0445 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0439. \u0412 MCR \u0444\u0430\u043D\u044C \u0437\u0430 \u0440\u0443\u043A\u0443 \u043E\u0442\u0434\u0435\u043B\u0435\u043D\u044B \u043E\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043E\u0447\u043A\u043E\u0432 \u0437\u0430 \u0446\u0432\u0435\u0442\u044B \u0438 \u0432\u0440\u0435\u043C\u0435\u043D\u0430 \u0433\u043E\u0434\u0430, \u0430 \u0442\u0430\u043A\u0436\u0435 \u0443\u043A\u0430\u0437\u0430\u043D\u0430 \u0441\u0443\u043C\u043C\u0430 \u0434\u043B\u044F \u0440\u0430\u0441\u0447\u0451\u0442\u0430. \u0414\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u043D\u0435 \u0432\u0445\u043E\u0434\u044F\u0442 \u0432 \u043C\u0438\u043D\u0438\u043C\u0443\u043C 8 \u0444\u0430\u043D\u044C."),
            rule_section(:aim, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441 \u2014 \u0442\u0435\u0440\u043C\u0438\u043D\u044B \u0438 \u0446\u0435\u043B\u044C",
              "\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0441\u0435 144 \u043A\u043E\u0441\u0442\u0438, \u043F\u043E\u0434\u0431\u0438\u0440\u0430\u044F \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043F\u0430\u0440\u044B. \u0412\u044B \u0438\u0433\u0440\u0430\u0435\u0442\u0435 \u0441\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E \u0438 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442\u0435, \u0443\u0431\u0440\u0430\u0432 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u043F\u0430\u0440\u0443.",
              "\u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0430 \u2014 \u0432\u0441\u0451 \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439. \u041F\u0430\u0440\u0430 \u2014 \u0434\u0432\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u043A\u043E\u0441\u0442\u0438, \u0441\u043B\u043E\u0439 \u2014 \u0443\u0440\u043E\u0432\u0435\u043D\u044C \u0432\u044B\u0441\u043E\u0442\u044B, \u0440\u044F\u0434\u044B \u0438\u0434\u0443\u0442 \u043F\u043E \u0433\u043E\u0440\u0438\u0437\u043E\u043D\u0442\u0430\u043B\u0438, \u0441\u0442\u043E\u043B\u0431\u0446\u044B \u043F\u043E \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u0438. \u0421\u0432\u043E\u0431\u043E\u0434\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u043D\u0438\u0447\u0435\u043C \u043D\u0435 \u043D\u0430\u043A\u0440\u044B\u0442\u0430 \u0438 \u0438\u043C\u0435\u0435\u0442 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u0438\u043D \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u0431\u043E\u043A, \u043B\u0435\u0432\u044B\u0439 \u0438\u043B\u0438 \u043F\u0440\u0430\u0432\u044B\u0439. \u0412\u0438\u0434\u0438\u043C\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u0430 \u0441 \u043E\u0431\u043E\u0438\u0445 \u0431\u043E\u043A\u043E\u0432.",
              "\u0417\u0434\u0435\u0441\u044C \u043D\u0435 \u0441\u043E\u0431\u0438\u0440\u0430\u044E\u0442 \u0447\u043E\u0443, \u043F\u0430\u043D\u0433\u0438 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0438 \u0438 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u044E\u0442 \u0444\u0430\u043D\u044C, \u0445\u0430\u043D \u0438\u043B\u0438 \u044F\u043A\u0443. \u042D\u0442\u0438 \u0442\u0435\u0440\u043C\u0438\u043D\u044B \u043E\u0442\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u043A \u0438\u0433\u0440\u0435 \u043F\u0440\u043E\u0442\u0438\u0432 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432. \u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u0442\u044B \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0448\u044C, \u0443\u0431\u0440\u0430\u0432 \u0432\u0441\u0435 \u043F\u0430\u0440\u044B \u0441 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438."),
            rule_section(:tiles, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441: \u041F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438",
              "\u041F\u0430\u0440\u0443 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0442 \u0434\u0432\u0435 \u043A\u043E\u0441\u0442\u0438 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0438 \u0434\u043E\u0441\u0442\u043E\u0438\u043D\u0441\u0442\u0432\u0430, \u0434\u0432\u0430 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0432\u0435\u0442\u0440\u0430 \u0438\u043B\u0438 \u0434\u0432\u0430 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430. \u041B\u044E\u0431\u044B\u0435 \u0434\u0432\u0430 \u0446\u0432\u0435\u0442\u043A\u0430 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 \u0434\u0440\u0443\u0433 \u043A \u0434\u0440\u0443\u0433\u0443, \u043A\u0430\u043A \u0438 \u043B\u044E\u0431\u044B\u0435 \u0434\u0432\u0430 \u0432\u0440\u0435\u043C\u0435\u043D\u0438 \u0433\u043E\u0434\u0430. \u0426\u0432\u0435\u0442\u043E\u043A \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0431\u044A\u0435\u0434\u0438\u043D\u0438\u0442\u044C \u0441\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0435\u043C \u0433\u043E\u0434\u0430.",
              "\u041E\u0431\u0435 \u043A\u043E\u0441\u0442\u0438 \u0434\u043E\u043B\u0436\u043D\u044B \u0431\u044B\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B: \u0441\u0432\u0435\u0440\u0445\u0443 \u0438\u0445 \u043D\u0435 \u0434\u043E\u043B\u0436\u043D\u0430 \u043F\u0435\u0440\u0435\u043A\u0440\u044B\u0432\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0430\u044F \u043A\u043E\u0441\u0442\u044C, \u0430 \u0441\u043B\u0435\u0432\u0430 \u0438\u043B\u0438 \u0441\u043F\u0440\u0430\u0432\u0430 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0439 \u0434\u043E\u043B\u0436\u043D\u043E \u0431\u044B\u0442\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0435 \u043C\u0435\u0441\u0442\u043E. \u0412\u0438\u0434\u0438\u043C\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u043E\u0441\u0442\u0430\u0432\u0430\u0442\u044C\u0441\u044F \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u043E\u0439 \u0441 \u043E\u0431\u0435\u0438\u0445 \u0441\u0442\u043E\u0440\u043E\u043D. \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043D\u0435 \u0440\u0430\u0441\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F."),
            rule_section(:play, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441: \u0412\u044B\u0431\u043E\u0440 \u043F\u0430\u0440\u044B",
              "\u0412 \u043F\u043E\u043B\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438 \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E \u043F\u0435\u0440\u0435\u043C\u0435\u0449\u0430\u044E\u0442 \u043F\u043E \u0441\u0442\u043E\u043B\u0431\u0446\u0430\u043C, \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437 \u2014 \u043F\u043E \u0440\u044F\u0434\u0430\u043C. \u041A\u043B\u0430\u0432\u0438\u0448\u0438 1, 2 \u0438 3 \u043F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0430\u044E\u0442 \u0441\u043B\u043E\u0438 \u0422\u0435\u0440\u0440\u0430\u0441; \u0443 \u043F\u043B\u043E\u0441\u043A\u043E\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043B\u043E\u0439 1. \u0421\u043B\u043E\u0439 \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0432\u044B\u0441\u043E\u0442\u0443, \u0430 \u043D\u0435 \u0440\u044F\u0434. \u041D\u0430\u0436\u043C\u0438 D, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u043B\u044B\u0448\u0430\u0442\u044C \u0441\u043B\u043E\u0439, \u0440\u044F\u0434 \u0438 \u0441\u0442\u043E\u043B\u0431\u0435\u0446; \u043E\u043D\u0438 \u043D\u0443\u043C\u0435\u0440\u0443\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u0432 \u043A\u0430\u0436\u0434\u043E\u043C \u0441\u043B\u043E\u0435.",
              "\u0414\u043B\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442\u0441\u044F, \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0430 \u043B\u0438 \u043E\u043D\u0430 \u0441\u043B\u0435\u0432\u0430, \u0441\u043F\u0440\u0430\u0432\u0430, \u0441 \u043E\u0431\u0435\u0438\u0445 \u0441\u0442\u043E\u0440\u043E\u043D \u0438\u043B\u0438 \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u0430 \u0441 \u043E\u0431\u0435\u0438\u0445 \u0441\u0442\u043E\u0440\u043E\u043D. \u0423 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u0432\u0438\u0434 \u043D\u0435 \u0440\u0430\u0441\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u041F\u043E\u0441\u043B\u0435 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043F\u0443\u0441\u0442\u044B\u0435 \u043F\u043E\u043B\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u043A\u043E\u043E\u0440\u0434\u0438\u043D\u0430\u0442\u044B \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043D\u0435 \u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F.",
              "\u041D\u0430\u0439\u0434\u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438 \u043D\u0430\u0436\u043C\u0438 Enter, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u0435\u0451. \u0417\u0430\u0442\u0435\u043C \u043D\u0430\u0439\u0434\u0438 \u0432\u0442\u043E\u0440\u0443\u044E \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u0443\u044E \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438 \u043D\u0430\u0436\u043C\u0438 Enter, \u0447\u0442\u043E\u0431\u044B \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u043E\u0431\u0435. \u041F\u0435\u0440\u0432\u043E\u0435 \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0443\u0434\u0430\u043B\u044F\u0435\u0442. \u0415\u0441\u043B\u0438 \u0432\u0442\u043E\u0440\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u043D\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u0438\u0442, \u043F\u0435\u0440\u0432\u0430\u044F \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u043E\u0439. \u041F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0439 Enter \u043D\u0430 \u043F\u0435\u0440\u0432\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 Escape \u043E\u0442\u043C\u0435\u043D\u044F\u0435\u0442 \u0432\u044B\u0431\u043E\u0440. \u0413\u043E\u0442\u043E\u0432\u043E\u0433\u043E \u0441\u043F\u0438\u0441\u043A\u0430 \u043F\u0430\u0440 \u0438\u0433\u0440\u0430 \u043D\u0435 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442.",
              "\u0423\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u043F\u0430\u0440\u044B \u043C\u043E\u0436\u0435\u0442 \u043E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442\u044C \u043A\u043E\u0441\u0442\u0438 \u043F\u043E\u0434 \u043D\u0435\u0439 \u0438\u043B\u0438 \u0440\u044F\u0434\u043E\u043C. \u041F\u043E\u0434\u0443\u043C\u0430\u0439, \u0447\u0442\u043E \u043E\u0442\u043A\u0440\u043E\u0435\u0442 \u0442\u0432\u043E\u0439 \u0445\u043E\u0434. \u041D\u043E\u0432\u0430\u044F \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0430 \u0438\u043C\u0435\u0435\u0442 \u0440\u0435\u0448\u0435\u043D\u0438\u0435, \u043D\u043E \u043D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u043C\u043E\u0433\u0443\u0442 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0442\u0435\u0431\u044F \u0431\u0435\u0437 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u043F\u0430\u0440\u044B.",
              "\u041F\u0440\u0438\u043C\u0435\u0440: \u043D\u0430\u0439\u0434\u0438 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0431\u0430\u043C\u0431\u0443\u043A 5 \u0438 \u043E\u0442\u043C\u0435\u0442\u044C \u0435\u0433\u043E Enter. \u041D\u0430\u0439\u0434\u0438 \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u044B\u0439 \u0431\u0430\u043C\u0431\u0443\u043A 5, \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u043E \u0432 \u0434\u0440\u0443\u0433\u043E\u043C \u0441\u043B\u043E\u0435, \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041E\u0431\u0430 \u0438\u0441\u0447\u0435\u0437\u043D\u0443\u0442. \u0415\u0441\u043B\u0438 \u0432\u0442\u043E\u0440\u043E\u0439 \u0437\u0430\u043A\u0440\u044B\u0442 \u0438\u043B\u0438 \u0437\u0430\u0431\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D, \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0441\u0432\u043E\u0431\u043E\u0434\u0438 \u0435\u0433\u043E \u0434\u0440\u0443\u0433\u0438\u043C\u0438 \u043F\u0430\u0440\u0430\u043C\u0438.",
              "\u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E, \u043F\u043E\u0434\u0443\u043C\u0430\u0439, \u043A\u0430\u043A\u0438\u0435 \u0443\u0431\u0440\u0430\u0442\u044C. \u041A\u0440\u0430\u0439\u043D\u044F\u044F \u043C\u043E\u0436\u0435\u0442 \u043E\u0441\u0432\u043E\u0431\u043E\u0434\u0438\u0442\u044C \u0441\u043E\u0441\u0435\u0434\u0430, \u0432\u0435\u0440\u0445\u043D\u044F\u044F \u2014 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0438\u0436\u043D\u044E\u044E. \u041D\u0435 \u043A\u0430\u0436\u0434\u0430\u044F \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u0430\u044F \u043F\u0430\u0440\u0430 \u0432\u0435\u0434\u0451\u0442 \u043A \u0440\u0435\u0448\u0435\u043D\u0438\u044E. \u041E\u0442\u043C\u0435\u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043F\u0430\u0440\u044B \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u043F\u043E\u043F\u0440\u043E\u0431\u043E\u0432\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u043E\u0439 \u043F\u043E\u0440\u044F\u0434\u043E\u043A."),
            rule_section(:ending, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441: \u041E\u0442\u043C\u0435\u043D\u0430 \u0445\u043E\u0434\u043E\u0432 \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435",
              "\u041A\u043D\u043E\u043F\u043A\u0430 \u043E\u0442\u043C\u0435\u043D\u044B \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0439 \u043F\u0430\u0440\u044B \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0434\u0432\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0435 \u0443\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0432\u0442\u043E\u0440\u044F\u044F \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435, \u043C\u043E\u0436\u043D\u043E \u043E\u0442\u043C\u0435\u043D\u044F\u0442\u044C \u0431\u043E\u043B\u0435\u0435 \u0440\u0430\u043D\u043D\u0438\u0435 \u0445\u043E\u0434\u044B \u0432\u043F\u043B\u043E\u0442\u044C \u0434\u043E \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438.",
              "\u0418\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440 \u0445\u043E\u0434\u0430 \u0438\u0433\u0440\u044B \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u0443\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440 \u0438 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0445\u0441\u044F \u043A\u043E\u0441\u0442\u0435\u0439. \u0412\u0430\u0448 \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u2014 \u0447\u0438\u0441\u043B\u043E \u0443\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440, \u043D\u0435 \u0431\u043E\u043B\u0435\u0435 72. \u0415\u0441\u043B\u0438 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0445 \u043F\u0430\u0440 \u043D\u0435\u0442, \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u0435 \u0445\u043E\u0434 \u0438 \u043F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0434\u0440\u0443\u0433\u043E\u0439 \u043F\u0443\u0442\u044C \u043B\u0438\u0431\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u044D\u0442\u0443 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0443 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043A\u043D\u043E\u043F\u043A\u043E\u0439. \u0414\u043E\u0441\u0440\u043E\u0447\u043D\u043E\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0435 \u043D\u0435 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u043E\u0439.",
              "S \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0447\u0451\u0442 \u2014 \u0447\u0438\u0441\u043B\u043E \u0443\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440. M \u2014 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u043A\u043E\u0441\u0442\u0438. \u0412 \u043D\u043E\u0432\u043E\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0435 144, \u043F\u043E\u0441\u043B\u0435 \u043E\u0434\u043D\u043E\u0439 \u043F\u0430\u0440\u044B \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F 142."),
            rule_section(:solitaire_points, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441 \u2014 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0443\u0434\u0430\u043B\u0451\u043D\u043D\u044B\u0435 \u043F\u0430\u0440\u044B",
              "\u0412 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u043D\u0435\u0442 \u0444\u0430\u043D, \u0445\u0430\u043D \u0438 \u0444\u0443. \u0421\u0447\u0451\u0442 \u2014 \u0447\u0438\u0441\u043B\u043E \u0443\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u043F\u0430\u0440: \u043A\u0430\u0436\u0434\u0430\u044F \u0434\u0430\u0451\u0442 1 \u043E\u0447\u043A\u043E, \u043E\u0442\u043C\u0435\u043D\u0430 \u0435\u0451 \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u044F \u0432\u044B\u0447\u0438\u0442\u0430\u0435\u0442 \u044D\u0442\u043E \u043E\u0447\u043A\u043E. \u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0443\u0431\u0435\u0440\u0438 \u0432\u0441\u0435 144 \u043A\u043E\u0441\u0442\u0438, \u0442\u043E \u0435\u0441\u0442\u044C 72 \u043F\u0430\u0440\u044B."),
            rule_section(:layout, "\u041F\u0430\u0441\u044C\u044F\u043D\u0441: \u0412\u044B\u0431\u043E\u0440 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0430 \u0422\u0435\u0440\u0440\u0430\u0441\u044B \u0441 \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u0438\u043C\u0438 \u0441\u043B\u043E\u044F\u043C\u0438. \u0412 \u043F\u043B\u043E\u0441\u043A\u043E\u0439 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0435 \u0432\u0441\u0435 \u043A\u043E\u0441\u0442\u0438 \u043B\u0435\u0436\u0430\u0442 \u043D\u0430 \u043E\u0434\u043D\u043E\u043C \u0441\u043B\u043E\u0435. \u041F\u0440\u0430\u0432\u0438\u043B\u0430 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u044F \u0438 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0435 \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E\u0439 \u043B\u0435\u0432\u043E\u0439 \u0438\u043B\u0438 \u043F\u0440\u0430\u0432\u043E\u0439 \u0441\u0442\u043E\u0440\u043E\u043D\u044B \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B \u0434\u043B\u044F \u043E\u0431\u0435\u0438\u0445 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043E\u043A."),
            rule_section(:table_hk_aim, "Hong Kong \u2014 \u0426\u0435\u043B\u044C \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u0427\u0435\u0442\u0432\u0435\u0440\u043E \u0441\u0442\u0430\u0440\u0430\u044E\u0442\u0441\u044F \u043F\u0435\u0440\u0432\u044B\u043C\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043F\u0430\u0440\u0430 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u043D\u0430 3 \u0444\u0430\u043D\u044C, \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u0438 \u0440\u0443\u043A\u0438. \u041C\u0430\u0442\u0447 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u0442\u0435\u0440\u043C\u0438\u043D\u044B \u043E\u0431\u044A\u044F\u0441\u043D\u044F\u044E\u0442 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043E\u0447\u043A\u0438 \u0434\u043E \u043F\u0435\u0440\u0432\u043E\u0433\u043E \u0445\u043E\u0434\u0430."),
            rule_section(:table_hk_terms, "Hong Kong \u2014 \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0442\u0435\u0440\u043C\u0438\u043D\u043E\u0432",
              "\u0422\u044B \u0438\u0433\u0440\u0430\u0435\u0448\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0418\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443, \u0430 \u043D\u0435 \u0443\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u043F\u0430\u0440\u044B \u0441 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438, \u043A\u0430\u043A \u0432 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435. \u0420\u0443\u043A\u0430 \u2014 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438; \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u2014 \u0438\u0433\u0440\u0430 \u043E\u0442 \u0432\u044B\u0434\u0430\u0447\u0438 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439. \u041C\u0430\u0442\u0447 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0441\u0442\u043E\u044F\u0442\u044C \u0438\u0437 \u043C\u043D\u043E\u0433\u0438\u0445 \u0440\u0430\u0437\u0434\u0430\u0447.",
              "- \u041A\u043E\u0441\u0442\u044C \u2014 \u043E\u0434\u043D\u0430 \u0448\u0442\u0443\u043A\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0431\u0430\u043C\u0431\u0443\u043A 5. \u0415\u0451 \u0432\u0438\u0434 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044F \u043C\u0430\u0441\u0442\u044C\u044E \u0438 \u0447\u0438\u0441\u043B\u043E\u043C \u043B\u0438\u0431\u043E \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u043C \u0432\u0435\u0442\u0440\u043E\u043C \u0438\u043B\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u043C. \u041E\u0431\u044B\u0447\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u0438\u0434\u0430 \u0447\u0435\u0442\u044B\u0440\u0435.",
              "- \u041C\u0430\u0441\u0442\u0438 \u2014 \u0441\u0438\u043C\u0432\u043E\u043B\u044B, \u0431\u0430\u043C\u0431\u0443\u043A\u0438 \u0438 \u043A\u0440\u0443\u0433\u0438, \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438 1\u20139. \u041E\u0434\u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u043D\u0435 \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u043C\u0430\u0441\u0442\u0438. \u0422\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u2014 1 \u0438 9, \u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 2\u20138.",
              "- \u0411\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 \u0432\u0435\u0442\u0440\u044B \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440 \u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u044B \u0431\u0435\u043B\u044B\u0439, \u0437\u0435\u043B\u0451\u043D\u044B\u0439, \u043A\u0440\u0430\u0441\u043D\u044B\u0439. \u0423 \u043D\u0438\u0445 \u043D\u0435\u0442 \u0447\u0438\u0441\u0435\u043B, \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0435\u0439 \u043E\u043D\u0438 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442.",
              "- \u0427\u043E\u0443, \u0438\u043B\u0438 \u0447\u0438, \u2014 \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u043B\u0430 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438: \u0431\u0430\u043C\u0431\u0443\u043A\u0438 3, 4 \u0438 5. \u0411\u0430\u043C\u0431\u0443\u043A 3, \u043A\u0440\u0443\u0433 4 \u0438 \u0431\u0430\u043C\u0431\u0443\u043A 5 \u043D\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442; 8, 9 \u0438 1 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0442\u043E\u0436\u0435 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0447\u043E\u0443.",
              "- \u041F\u0430\u043D\u0433, \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043D \u0438\u043B\u0438 pong, \u2014 \u0442\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0442\u0440\u0438 \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430. \u0422\u0440\u0438 \u043F\u044F\u0442\u0451\u0440\u043A\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u043C\u0430\u0441\u0442\u0435\u0439 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043F\u0430\u043D\u0433.",
              "- \u041A\u043E\u043D\u0433, \u0438\u043B\u0438 \u043A\u0430\u043D, \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0415\u0433\u043E \u043D\u0443\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C; \u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0432 \u0440\u0443\u043A\u0435 \u0441\u0430\u043C\u043E \u043F\u043E \u0441\u0435\u0431\u0435 \u043A\u043E\u043D\u0433 \u043D\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442. \u041E\u043D \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u043E\u0439 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F.",
              "- \u041F\u0430\u0440\u0430 \u2014 \u0434\u0432\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0413\u0440\u0443\u043F\u043F\u0430 \u2014 \u0447\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043E\u0434\u043D\u0443 \u043F\u0430\u0440\u0443, \u0430 \u043D\u0435 \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0430\u0440 \u0438\u043B\u0438 \u043C\u043D\u043E\u0433\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438.",
              "- \u0421\u0442\u0435\u043D\u0430 \u2014 \u0437\u0430\u043F\u0430\u0441 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F. \u0412\u0437\u044F\u0442\u0438\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0432 \u0440\u0443\u043A\u0443; \u0441\u0431\u0440\u043E\u0441 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0438\u0437 \u0440\u0443\u043A\u0438 \u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C \u0435\u0451 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C.",
              "- \u0412 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435\u0442 \u0433\u0440\u0443\u043F\u043F, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043D\u0430 \u0447\u0443\u0436\u0438\u0445 \u043A\u043E\u0441\u0442\u044F\u0445. \u0427\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0443\u043A\u0443. \u0413\u0440\u0443\u043F\u043F\u044B \u0438\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043C\u043E\u0433\u0443\u0442 \u043E\u0441\u0442\u0430\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u0440\u0443\u043A\u0443 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442.",
              "- \u041F\u043E\u0431\u0435\u0434\u0430 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E \u0432\u0437\u044F\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C; \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u2014 \u043A\u043E\u0441\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430; \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C.",
              "- \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u2014 \u0432\u0438\u0434 \u043A\u043E\u0441\u0442\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442 \u0440\u0443\u043A\u0443. \u0421 \u0431\u0430\u043C\u0431\u0443\u043A\u0430\u043C\u0438 4\u20135 \u043C\u043E\u0436\u043D\u043E \u0436\u0434\u0430\u0442\u044C 3 \u0438\u043B\u0438 6. \u0422\u0435\u043C\u043F\u0430\u0439 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0434\u043E \u043F\u043E\u043B\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u044B \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438. \u0414\u043B\u044F \u0437\u0430\u043A\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0442\u0430\u043A\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u043F\u043E \u043E\u0447\u043A\u0430\u043C \u044D\u0442\u043E\u0433\u043E \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430.",
              "- \u0424\u0430\u043D\u044C \u2014 \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u0438 \u0440\u0443\u043A\u0438 \u0437\u0430 \u0443\u0437\u043E\u0440\u044B \u0438 \u043E\u0431\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u0441\u0442\u0432\u0430 \u043F\u043E\u0431\u0435\u0434\u044B. \u0414\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u043F\u0440\u043E\u0444\u0438\u043B\u044F \u043D\u0443\u0436\u043D\u043E \u043C\u0438\u043D\u0438\u043C\u0443\u043C 3 \u0444\u0430\u043D\u044C. \u0417\u0430\u0442\u0435\u043C \u043E\u043D\u0438 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u044F\u0442\u0441\u044F \u0432 \u043E\u0447\u043A\u0438 \u043C\u0430\u0442\u0447\u0430: 3 \u0444\u0430\u043D\u044C \u043D\u0435 \u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u0432\u044B\u0438\u0433\u0440\u044B\u0448 \u0442\u043E\u043B\u044C\u043A\u043E 3 \u043E\u0447\u043A\u043E\u0432.",
              "- \u0421\u0432\u043E\u0439 \u0432\u0435\u0442\u0435\u0440 \u2014 \u0440\u043E\u043B\u044C \u0432 \u0440\u0430\u0437\u0434\u0430\u0447\u0435: \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u0412\u043E\u0441\u0442\u043E\u043A, \u0434\u0430\u043B\u0435\u0435 \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440. \u0412\u0435\u0442\u0435\u0440 \u0440\u0430\u0443\u043D\u0434\u0430 \u043E\u0431\u0449\u0438\u0439 \u0434\u043B\u044F \u0441\u0442\u043E\u043B\u0430. \u041F\u0430\u043D\u0433 \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430 \u0438\u043B\u0438 \u0432\u0435\u0442\u0440\u0430 \u0440\u0430\u0443\u043D\u0434\u0430 \u043C\u043E\u0436\u0435\u0442 \u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0447\u043A\u0438; \u043E\u0434\u043D\u043E\u0439 \u043F\u0430\u0440\u044B \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u043D\u0430\u0433\u0440\u0430\u0434\u044B \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E.",
              "- \u0426\u0432\u0435\u0442\u044B \u0438 \u0441\u0435\u0437\u043E\u043D\u044B \u2014 \u0431\u043E\u043D\u0443\u0441\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0418\u0433\u0440\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0438 \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u0438\u0445. \u041E\u043D\u0438 \u043D\u0435 \u0432\u0445\u043E\u0434\u044F\u0442 \u0432 \u0447\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043F\u0430\u0440\u0443 \u0438 \u043D\u0435 \u043E\u0431\u043E\u0437\u043D\u0430\u0447\u0430\u044E\u0442 \u0440\u0430\u0443\u043D\u0434\u044B \u0432\u0435\u0442\u0440\u043E\u0432."),
            rule_section(:table_hk_start, "Hong Kong \u2014 \u041D\u0430\u0447\u0430\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447\u0438",
              "\u0411\u0430\u043B\u0430\u043D\u0441\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F; \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442 \u043E\u0447\u043A\u0438, \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442.",
              "\u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 14 \u043A\u043E\u0441\u0442\u044F\u043C\u0438 \u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u2014 \u0441 13. \u0412 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434 \u0432\u044B\u0431\u0435\u0440\u0438 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0441\u043F\u0438\u0441\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0431\u0435\u0440\u0451\u0442. \u0415\u0441\u043B\u0438 \u0442\u044B \u0441\u0434\u0430\u044E\u0449\u0438\u0439, \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0443\u0436\u0435 \u0435\u0441\u0442\u044C, \u0435\u0449\u0451 \u043E\u0434\u043D\u043E \u0432\u0437\u044F\u0442\u0438\u0435 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F."),
            rule_section(:table_hk_play, "Hong Kong \u2014 \u041F\u0435\u0440\u0432\u044B\u0435 \u0445\u043E\u0434\u044B \u043F\u043E \u0448\u0430\u0433\u0430\u043C",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0435\u0440\u0432\u044B\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437. \u0418\u0449\u0438 \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u0435 \u0447\u0438\u0441\u043B\u0430 \u0434\u043B\u044F \u0447\u043E\u0443, \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u0434\u043B\u044F \u043F\u0430\u043D\u0433\u043E\u0432 \u0438 \u043E\u0434\u043D\u0443 \u0431\u0443\u0434\u0443\u0449\u0443\u044E \u043F\u0430\u0440\u0443. \u0413\u0440\u0443\u043F\u043F\u044B, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0432 \u0440\u0443\u043A\u0435, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0442\u043C\u0435\u0447\u0430\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E: \u0438\u0433\u0440\u0430 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0451\u0442 \u0438\u0445 \u043F\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0438 \u043F\u043E\u0431\u0435\u0434\u044B.",
              "\u0415\u0441\u043B\u0438 \u0442\u044B \u0432 \u0438\u0433\u0440\u043E\u0432\u044B\u0445 \u043F\u043E\u043B\u044F\u0445, \u043D\u043E\u0432\u044B\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442 \u0444\u043E\u043A\u0443\u0441 \u043D\u0430 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0444\u043E\u043A\u0443\u0441 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u043D\u0430 \u043D\u043E\u0432\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0441 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043F\u043E\u043C\u0435\u0442\u043A\u043E\u0439. \u042D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441: \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A \u0434\u0440\u0443\u0433\u0438\u043C \u043A\u043E\u0441\u0442\u044F\u043C, \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0438 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u0443\u044E.",
              "\u0414\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430 \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0445 \u0441\u0431\u0440\u043E\u0441\u043E\u0432 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0423\u0445\u043E\u0434\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u043E\u0442 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440. \u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0431\u044B\u043B\u043E \u0442\u0440\u0438, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0432\u0435 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F.",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0442\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0448\u044C \u043A\u043E\u0441\u0442\u044C \u0438 \u0443\u0432\u0438\u0434\u0438\u0448\u044C \u043E\u0442\u0432\u0435\u0442\u044B. \u041F\u0430\u0441 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u044D\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438, \u0430 \u043D\u0435 \u0432\u044B\u0445\u043E\u0434 \u0438\u043B\u0438 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0448. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u043F\u0430\u0441\u0443\u044E\u0442, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0431\u0435\u0440\u0451\u0442 \u043A\u043E\u0441\u0442\u044C. \u0414\u043E \u0442\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u043D\u043E\u0433\u0434\u0430 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0430\u0441.",
              "\u041F\u0435\u0440\u0432\u043E\u0435 \u043F\u043E\u043B\u0435 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0421\u0440\u0430\u0437\u0443 \u0437\u0430 \u043D\u0438\u043C \u0432\u0441\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F: \u043E\u0442\u0432\u0435\u0442\u044B, \u0432\u0437\u044F\u0442\u0438\u0435, \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u043A\u043E\u043D\u0433\u0438 \u0438\u043B\u0438 \u0440\u0438\u0438\u0447\u0438, \u0435\u0441\u043B\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438\u0445 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442. \u0417\u0430\u0442\u0435\u043C \u0438\u0434\u0443\u0442 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438. Tab \u0438 Shift+Tab \u043C\u0435\u043D\u044F\u044E\u0442 \u043F\u043E\u043B\u0435, \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043F\u0443\u043D\u043A\u0442, Enter \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442. \u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
              "\u041F\u043E\u043B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0445 \u0433\u0440\u0443\u043F\u043F \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0433\u0440\u0443\u043F\u043F\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0441 \u0438\u043C\u0435\u043D\u0430\u043C\u0438 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0435\u0432. \u0421\u0431\u0440\u043E\u0441\u044B \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442, \u043A\u0442\u043E \u043A\u0430\u043A\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u043B. \u0422\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043D\u044F\u0442\u044C, \u0447\u0442\u043E \u0443\u0436\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043E \u0438 \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C. \u0421\u0430\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0445\u043E\u0434 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442.",
              "\u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0440\u0443\u043A\u0443, \u0432\u044B\u0431\u0435\u0440\u0438 \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u0430 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441 \u0438\u043B\u0438 \u043F\u0430\u0441. \u0418\u0433\u0440\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0444\u043E\u0440\u043C\u0443 \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E \u043E\u0447\u043A\u0430\u043C. \u0415\u0441\u043B\u0438 \u0440\u0430\u043D\u044C\u0448\u0435 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0441\u0442\u0435\u043D\u0430, \u0431\u0443\u0434\u0435\u0442 \u043D\u0438\u0447\u044C\u044F; \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0430\u044F \u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044E \u0440\u0443\u043A\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043D\u0435 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442.",
              "S \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u043E\u0447\u043A\u0438 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. M \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F \u0432 \u0441\u0442\u0435\u043D\u0435. \u041E\u043D\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u043E\u0431\u0449\u0430\u044E\u0442: \u043D\u0435 \u0431\u0435\u0440\u0443\u0442, \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442, \u043D\u0435 \u043F\u0430\u0441\u0443\u044E\u0442 \u0438 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u0447\u0443\u0436\u0438\u0435 \u0440\u0443\u043A\u0438.",
              "W \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0438: \u0444\u0430\u043D \u043B\u0438\u0431\u043E \u0445\u0430\u043D \u0438 \u0444\u0443, \u0430 \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u043C\u044B\u0435 \u043E\u0447\u043A\u0438. \u0411\u0435\u0437 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0443\u043A\u0438 \u043D\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u0414\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u0440\u0438\u0438\u0447\u0438 \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u0443\u0440\u0430-\u0434\u043E\u0440\u0430 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0432\u044B\u0448\u0435. U \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0432\u043E\u0438 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438, Shift+U \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445, R \u043D\u043E\u043C\u0435\u0440 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0432\u0435\u0442\u0440\u044B \u0438 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0412 \u0440\u0438\u0438\u0447\u0438 I \u0447\u0438\u0442\u0430\u0435\u0442 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0438 \u043A\u0430\u043C\u043D\u0438 \u0434\u043E\u0440\u0430, \u0447\u0438\u0441\u043B\u043E \u0442\u0432\u043E\u0438\u0445 \u0434\u043E\u0440\u0430, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0440\u0438\u0438\u0447\u0438, \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B, \u0445\u043E\u043D\u0431\u0430 \u0438 \u0442\u0432\u043E\u0439 \u0444\u0443\u0440\u0438\u0442\u0435\u043D. \u042D\u0442\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0442\u0430\u044E\u0442 \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E."),
            rule_section(:table_hand, "Hong Kong \u2014 \u0427\u0442\u043E \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u0421\u043E\u0431\u0435\u0440\u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u0447\u043E\u0443, \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u0438 \u043F\u0430\u0440\u0443, \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044F \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u0438 \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0432 \u0440\u0443\u043A\u0435 \u0433\u0440\u0443\u043F\u043F\u044B. \u0427\u043E\u0443 \u2014 \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u043B\u0430 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, \u043F\u0443\u043D\u0433 \u2014 \u0442\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u043A\u043E\u043D\u0433 \u2014 \u0447\u0435\u0442\u044B\u0440\u0435, \u043F\u0430\u0440\u0430 \u2014 \u0434\u0432\u0435. \u041D\u0443\u0436\u043D\u044B \u0442\u0430\u043A\u0436\u0435 3 \u0444\u0430\u043D. \u041F\u0440\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0438 \u043E\u0431\u043E\u0438\u0445 \u0443\u0441\u043B\u043E\u0432\u0438\u0439 \u0432\u044B\u0431\u0435\u0440\u0438 \u041E\u0431\u044A\u044F\u0432\u0438\u0442\u044C Mahjong \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041F\u043E\u043B\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u043F\u0440\u0435\u043C\u0438\u0439 \u043F\u0440\u0438\u0432\u0435\u0434\u0451\u043D \u0434\u0430\u043B\u0435\u0435; \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0435\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u0441\u0430\u043C\u043E \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u0440\u0430\u0437\u0434\u0430\u0447\u0443."),
            rule_section(:table_hk_claims, "Hong Kong \u2014 \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u043A\u043E\u043D\u0433\u043E\u0432",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0442\u0432\u0435\u0442\u043E\u0432 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u0430, \u0432\u044B\u0431\u0435\u0440\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A. \u0418\u043D\u0430\u0447\u0435 \u0432\u044B\u0431\u0435\u0440\u0438 \u0447\u043E\u0443, \u043F\u043E\u043D\u0433, \u043A\u043E\u043D\u0433 \u0438\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0427\u043E\u0443 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u043B\u0438\u0448\u044C \u0443 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E \u043F\u043E \u0445\u043E\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u043F\u043E\u0434\u043E\u0439\u0434\u0451\u0442 \u0441\u0431\u0440\u043E\u0441 \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "\u041F\u043E\u0431\u0435\u0434\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u043D\u0430 \u0433\u0440\u0443\u043F\u043F\u0443, \u0430 \u043F\u043E\u043D\u0433 \u0438 \u043A\u043E\u043D\u0433 \u0432\u0430\u0436\u043D\u0435\u0435 \u0447\u043E\u0443. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u043C\u043E\u0433\u0443\u0442 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043F\u043E\u0441\u043B\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0435\u0433\u043E. \u0418\u0433\u0440\u0430 \u0436\u0434\u0451\u0442 \u0432\u0441\u0435\u0445 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043E\u0442\u0432\u0435\u0442\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0447\u043E\u0443 \u0438\u043B\u0438 \u043F\u043E\u043D\u0433\u0430 \u0441\u0431\u0440\u043E\u0441\u044C \u043A\u043E\u0441\u0442\u044C \u0431\u0435\u0437 \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0437 \u0441\u0442\u0435\u043D\u044B; \u0433\u0440\u0443\u043F\u043F\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u043A\u043E\u043D\u0433\u0430 \u0432\u043E\u0437\u044C\u043C\u0438 \u0437\u0430\u043C\u0435\u0449\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438 \u043B\u0438\u0448\u044C \u0437\u0430\u0442\u0435\u043C \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u0430 \u0443 \u0442\u0435\u0431\u044F, \u043E\u0431\u044A\u044F\u0432\u0438 \u0438\u0445 \u0447\u0435\u0440\u0435\u0437 \u0441\u043F\u0438\u0441\u043E\u043A \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043A\u043E\u043D\u0433\u043E\u0432. \u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u043A \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C\u0443 \u043F\u043E\u043D\u0433\u0443. \u041F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0442\u0430\u043A\u043E\u0439 \u043A\u043E\u043D\u0433 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u043C\u043E\u0439 \u043A\u043E\u0441\u0442\u0438.",
              "\u0415\u0441\u043B\u0438 \u0443 \u0442\u0435\u0431\u044F \u0434\u0432\u0430 \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430 \u0438 \u043A\u0442\u043E-\u0442\u043E \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E, \u041F\u0430\u043D\u0433 \u0437\u0430\u0431\u0438\u0440\u0430\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0438 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u0442\u0440\u0438. \u0417\u0430\u0442\u0435\u043C \u043D\u0443\u0436\u043D\u043E \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0431\u0435\u0437 \u0432\u0437\u044F\u0442\u0438\u044F. \u0421 \u0431\u0430\u043C\u0431\u0443\u043A\u0430\u043C\u0438 4\u20135 \u043C\u043E\u0436\u043D\u043E \u0432\u0437\u044F\u0442\u044C 3 \u0438\u043B\u0438 6 \u0432 \u0447\u043E\u0443 \u0442\u043E\u043B\u044C\u043A\u043E \u0443 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430, \u043D\u0435 \u0443 \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430."),
            rule_section(:table_hk_sets, "\u0413\u043E\u043D\u043A\u043E\u043D\u0433 \u2014 \u043F\u043E\u043B\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u043F\u0440\u0435\u043C\u0438\u0439",
              "\u041E\u0431\u044B\u0447\u043D\u0430\u044F \u043F\u043E\u0431\u0435\u0434\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u0433\u0440\u0443\u043F\u043F \u0438 \u043F\u0430\u0440\u044B \u0438 \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 3 \u0444\u0430\u043D. \u0421\u0435\u043C\u044C \u043F\u0430\u0440 \u0438 \u0442\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0438\u0440\u043E\u0442 \u0438\u043C\u0435\u044E\u0442 \u0434\u0440\u0443\u0433\u0443\u044E \u0444\u043E\u0440\u043C\u0443. \u041D\u0438\u0436\u0435 \u043F\u043E\u043B\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u043F\u0440\u0435\u043C\u0438\u0439 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438; \u0431\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u043E\u0433\u0440\u0430\u043D\u0438\u0447\u0435\u043D\u0438\u044F \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0435 \u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0435 \u0440\u0443\u043A\u0438. \u041E\u0431\u044B\u0447\u043D\u043E\u0435 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0435 \u0447\u043E\u0443, \u0447\u0438\u0441\u043B\u043E\u0432\u043E\u0439 \u043F\u0443\u043D\u0433 \u0438\u043B\u0438 \u043F\u0430\u0440\u0430 \u0441\u0432\u043E\u0435\u0439 \u043F\u0440\u0435\u043C\u0438\u0438 \u043D\u0435 \u0434\u0430\u044E\u0442.",
              "\u0421\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u043F\u0440\u0435\u043C\u0438\u0438 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u041C\u0430\u043B\u044B\u0435 \u0438 \u0431\u043E\u043B\u044C\u0448\u0438\u0435 \u0442\u0440\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u0430 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442 \u0431\u043E\u043D\u0443\u0441\u044B \u0437\u0430 \u0441\u043E\u0441\u0442\u0430\u0432\u043B\u044F\u044E\u0449\u0438\u0435 \u0438\u0445 \u043F\u0443\u043D\u0433\u0438. \u0414\u043B\u044F \u0441\u043F\u0435\u0446\u0438\u0430\u043B\u044C\u043D\u044B\u0445 \u0440\u0443\u043A \u043E\u0442 10 \u0444\u0430\u043D \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0430\u044F \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0430\u044F \u0441\u043F\u0435\u0446\u0438\u0430\u043B\u044C\u043D\u0430\u044F \u043F\u0440\u0435\u043C\u0438\u044F, \u0431\u0435\u0437 \u043E\u0431\u044B\u0447\u043D\u044B\u0445 \u0431\u043E\u043D\u0443\u0441\u043E\u0432. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430 \u0438 \u0447\u0435\u0442\u044B\u0440\u0435 \u0441\u043A\u0440\u044B\u0442\u044B\u0445 \u043F\u0443\u043D\u0433\u0430 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0439 \u043F\u0440\u0435\u043C\u0438\u0438 \u043D\u0435 \u0434\u0430\u044E\u0442. \u0412\u0441\u0435 \u0432\u043E\u0441\u0435\u043C\u044C \u0431\u043E\u043D\u0443\u0441\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u0430\u044E\u0442 4 \u0444\u0430\u043D; \u0441\u0435\u043C\u044C \u043F\u0430\u0440 \u0434\u0430\u044E\u0442 4 \u0444\u0430\u043D."),
            rule_section(:table_hk_fan_1, "Hong Kong: 1 \u0444\u0430\u043D",
              "- 1 \u0444\u0430\u043D \u2014 \u0421\u0430\u043C\u043E\u0441\u0442\u043E\u044F\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438.",
              "- 1 \u0444\u0430\u043D \u2014 \u0422\u043E\u043B\u044C\u043A\u043E \u0447\u043E\u0443: \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0438 \u043F\u0430\u0440\u0430, \u0432 \u0442\u043E\u043C \u0447\u0438\u0441\u043B\u0435 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445.",
