            rule_section(:table_hk_payments, "Hong Kong \u2014 \u041E\u0447\u043A\u0438 \u0438 \u0432\u044B\u043F\u043B\u0430\u0442\u044B",
              "\u041E\u0441\u043D\u043E\u0432\u0430 \u0432\u044B\u043F\u043B\u0430\u0442\u044B: 3 \u0444\u0430\u043D \u2014 8 \u043E\u0447\u043A\u043E\u0432; 4 \u2014 16; 5 \u2014 24; 6 \u2014 32; 7 \u2014 48; 8 \u0438 \u0431\u043E\u043B\u0435\u0435 \u2014 64. \u0420\u0443\u043A\u0430 \u043C\u043E\u0436\u0435\u0442 \u0441\u0442\u043E\u0438\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435 8 \u0444\u0430\u043D, \u043D\u043E \u043E\u0441\u043D\u043E\u0432\u0430 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u0431\u043E\u043B\u044C\u0448\u0435 \u043D\u0435 \u0440\u0430\u0441\u0442\u0451\u0442.",
              "\u041F\u0440\u0438 \u043F\u043E\u0431\u0435\u0434\u0435 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0438\u0439 \u043F\u043B\u0430\u0442\u0438\u0442 \u0434\u0432\u0435 \u043E\u0441\u043D\u043E\u0432\u044B, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043F\u043E \u043E\u0434\u043D\u043E\u0439. \u041F\u0440\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u043C \u0432\u0437\u044F\u0442\u0438\u0438 \u043A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u043B\u0430\u0442\u0438\u0442 \u0434\u0432\u0435 \u043E\u0441\u043D\u043E\u0432\u044B.",
              "\u041D\u0435\u0431\u0435\u0441\u043D\u0430\u044F \u0438 \u0437\u0435\u043C\u043D\u0430\u044F \u0440\u0443\u043A\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432 \u0438\u0433\u0440\u0435 \u043D\u0435 \u043F\u0440\u0435\u043C\u0438\u0440\u0443\u044E\u0442\u0441\u044F. \u041D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0439 \u0437\u0430 \u043D\u0438\u0445 \u0431\u043E\u043D\u0443\u0441 \u0437\u0430 \u043F\u043E\u0431\u0435\u0434\u0443 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438."),
            rule_section(:table_winds, "Hong Kong \u2014 \u0420\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u0434\u043B\u0438\u043D\u0430 \u043C\u0430\u0442\u0447\u0430",
              "\u041C\u0430\u0442\u0447 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u043C\u0435\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0443\u043D\u0434\u0430: \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440. \u0412 \u043A\u0430\u0436\u0434\u043E\u043C \u0432\u0441\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u043F\u0435\u0440\u0438\u043E\u0434 \u0441\u0434\u0430\u0447\u0438, \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u0430\u0437\u0434\u0430\u0447. \u0412\u044B\u043F\u043B\u0430\u0442\u044B \u043D\u0430\u043A\u0430\u043F\u043B\u0438\u0432\u0430\u044E\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F; \u043E\u0434\u043D\u0430 \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u0430\u044F \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0440\u0443\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0443 \u043C\u0430\u0442\u0447\u0430.",
              "\u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0441\u0432\u043E\u0435\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043B\u044E\u0431\u043E\u0439 \u043D\u0438\u0447\u044C\u0435\u0439. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0412\u043E\u0441\u0442\u043E\u043A \u2014 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0438\u043D\u043E\u0433\u0434\u0430 \u0431\u043E\u043B\u044C\u0448\u0435. \u0427\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u2014 \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440: \u043C\u0438\u043D\u0438\u043C\u0443\u043C 16 \u0440\u0430\u0437\u0434\u0430\u0447. \u0421\u0435\u0437\u043E\u043D\u044B \u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0431\u043E\u043D\u0443\u0441\u043D\u044B\u043C\u0438 \u043A\u043E\u0441\u0442\u044F\u043C\u0438, \u0430 \u043D\u0435 \u044D\u0442\u0438\u043C\u0438 \u044D\u0442\u0430\u043F\u0430\u043C\u0438.",
              "\u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044C \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044F, \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0438 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F \u043E\u0447\u043A\u043E\u0432. \u0412 \u0434\u043B\u0438\u043D\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0432\u0441\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0442 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C \u043A \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0440\u0430\u0437\u0434\u0430\u0447\u0435. \u041D\u0438\u0447\u044C\u044F \u0432 \u0413\u043E\u043D\u043A\u043E\u043D\u0433\u0435 \u043E\u0447\u043A\u0438 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442. \u041F\u043E\u0441\u043B\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0445 \u0440\u0430\u0443\u043D\u0434\u043E\u0432 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441; \u0440\u0430\u0432\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C\u044B \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E."),
            rule_section(:table_hk_variants, "Hong Kong \u2014 \u0412\u044B\u0431\u043E\u0440 \u0434\u043B\u0438\u043D\u044B \u0438\u0433\u0440\u044B",
              "\u0414\u043B\u0438\u043D\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u0430. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u043C\u0435\u043D\u044F\u044E\u0442 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447, \u0430 \u043D\u0435 \u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u043E\u0439 \u0440\u0443\u043A\u0438.",
              "\u041E\u0434\u043D\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u043E\u0439 \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043F\u043E \u0441\u0442\u0435\u043D\u0435. \u0412\u043E\u0441\u0442\u043E\u0447\u043D\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0432\u0441\u0435 \u0447\u0435\u0442\u0432\u0435\u0440\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0442 \u0441\u0432\u043E\u0439 \u043F\u0435\u0440\u0438\u043E\u0434 \u0441\u0434\u0430\u0447\u0438. \u0423 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0441\u0432\u043E\u0439 \u0412\u043E\u0441\u0442\u043E\u043A, \u0438 \u043E\u0431\u0449\u0438\u0439 \u0432\u0435\u0442\u0435\u0440 \u0440\u0430\u0443\u043D\u0434\u0430 \u0432\u0441\u0451 \u044D\u0442\u043E \u0432\u0440\u0435\u043C\u044F \u0442\u043E\u0436\u0435 \u0412\u043E\u0441\u0442\u043E\u043A. \u042D\u0442\u043E \u043D\u0435 \u043E\u0434\u0438\u043D \u043B\u0438\u0447\u043D\u044B\u0439 \u0445\u043E\u0434."),
            rule_section(:table_riichi_aim, "Riichi \u2014 \u0426\u0435\u043B\u044C \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u0412 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0438\u0433\u0440\u0435 \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C \u043D\u0443\u0436\u043D\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0440\u0443\u043A\u0443 \u0440\u0430\u043D\u044C\u0448\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u043E\u0432. \u041E\u0431\u044B\u0447\u043D\u043E \u044D\u0442\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043F\u0430\u0440\u0430, \u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u044F\u043A\u0443, \u043F\u0440\u0438\u0437\u043D\u0430\u043D\u043D\u043E\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u044B. \u041F\u043E\u043B\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u0431\u0435\u0437 \u044F\u043A\u0443 \u043C\u043E\u0436\u0435\u0442 \u043D\u0435 \u043F\u043E\u0437\u0432\u043E\u043B\u0438\u0442\u044C \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C. \u0412 \u043C\u0430\u0442\u0447\u0435 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0438\u0442\u043E\u0433\u043E\u0432\u044B\u0439 \u0441\u0447\u0451\u0442; \u0442\u0435\u0440\u043C\u0438\u043D\u044B \u043E\u0431\u044A\u044F\u0441\u043D\u0435\u043D\u044B \u0434\u0430\u043B\u0435\u0435."),
            rule_section(:table_riichi_terms, "Riichi \u2014 \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0442\u0435\u0440\u043C\u0438\u043D\u043E\u0432",
              "\u0422\u044B \u0438\u0433\u0440\u0430\u0435\u0448\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0418\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443, \u0430 \u043D\u0435 \u0443\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u043F\u0430\u0440\u044B \u0441 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438, \u043A\u0430\u043A \u0432 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435. \u0420\u0443\u043A\u0430 \u2014 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438; \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u2014 \u0438\u0433\u0440\u0430 \u043E\u0442 \u0432\u044B\u0434\u0430\u0447\u0438 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439. \u041C\u0430\u0442\u0447 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0441\u0442\u043E\u044F\u0442\u044C \u0438\u0437 \u043C\u043D\u043E\u0433\u0438\u0445 \u0440\u0430\u0437\u0434\u0430\u0447.",
              "- \u041A\u043E\u0441\u0442\u044C \u2014 \u043E\u0434\u043D\u0430 \u0448\u0442\u0443\u043A\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0431\u0430\u043C\u0431\u0443\u043A 5. \u0415\u0451 \u0432\u0438\u0434 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044F \u043C\u0430\u0441\u0442\u044C\u044E \u0438 \u0447\u0438\u0441\u043B\u043E\u043C \u043B\u0438\u0431\u043E \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u043C \u0432\u0435\u0442\u0440\u043E\u043C \u0438\u043B\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u043C. \u041E\u0431\u044B\u0447\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u0438\u0434\u0430 \u0447\u0435\u0442\u044B\u0440\u0435.",
              "- \u041C\u0430\u0441\u0442\u0438 \u2014 \u0441\u0438\u043C\u0432\u043E\u043B\u044B, \u0431\u0430\u043C\u0431\u0443\u043A\u0438 \u0438 \u043A\u0440\u0443\u0433\u0438, \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438 1\u20139. \u041E\u0434\u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u043D\u0435 \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u043C\u0430\u0441\u0442\u0438. \u0422\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u2014 1 \u0438 9, \u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 2\u20138.",
              "- \u0411\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 \u0432\u0435\u0442\u0440\u044B \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440 \u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u044B \u0431\u0435\u043B\u044B\u0439, \u0437\u0435\u043B\u0451\u043D\u044B\u0439, \u043A\u0440\u0430\u0441\u043D\u044B\u0439. \u0423 \u043D\u0438\u0445 \u043D\u0435\u0442 \u0447\u0438\u0441\u0435\u043B, \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0435\u0439 \u043E\u043D\u0438 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442.",
              "- \u0427\u043E\u0443, \u0438\u043B\u0438 \u0447\u0438, \u2014 \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u043B\u0430 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438: \u0431\u0430\u043C\u0431\u0443\u043A\u0438 3, 4 \u0438 5. \u0411\u0430\u043C\u0431\u0443\u043A 3, \u043A\u0440\u0443\u0433 4 \u0438 \u0431\u0430\u043C\u0431\u0443\u043A 5 \u043D\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442; 8, 9 \u0438 1 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0442\u043E\u0436\u0435 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0447\u043E\u0443.",
              "- \u041F\u0430\u043D\u0433, \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043D \u0438\u043B\u0438 pong, \u2014 \u0442\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0442\u0440\u0438 \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430. \u0422\u0440\u0438 \u043F\u044F\u0442\u0451\u0440\u043A\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u043C\u0430\u0441\u0442\u0435\u0439 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043F\u0430\u043D\u0433.",
              "- \u041A\u043E\u043D\u0433, \u0438\u043B\u0438 \u043A\u0430\u043D, \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0415\u0433\u043E \u043D\u0443\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C; \u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0432 \u0440\u0443\u043A\u0435 \u0441\u0430\u043C\u043E \u043F\u043E \u0441\u0435\u0431\u0435 \u043A\u043E\u043D\u0433 \u043D\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442. \u041E\u043D \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u043E\u0439 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F.",
              "- \u041F\u0430\u0440\u0430 \u2014 \u0434\u0432\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0413\u0440\u0443\u043F\u043F\u0430 \u2014 \u0447\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043E\u0434\u043D\u0443 \u043F\u0430\u0440\u0443, \u0430 \u043D\u0435 \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0430\u0440 \u0438\u043B\u0438 \u043C\u043D\u043E\u0433\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438.",
              "- \u0421\u0442\u0435\u043D\u0430 \u2014 \u0437\u0430\u043F\u0430\u0441 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F. \u0412\u0437\u044F\u0442\u0438\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0432 \u0440\u0443\u043A\u0443; \u0441\u0431\u0440\u043E\u0441 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0438\u0437 \u0440\u0443\u043A\u0438 \u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C \u0435\u0451 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C.",
              "- \u0412 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435\u0442 \u0433\u0440\u0443\u043F\u043F, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043D\u0430 \u0447\u0443\u0436\u0438\u0445 \u043A\u043E\u0441\u0442\u044F\u0445. \u0427\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0443\u043A\u0443. \u0413\u0440\u0443\u043F\u043F\u044B \u0438\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043C\u043E\u0433\u0443\u0442 \u043E\u0441\u0442\u0430\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u0440\u0443\u043A\u0443 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442.",
              "- \u041F\u043E\u0431\u0435\u0434\u0430 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E \u0432\u0437\u044F\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C; \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u2014 \u043A\u043E\u0441\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430; \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C.",
              "- \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u2014 \u0432\u0438\u0434 \u043A\u043E\u0441\u0442\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442 \u0440\u0443\u043A\u0443. \u0421 \u0431\u0430\u043C\u0431\u0443\u043A\u0430\u043C\u0438 4\u20135 \u043C\u043E\u0436\u043D\u043E \u0436\u0434\u0430\u0442\u044C 3 \u0438\u043B\u0438 6. \u0422\u0435\u043C\u043F\u0430\u0439 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0434\u043E \u043F\u043E\u043B\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u044B \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438. \u0414\u043B\u044F \u0437\u0430\u043A\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0442\u0430\u043A\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u043F\u043E \u043E\u0447\u043A\u0430\u043C \u044D\u0442\u043E\u0433\u043E \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430.",
              "- \u042F\u043A\u0443 \u2014 \u0438\u043C\u0435\u043D\u043E\u0432\u0430\u043D\u043D\u043E\u0435 \u0443\u0441\u043B\u043E\u0432\u0438\u0435, \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u044E\u0449\u0435\u0435 \u043F\u043E\u0431\u0435\u0434\u0443 \u0441 \u043F\u043E\u043B\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u043E\u0439. \u041D\u0443\u0436\u043D\u043E \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u043E\u0434\u043D\u043E \u044F\u043A\u0443. \u041F\u0430\u043D\u0433 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u044F\u043A\u0443, \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u043B\u044C\u043D\u0430\u044F \u043F\u043E\u043B\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u043D\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E.",
              "- \u0425\u0430\u043D \u0438\u0437\u043C\u0435\u0440\u044F\u044E\u0442 \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u044F\u043A\u0443 \u0438 \u0431\u043E\u043D\u0443\u0441\u043E\u0432. \u0424\u0443 \u2014 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0447\u043A\u0438 \u0437\u0430 \u0433\u0440\u0443\u043F\u043F\u044B, \u043F\u0430\u0440\u0443 \u0438 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0435. \u0412\u043C\u0435\u0441\u0442\u0435 \u043E\u043D\u0438 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442 \u0432\u044B\u043F\u043B\u0430\u0442\u0443. \u041E\u0434\u043D\u0438 \u0444\u0443 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0435 \u044F\u043A\u0443 \u043D\u0435 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442.",
              "- \u0420\u043E\u043D \u2014 \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0447\u0443\u0436\u043E\u043C \u0441\u0431\u0440\u043E\u0441\u0435, \u0446\u0443\u043C\u043E \u2014 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F. \u041C\u044D\u043D\u0434\u0437\u044D\u043D \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0441\u0442\u044C. \u041C\u044D\u043D\u0434\u0437\u044D\u043D \u0446\u0443\u043C\u043E \u2014 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u0441 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u043E\u0439 \u0438 \u0441\u0430\u043C\u043E \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u044F\u043A\u0443.",
              "- \u0420\u0438\u0438\u0447\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442, \u0447\u0442\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438. \u0422\u044B \u043E\u0442\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0448\u044C 1000 \u043E\u0447\u043A\u043E\u0432 \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0448\u044C \u044F\u043A\u0443, \u043D\u043E \u0443\u0436\u0435 \u043D\u0435 \u043C\u043E\u0436\u0435\u0448\u044C \u0441\u0432\u043E\u0431\u043E\u0434\u043D\u043E \u043F\u0435\u0440\u0435\u0441\u0442\u0440\u0430\u0438\u0432\u0430\u0442\u044C \u0440\u0443\u043A\u0443.",
              "- \u0414\u043E\u0440\u0430 \u2014 \u0431\u043E\u043D\u0443\u0441\u043D\u044B\u0439 \u0432\u0438\u0434 \u043A\u043E\u0441\u0442\u0438, \u0437\u0430\u0434\u0430\u043D\u043D\u044B\u0439 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u043E\u043C. \u041A\u0430\u0436\u0434\u044B\u0439 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u0445\u0430\u043D \u043F\u0440\u0438 \u043D\u0430\u043B\u0438\u0447\u0438\u0438 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u0433\u043E \u044F\u043A\u0443. \u041E\u0434\u043D\u0438 \u0434\u043E\u0440\u044B \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u044C \u043D\u0435 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u044E\u0442.",
              "- \u0424\u0443\u0440\u0438\u0442\u0435\u043D \u0437\u0430\u043F\u0440\u0435\u0449\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0447\u0443\u0436\u043E\u043C \u0441\u0431\u0440\u043E\u0441\u0435. \u041E\u043D \u043C\u043E\u0436\u0435\u0442 \u0432\u043E\u0437\u043D\u0438\u043A\u043D\u0443\u0442\u044C \u0438\u0437-\u0437\u0430 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u0441\u0431\u0440\u043E\u0441\u043E\u0432 \u0438\u043B\u0438 \u043F\u0440\u043E\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0431\u0435\u0434\u0435 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u043E\u043D \u043D\u0435 \u043C\u0435\u0448\u0430\u0435\u0442.",
              "- \u0425\u043E\u043D\u0431\u0430 \u2014 \u0441\u0447\u0451\u0442\u0447\u0438\u043A \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0432\u044B\u043F\u043B\u0430\u0442 \u043F\u043E\u0441\u043B\u0435 \u043D\u0438\u0447\u044C\u0438\u0445 \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u043E\u0432 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E. \u041C\u0430\u043D\u0433\u0430\u043D \u0438 \u0431\u043E\u043B\u0435\u0435 \u0432\u044B\u0441\u043E\u043A\u0438\u0435 \u043F\u0440\u0435\u0434\u0435\u043B\u044B \u2014 \u0443\u0440\u043E\u0432\u043D\u0438 \u0432\u044B\u043F\u043B\u0430\u0442 \u0437\u0430 \u0446\u0435\u043D\u043D\u044B\u0435 \u0440\u0443\u043A\u0438, \u0430 \u043D\u0435 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0433\u0440\u0443\u043F\u043F\u044B.",
              "- \u0421\u0432\u043E\u0439 \u0432\u0435\u0442\u0435\u0440 \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u0434\u0430\u044E\u0449\u0438\u043C: \u0443 \u043D\u0435\u0433\u043E \u0412\u043E\u0441\u0442\u043E\u043A, \u0434\u0430\u043B\u0435\u0435 \u042E\u0433, \u0417\u0430\u043F\u0430\u0434 \u0438 \u0421\u0435\u0432\u0435\u0440. \u0412\u0435\u0442\u0435\u0440 \u0440\u0430\u0443\u043D\u0434\u0430 \u043E\u0431\u0449\u0438\u0439. \u041F\u0430\u043D\u0433 \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430 \u0438\u043B\u0438 \u0432\u0435\u0442\u0440\u0430 \u0440\u0430\u0443\u043D\u0434\u0430 \u043C\u043E\u0436\u0435\u0442 \u0434\u0430\u0432\u0430\u0442\u044C \u043E\u0447\u043A\u0438; \u043F\u0440\u0438 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0438 \u043E\u0434\u043D\u0430 \u0433\u0440\u0443\u043F\u043F\u0430 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u043E\u0431\u0430 \u0443\u0441\u043B\u043E\u0432\u0438\u044F."),
            rule_section(:table_riichi_start, "Riichi \u2014 \u041D\u0430\u0447\u0430\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447\u0438",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 30 000 \u043E\u0447\u043A\u043E\u0432. \u0412\u044B\u043F\u043B\u0430\u0442\u044B \u0438 \u043F\u0440\u0438\u043D\u044F\u0442\u044B\u0435 \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B \u0440\u0438\u0438\u0447\u0438 \u043C\u0435\u043D\u044F\u044E\u0442 \u044D\u0442\u043E\u0442 \u0431\u0430\u043B\u0430\u043D\u0441.",
              "\u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 14 \u043A\u043E\u0441\u0442\u044F\u043C\u0438 \u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u2014 \u0441 13. \u0412 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434 \u0432\u044B\u0431\u0435\u0440\u0438 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0441\u043F\u0438\u0441\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0431\u0435\u0440\u0451\u0442. \u0415\u0441\u043B\u0438 \u0442\u044B \u0441\u0434\u0430\u044E\u0449\u0438\u0439, \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0443\u0436\u0435 \u0435\u0441\u0442\u044C, \u0435\u0449\u0451 \u043E\u0434\u043D\u043E \u0432\u0437\u044F\u0442\u0438\u0435 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F."),
            rule_section(:table_riichi_play, "Riichi \u2014 \u041F\u0435\u0440\u0432\u044B\u0435 \u0445\u043E\u0434\u044B \u043F\u043E \u0448\u0430\u0433\u0430\u043C",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0435\u0440\u0432\u044B\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437. \u0418\u0449\u0438 \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u0435 \u0447\u0438\u0441\u043B\u0430 \u0434\u043B\u044F \u0447\u043E\u0443, \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u0434\u043B\u044F \u043F\u0430\u043D\u0433\u043E\u0432 \u0438 \u043E\u0434\u043D\u0443 \u0431\u0443\u0434\u0443\u0449\u0443\u044E \u043F\u0430\u0440\u0443. \u0413\u0440\u0443\u043F\u043F\u044B, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0432 \u0440\u0443\u043A\u0435, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0442\u043C\u0435\u0447\u0430\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E: \u0438\u0433\u0440\u0430 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0451\u0442 \u0438\u0445 \u043F\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0438 \u043F\u043E\u0431\u0435\u0434\u044B.",
              "\u0415\u0441\u043B\u0438 \u0442\u044B \u0432 \u0438\u0433\u0440\u043E\u0432\u044B\u0445 \u043F\u043E\u043B\u044F\u0445, \u043D\u043E\u0432\u044B\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442 \u0444\u043E\u043A\u0443\u0441 \u043D\u0430 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0444\u043E\u043A\u0443\u0441 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u043D\u0430 \u043D\u043E\u0432\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0441 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043F\u043E\u043C\u0435\u0442\u043A\u043E\u0439. \u042D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441: \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A \u0434\u0440\u0443\u0433\u0438\u043C \u043A\u043E\u0441\u0442\u044F\u043C, \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0438 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u0443\u044E.",
              "\u0414\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430 \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0445 \u0441\u0431\u0440\u043E\u0441\u043E\u0432 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0423\u0445\u043E\u0434\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u043E\u0442 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440. \u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0431\u044B\u043B\u043E \u0442\u0440\u0438, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0432\u0435 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F.",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0442\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0448\u044C \u043A\u043E\u0441\u0442\u044C \u0438 \u0443\u0432\u0438\u0434\u0438\u0448\u044C \u043E\u0442\u0432\u0435\u0442\u044B. \u041F\u0430\u0441 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u044D\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438, \u0430 \u043D\u0435 \u0432\u044B\u0445\u043E\u0434 \u0438\u043B\u0438 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0448. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u043F\u0430\u0441\u0443\u044E\u0442, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0431\u0435\u0440\u0451\u0442 \u043A\u043E\u0441\u0442\u044C. \u0414\u043E \u0442\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u043D\u043E\u0433\u0434\u0430 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0430\u0441.",
              "\u041F\u0435\u0440\u0432\u043E\u0435 \u043F\u043E\u043B\u0435 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0421\u0440\u0430\u0437\u0443 \u0437\u0430 \u043D\u0438\u043C \u0432\u0441\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F: \u043E\u0442\u0432\u0435\u0442\u044B, \u0432\u0437\u044F\u0442\u0438\u0435, \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u043A\u043E\u043D\u0433\u0438 \u0438\u043B\u0438 \u0440\u0438\u0438\u0447\u0438, \u0435\u0441\u043B\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438\u0445 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442. \u0417\u0430\u0442\u0435\u043C \u0438\u0434\u0443\u0442 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438. Tab \u0438 Shift+Tab \u043C\u0435\u043D\u044F\u044E\u0442 \u043F\u043E\u043B\u0435, \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043F\u0443\u043D\u043A\u0442, Enter \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442. \u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
              "\u041F\u043E\u043B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0445 \u0433\u0440\u0443\u043F\u043F \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0433\u0440\u0443\u043F\u043F\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0441 \u0438\u043C\u0435\u043D\u0430\u043C\u0438 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0435\u0432. \u0421\u0431\u0440\u043E\u0441\u044B \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442, \u043A\u0442\u043E \u043A\u0430\u043A\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u043B. \u0422\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043D\u044F\u0442\u044C, \u0447\u0442\u043E \u0443\u0436\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043E \u0438 \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C. \u0421\u0430\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0445\u043E\u0434 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442.",
              "\u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0440\u0443\u043A\u0443, \u0432\u044B\u0431\u0435\u0440\u0438 \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u0430 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441 \u0438\u043B\u0438 \u043F\u0430\u0441. \u0418\u0433\u0440\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0444\u043E\u0440\u043C\u0443 \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E \u043E\u0447\u043A\u0430\u043C. \u0415\u0441\u043B\u0438 \u0440\u0430\u043D\u044C\u0448\u0435 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0441\u0442\u0435\u043D\u0430, \u0431\u0443\u0434\u0435\u0442 \u043D\u0438\u0447\u044C\u044F; \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0430\u044F \u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044E \u0440\u0443\u043A\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043D\u0435 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442.",
              "S \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u043E\u0447\u043A\u0438 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. M \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F \u0432 \u0441\u0442\u0435\u043D\u0435. \u041E\u043D\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u043E\u0431\u0449\u0430\u044E\u0442: \u043D\u0435 \u0431\u0435\u0440\u0443\u0442, \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442, \u043D\u0435 \u043F\u0430\u0441\u0443\u044E\u0442 \u0438 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u0447\u0443\u0436\u0438\u0435 \u0440\u0443\u043A\u0438.",
              "W \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0438: \u0444\u0430\u043D \u043B\u0438\u0431\u043E \u0445\u0430\u043D \u0438 \u0444\u0443, \u0430 \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u043C\u044B\u0435 \u043E\u0447\u043A\u0438. \u0411\u0435\u0437 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0443\u043A\u0438 \u043D\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u0414\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u0440\u0438\u0438\u0447\u0438 \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u0443\u0440\u0430-\u0434\u043E\u0440\u0430 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0432\u044B\u0448\u0435. U \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0432\u043E\u0438 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438, Shift+U \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445, R \u043D\u043E\u043C\u0435\u0440 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0432\u0435\u0442\u0440\u044B \u0438 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0412 \u0440\u0438\u0438\u0447\u0438 I \u0447\u0438\u0442\u0430\u0435\u0442 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0438 \u043A\u0430\u043C\u043D\u0438 \u0434\u043E\u0440\u0430, \u0447\u0438\u0441\u043B\u043E \u0442\u0432\u043E\u0438\u0445 \u0434\u043E\u0440\u0430, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0440\u0438\u0438\u0447\u0438, \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B, \u0445\u043E\u043D\u0431\u0430 \u0438 \u0442\u0432\u043E\u0439 \u0444\u0443\u0440\u0438\u0442\u0435\u043D. \u042D\u0442\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0442\u0430\u044E\u0442 \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E."),
            rule_section(:table_riichi_build, "Riichi \u2014 \u0427\u0442\u043E \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043F\u0430\u0440\u0430. \u0410\u043B\u044C\u0442\u0435\u0440\u043D\u0430\u0442\u0438\u0432\u044B \u2014 \u0441\u0435\u043C\u044C \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0430\u0440 \u0438 \u0442\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0438\u0440\u043E\u0442. \u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u043D\u0443\u0436\u043D\u043E \u044F\u043A\u0443; \u043E\u0434\u043D\u0438\u0445 \u0434\u043E\u0440\u0430 \u0438 \u0444\u0443 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E. \u041F\u0440\u0438 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u0435 \u0432\u044B\u0431\u0435\u0440\u0438 \u041E\u0431\u044A\u044F\u0432\u0438\u0442\u044C Mahjong \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0414\u0430\u043B\u0435\u0435 \u043F\u0435\u0440\u0435\u0447\u0438\u0441\u043B\u0435\u043D\u044B \u0432\u0441\u0435 \u043F\u0440\u0438\u0441\u0443\u0436\u0434\u0430\u0435\u043C\u044B\u0435 \u044F\u043A\u0443 \u0438 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u044F \u0444\u0443."),
            rule_section(:table_riichi_claims, "Riichi \u2014 \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u043A\u043E\u043D\u0433\u043E\u0432",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0442\u0432\u0435\u0442\u043E\u0432 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u0430, \u0432\u044B\u0431\u0435\u0440\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A. \u0418\u043D\u0430\u0447\u0435 \u0432\u044B\u0431\u0435\u0440\u0438 \u0447\u043E\u0443, \u043F\u043E\u043D\u0433, \u043A\u043E\u043D\u0433 \u0438\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0427\u043E\u0443 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u043B\u0438\u0448\u044C \u0443 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E \u043F\u043E \u0445\u043E\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u043F\u043E\u0434\u043E\u0439\u0434\u0451\u0442 \u0441\u0431\u0440\u043E\u0441 \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "\u041F\u043E\u0431\u0435\u0434\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u043D\u0430 \u0433\u0440\u0443\u043F\u043F\u0443, \u0430 \u043F\u043E\u043D\u0433 \u0438 \u043A\u043E\u043D\u0433 \u0432\u0430\u0436\u043D\u0435\u0435 \u0447\u043E\u0443. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u043C\u043E\u0433\u0443\u0442 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043F\u043E\u0441\u043B\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0435\u0433\u043E. \u0418\u0433\u0440\u0430 \u0436\u0434\u0451\u0442 \u0432\u0441\u0435\u0445 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043E\u0442\u0432\u0435\u0442\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0447\u043E\u0443 \u0438\u043B\u0438 \u043F\u043E\u043D\u0433\u0430 \u0441\u0431\u0440\u043E\u0441\u044C \u043A\u043E\u0441\u0442\u044C \u0431\u0435\u0437 \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0437 \u0441\u0442\u0435\u043D\u044B; \u0433\u0440\u0443\u043F\u043F\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u043A\u043E\u043D\u0433\u0430 \u0432\u043E\u0437\u044C\u043C\u0438 \u0437\u0430\u043C\u0435\u0449\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438 \u043B\u0438\u0448\u044C \u0437\u0430\u0442\u0435\u043C \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u0430 \u0443 \u0442\u0435\u0431\u044F, \u043E\u0431\u044A\u044F\u0432\u0438 \u0438\u0445 \u0447\u0435\u0440\u0435\u0437 \u0441\u043F\u0438\u0441\u043E\u043A \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043A\u043E\u043D\u0433\u043E\u0432. \u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u043A \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C\u0443 \u043F\u043E\u043D\u0433\u0443. \u041F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0442\u0430\u043A\u043E\u0439 \u043A\u043E\u043D\u0433 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u043C\u043E\u0439 \u043A\u043E\u0441\u0442\u0438.",
              "\u041E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 \u043C\u043E\u0436\u0435\u0442 \u0443\u0431\u0440\u0430\u0442\u044C \u043D\u0430\u043C\u0435\u0447\u0435\u043D\u043D\u043E\u0435 \u044F\u043A\u0443. \u0420\u0438\u0438\u0447\u0438 \u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0435 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u044E\u0442 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0441\u0442\u0438, \u043F\u0430\u043D\u0433 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432 \u0434\u0430\u0451\u0442 \u043E\u0447\u043A\u0438 \u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C. \u041F\u0435\u0440\u0435\u0434 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435\u043C \u043F\u043E\u0434\u0443\u043C\u0430\u0439, \u043A\u0430\u043A\u043E\u0435 \u044F\u043A\u0443 \u043E\u0441\u0442\u0430\u043D\u0435\u0442\u0441\u044F."),
            rule_section(:table_riichi, "\u0420\u0438\u0438\u0447\u0438 \u2014 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u0438, \u0434\u043E\u0440\u0430 \u0438 \u0444\u0443\u0440\u0438\u0442\u0435\u043D",
              "\u0415\u0441\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B, \u0441\u043F\u0438\u0441\u043E\u043A \u00AB\u0420\u0438\u0438\u0447\u0438\u00BB \u043F\u0440\u0435\u0434\u043B\u043E\u0436\u0438\u0442 \u0441\u0431\u0440\u043E\u0441\u044B \u0434\u043B\u044F \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u0438. \u0412\u044B\u0431\u0435\u0440\u0438 \u043A\u043E\u0441\u0442\u044C \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041F\u0440\u0438\u043D\u044F\u0442\u043E\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0432\u043D\u043E\u0441\u0438\u0442 \u043D\u0430 \u0441\u0442\u043E\u043B 1 000 \u043E\u0447\u043A\u043E\u0432. \u0417\u0430\u0442\u0435\u043C \u043D\u0443\u0436\u043D\u043E \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0442\u044C \u0432\u0437\u044F\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C, \u0435\u0441\u043B\u0438 \u043E\u043D\u0430 \u043D\u0435 \u0434\u0430\u0451\u0442 \u043F\u043E\u0431\u0435\u0434\u0443; \u043A\u043E\u043D\u0433 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C \u043B\u0438\u0448\u044C \u043F\u0440\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u0438\u0438 \u0432\u0441\u0435\u0445 \u0442\u0440\u0435\u0431\u0443\u0435\u043C\u044B\u0445 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u043E\u0432 \u0440\u0430\u0437\u0431\u043E\u0440\u0430 \u0440\u0443\u043A\u0438. \u041F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B, \u0430 \u043D\u0435\u0432\u043E\u0441\u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u043D\u044B\u0435 \u043F\u0435\u0440\u0435\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0440\u0430\u0437\u0434\u0430\u0447\u0443.",
              "\u0424\u0443\u0440\u0438\u0442\u0435\u043D \u0437\u0430\u043F\u0440\u0435\u0449\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435, \u0435\u0441\u043B\u0438 \u043E\u0434\u043D\u0430 \u0438\u0437 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0449\u0438\u0445 \u0440\u0443\u043A\u0443 \u043A\u043E\u0441\u0442\u0435\u0439 \u0435\u0441\u0442\u044C \u0441\u0440\u0435\u0434\u0438 \u0442\u0432\u043E\u0438\u0445 \u0441\u0431\u0440\u043E\u0441\u043E\u0432. \u041E\u0442\u043A\u0430\u0437 \u043E\u0442 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u043D\u0430 \u0447\u0443\u0436\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u0442\u0430\u043A\u0436\u0435 \u0432\u0440\u0435\u043C\u0435\u043D\u043D\u043E \u0437\u0430\u043F\u0440\u0435\u0449\u0430\u0435\u0442 \u0442\u0430\u043A\u0438\u0435 \u043F\u043E\u0431\u0435\u0434\u044B; \u043F\u043E\u0441\u043B\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0440\u0438\u0438\u0447\u0438 \u0437\u0430\u043F\u0440\u0435\u0442 \u0434\u0435\u0439\u0441\u0442\u0432\u0443\u0435\u0442 \u0434\u043E \u043A\u043E\u043D\u0446\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0438. \u041F\u043E\u0431\u0435\u0434\u0430 \u0441\u043E \u0441\u0442\u0435\u043D\u044B \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u0430. \u0412 \u0441\u0430\u043D\u043C\u0430 \u0443\u0431\u0440\u0430\u043D\u044B \u0441\u0438\u043C\u0432\u043E\u043B\u044B \u043E\u0442 2 \u0434\u043E 8; \u0421\u0435\u0432\u0435\u0440 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u044C\u044E \u0431\u0435\u0437 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0438\u0437\u0432\u043B\u0435\u0447\u0435\u043D\u0438\u044F.",
              "\u041F\u0440\u0438\u043C\u0435\u0440 \u0444\u0443\u0440\u0438\u0442\u0435\u043D\u0430: \u0436\u0434\u0451\u0448\u044C \u0431\u0430\u043C\u0431\u0443\u043A 3 \u0438\u043B\u0438 6, \u043D\u043E \u0440\u0430\u043D\u044C\u0448\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u043B 3. \u041F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0447\u0443\u0436\u043E\u043C \u0441\u0431\u0440\u043E\u0441\u0435 \u0437\u0430\u043F\u0440\u0435\u0449\u0435\u043D\u0430 \u0438 \u043D\u0430 6, \u043D\u0435 \u0442\u043E\u043B\u044C\u043A\u043E \u043D\u0430 \u0441\u0432\u043E\u044E \u043F\u0440\u0435\u0436\u043D\u044E\u044E 3. \u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 3 \u0438\u043B\u0438 6 \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0436\u0435\u0442 \u0434\u0430\u0442\u044C \u043F\u043E\u0431\u0435\u0434\u0443."),
            rule_section(:table_yaku, "\u0420\u0438\u0438\u0447\u0438 \u2014 \u043F\u043E\u043B\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u044F\u043A\u0443 \u0438 \u0445\u0430\u043D",
              "\u0412 \u0440\u0438\u0438\u0447\u0438 \u043D\u0443\u0436\u043D\u0430 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430\u044F \u0440\u0443\u043A\u0430 \u0438 \u0445\u043E\u0442\u044F \u0431\u044B \u043E\u0434\u043D\u043E \u044F\u043A\u0443. \u041D\u0438\u0436\u0435 \u0432\u0441\u0435 \u043E\u0431\u044B\u0447\u043D\u044B\u0435 \u044F\u043A\u0443, \u043F\u0440\u0438\u0441\u0443\u0436\u0434\u0430\u0435\u043C\u044B\u0435 \u0432 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438, \u0441\u043E \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C\u044E \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0438. \u0421\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0443\u043A\u0443. \u041F\u0443\u043D\u0433, \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u044B\u043C \u0447\u0443\u0436\u0438\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C, \u043F\u0440\u0438 \u043F\u043E\u0434\u0441\u0447\u0451\u0442\u0435 \u043D\u0435 \u044F\u0432\u043B\u044F\u0435\u0442\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C.",
              "- \u0420\u0438\u0438\u0447\u0438: \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0433\u043E\u0442\u043E\u0432\u0430\u044F \u0440\u0443\u043A\u0430 \u0438 \u043F\u0440\u0438\u043D\u044F\u0442\u043E\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0441 \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u043E\u043C 1000 \u043E\u0447\u043A\u043E\u0432. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0414\u0432\u043E\u0439\u043D\u043E\u0435 \u0440\u0438\u0438\u0447\u0438: \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0432 \u043F\u0435\u0440\u0432\u043E\u043C \u043D\u0435\u043F\u0440\u0435\u0440\u0432\u0430\u043D\u043D\u043E\u043C \u043A\u0440\u0443\u0433\u0435; \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u043E\u0431\u044B\u0447\u043D\u043E\u0435 \u0440\u0438\u0438\u0447\u0438. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0418\u043F\u043F\u0430\u0446\u0443: \u043F\u043E\u0431\u0435\u0434\u0430 \u0432 \u043F\u0435\u0440\u0432\u043E\u043C \u043D\u0435\u043F\u0440\u0435\u0440\u0432\u0430\u043D\u043D\u043E\u043C \u043A\u0440\u0443\u0433\u0435 \u043F\u043E\u0441\u043B\u0435 \u0440\u0438\u0438\u0447\u0438. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u041C\u044D\u043D\u0434\u0437\u044D\u043D \u0446\u0443\u043C\u043E: \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u0441 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u043E\u0439. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0422\u0430\u043D\u044A\u044F\u043E: \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0441\u043B\u0430 2\u20138, \u0431\u0435\u0437 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u042F\u043A\u0443\u0445\u0430\u0439: \u0437\u0430 \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u0443\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432 \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u041F\u0443\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433 \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u041F\u0443\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433 \u0432\u0435\u0442\u0440\u0430 \u0440\u0430\u0443\u043D\u0434\u0430; \u043F\u0440\u0438 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0438 \u0441\u043E \u0441\u0432\u043E\u0438\u043C \u0432\u0435\u0442\u0440\u043E\u043C \u0432\u043C\u0435\u0441\u0442\u0435 2 \u0445\u0430\u043D. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0425\u0430\u0439\u0442\u044D\u0439: \u043F\u043E\u0431\u0435\u0434\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u043C \u043E\u0431\u044B\u0447\u043D\u044B\u043C \u0432\u0437\u044F\u0442\u0438\u0435\u043C \u0438\u0437 \u0441\u0442\u0435\u043D\u044B. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0425\u043E\u0442\u044D\u0439: \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u043C \u0441\u0431\u0440\u043E\u0441\u0435. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0420\u0438\u043D\u0441\u044F\u043D: \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0437\u0430\u043C\u0435\u0449\u0430\u044E\u0449\u0435\u0439 \u043A\u043E\u0441\u0442\u0438 \u043F\u043E\u0441\u043B\u0435 \u043A\u043E\u043D\u0433\u0430. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0422\u044F\u043D\u043A\u0430\u043D: \u043E\u0433\u0440\u0430\u0431\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0433\u0430. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u041F\u0438\u043D\u0444\u0443: \u0447\u0435\u0442\u044B\u0440\u0435 \u0447\u043E\u0443, \u043D\u0435\u0437\u043D\u0430\u0447\u0438\u043C\u0430\u044F \u043F\u0430\u0440\u0430 \u0438 \u0434\u0432\u0443\u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0435\u0435 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0435. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0418\u0438\u043F\u044D\u0439\u043A\u043E: \u0434\u0432\u0430 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0447\u043E\u0443 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0420\u044F\u043D\u043F\u044D\u0439\u043A\u043E: \u0434\u0432\u0435 \u043F\u0430\u0440\u044B \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u0447\u043E\u0443; \u0437\u0430\u043C\u0435\u043D\u044F\u0435\u0442 \u0438\u0438\u043F\u044D\u0439\u043A\u043E. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 3 han.",
              "- \u0422\u0438\u0438\u0442\u043E\u0439\u0446\u0443: \u0441\u0435\u043C\u044C \u0440\u0430\u0437\u043D\u044B\u0445 \u043F\u0430\u0440; \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0434\u0432\u0435 \u043F\u0430\u0440\u044B. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0422\u043E\u0439\u0442\u043E\u0439: \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u0438 \u043F\u0430\u0440\u0430. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0421\u0430\u043D\u0430\u043D\u043A\u043E: \u0442\u0440\u0438 \u0441\u043A\u0440\u044B\u0442\u044B\u0445 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430; \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0430\u044F \u0433\u0440\u0443\u043F\u043F\u0430 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0421\u0430\u043D\u043A\u0430\u043D\u0446\u0443: \u0442\u0440\u0438 \u043A\u043E\u043D\u0433\u0430. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0421\u0451\u0441\u0430\u0433\u044D\u043D: \u0434\u0432\u0430 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432 \u0438 \u043F\u0430\u0440\u0430 \u0442\u0440\u0435\u0442\u044C\u0435\u0433\u043E; \u044F\u043A\u0443\u0445\u0430\u0439 \u0437\u0430 \u043E\u0431\u0430 \u043F\u0443\u043D\u0433\u0430 \u0442\u043E\u0436\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0421\u0430\u043D\u0441\u0451\u043A\u0443 \u0434\u043E\u0434\u0437\u044E\u043D: \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u043E\u0435 \u0447\u043E\u0443 \u0432\u043E \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u043C\u0430\u0441\u0442\u044F\u0445. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0421\u0430\u043D\u0441\u0451\u043A\u0443 \u0434\u043E\u043A\u043E: \u043F\u0443\u043D\u0433\u0438 \u043E\u0434\u043D\u043E\u0433\u043E \u0447\u0438\u0441\u043B\u0430 \u0432\u043E \u0432\u0441\u0435\u0445 \u0442\u0440\u0451\u0445 \u043C\u0430\u0441\u0442\u044F\u0445. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0418\u0446\u0446\u0443: \u0447\u043E\u0443 123, 456 \u0438 789 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0422\u044F\u043D\u0442\u0430: \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u0435 \u0438 \u043F\u0430\u0440\u0435 \u0435\u0441\u0442\u044C \u043A\u0440\u0430\u0439\u043D\u044F\u044F \u0438\u043B\u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C; \u043F\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u0447\u043E\u0443 \u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 1 han.",
              "- \u0414\u0437\u044E\u043D\u0442\u044F\u043D: \u0432 \u043A\u0430\u0436\u0434\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u0435 \u0438 \u043F\u0430\u0440\u0435 \u0435\u0441\u0442\u044C 1 \u0438\u043B\u0438 9; \u043F\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0442 \u0447\u043E\u0443, \u043D\u0435\u0442 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 3 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0425\u043E\u043D\u0440\u043E\u0442\u043E: \u0442\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u0439\u043D\u0438\u0435 \u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 2 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0425\u043E\u043D\u0438\u0446\u0443: \u043E\u0434\u043D\u0430 \u0447\u0438\u0441\u043B\u043E\u0432\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 3 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 2 han.",
              "- \u0422\u0438\u043D\u0438\u0446\u0443: \u043E\u0434\u043D\u0430 \u0447\u0438\u0441\u043B\u043E\u0432\u0430\u044F \u043C\u0430\u0441\u0442\u044C \u0431\u0435\u0437 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445. \u0417\u0430\u043A\u0440\u044B\u0442\u0430\u044F: 6 han; \u043E\u0442\u043A\u0440\u044B\u0442\u0430\u044F: 5 han."),
            rule_section(:table_riichi_dora, "\u0420\u0438\u0438\u0447\u0438 \u2014 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0445\u0430\u043D \u0437\u0430 \u0434\u043E\u0440\u0430",
              "\u0414\u043E\u0440\u0430 \u0434\u0430\u044E\u0442 1 \u0445\u0430\u043D \u0437\u0430 \u043A\u0430\u0436\u0434\u0443\u044E \u0441\u0432\u043E\u044E \u043A\u043E\u0441\u0442\u044C \u0434\u043E\u0440\u0430, \u043D\u043E \u0442\u043E\u043B\u044C\u043A\u043E \u043F\u0440\u0438 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u043C \u044F\u043A\u0443. \u0421\u0430\u043C\u0438 \u0434\u043E\u0440\u0430 \u043D\u0435 \u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u044F\u043A\u0443. \u0418\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0432 \u0446\u0438\u043A\u043B\u0435; \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043A\u0430\u0436\u0434\u0430\u044F \u043A\u043E\u043F\u0438\u044F \u0432 \u0440\u0443\u043A\u0435 \u0438 \u0441\u0432\u043E\u0438\u0445 \u0433\u0440\u0443\u043F\u043F\u0430\u0445. \u041F\u043E\u0441\u043B\u0435 \u043F\u0440\u0438\u043D\u044F\u0442\u043E\u0433\u043E \u0440\u0438\u0438\u0447\u0438 \u043F\u0440\u0438 \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u0435 \u043C\u043E\u0433\u0443\u0442 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u0443\u0440\u0430-\u0434\u043E\u0440\u0430; \u043F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0438\u0445 \u043D\u0435 \u0440\u0430\u0441\u043A\u0440\u044B\u0432\u0430\u0435\u0442."),
            rule_section(:table_riichi_yakuman, "\u0420\u0438\u0438\u0447\u0438 \u2014 \u043F\u043E\u043B\u043D\u044B\u0439 \u043F\u0435\u0440\u0435\u0447\u0435\u043D\u044C \u044F\u043A\u0443\u043C\u0430\u043D\u043E\u0432",
              "\u041A\u0430\u0436\u0434\u044B\u0439 \u043F\u0443\u043D\u043A\u0442 \u043D\u0438\u0436\u0435 \u0434\u0430\u0451\u0442 1 \u044F\u043A\u0443\u043C\u0430\u043D \u0432\u043C\u0435\u0441\u0442\u043E \u043E\u0431\u044B\u0447\u043D\u044B\u0445 \u0445\u0430\u043D \u0438 \u0444\u0443. \u0420\u0430\u0437\u043D\u044B\u0435 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0435 \u044F\u043A\u0443\u043C\u0430\u043D\u044B \u043C\u043E\u0433\u0443\u0442 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0442\u044C\u0441\u044F. \u0412 \u044D\u0442\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u044F\u043A\u0443\u043C\u0430\u043D \u043D\u0435 \u0443\u0434\u0432\u0430\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0437\u0430 \u043E\u0441\u043E\u0431\u043E\u0435 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u0438\u043B\u0438 \u0437\u0430 \u0431\u043E\u043B\u044C\u0448\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0432\u0435\u0442\u0440\u0430.",
              "- 1 yakuman \u2014 \u0422\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0438\u0440\u043E\u0442: \u0432\u0441\u0435 \u043A\u0440\u0430\u0439\u043D\u0438\u0435 \u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435, \u043E\u0434\u043D\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F; \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- 1 yakuman \u2014 \u0427\u0435\u0442\u044B\u0440\u0435 \u0441\u043A\u0440\u044B\u0442\u044B\u0445 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430: \u043F\u0440\u0438 \u043F\u043E\u0431\u0435\u0434\u0435 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043E\u043D \u0434\u043E\u043B\u0436\u0435\u043D \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0442\u044C \u043F\u0430\u0440\u0443.",
              "- 1 yakuman \u2014 \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u0442\u0440\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u0430: \u043F\u0443\u043D\u0433\u0438 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0438 \u0442\u0440\u0451\u0445 \u0432\u0438\u0434\u043E\u0432 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432.",
              "- 1 yakuman \u2014 \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0432\u0435\u0442\u0440\u0430: \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u0432\u0435\u0442\u0440\u043E\u0432.",
              "- 1 yakuman \u2014 \u041C\u0430\u043B\u044B\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0432\u0435\u0442\u0440\u0430: \u0442\u0440\u0438 \u043F\u0443\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u0432\u0435\u0442\u0440\u043E\u0432 \u0438 \u043F\u0430\u0440\u0430 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u0433\u043E.",
              "- 1 yakuman \u2014 \u0422\u043E\u043B\u044C\u043A\u043E \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435: \u043B\u0438\u0448\u044C \u0432\u0435\u0442\u0440\u044B \u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u044B.",
              "- 1 yakuman \u2014 \u0422\u043E\u043B\u044C\u043A\u043E \u043A\u0440\u0430\u0439\u043D\u0438\u0435: \u043B\u0438\u0448\u044C \u0435\u0434\u0438\u043D\u0438\u0446\u044B \u0438 \u0434\u0435\u0432\u044F\u0442\u043A\u0438.",
              "- 1 yakuman \u2014 \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0435\u043B\u0451\u043D\u044B\u0435: \u0431\u0430\u043C\u0431\u0443\u043A 2, 3, 4, 6, 8 \u0438 \u0437\u0435\u043B\u0451\u043D\u044B\u0435 \u0434\u0440\u0430\u043A\u043E\u043D\u044B.",
              "- 1 yakuman \u2014 \u0427\u0435\u0442\u044B\u0440\u0435 \u043A\u043E\u043D\u0433\u0430 \u0438 \u043F\u0430\u0440\u0430.",
              "- 1 yakuman \u2014 \u0414\u0435\u0432\u044F\u0442\u044C \u0432\u0440\u0430\u0442: \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, 1112345678999 \u0438 \u0435\u0449\u0451 \u043E\u0434\u043D\u0430 \u043A\u043E\u0441\u0442\u044C \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438.",
              "\u041D\u0435\u0431\u0435\u0441\u043D\u0430\u044F \u0438 \u0437\u0435\u043C\u043D\u0430\u044F \u0440\u0443\u043A\u0438 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432 \u0438\u0433\u0440\u0435 \u043D\u0435 \u043F\u0440\u0435\u043C\u0438\u0440\u0443\u044E\u0442\u0441\u044F. \u041D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0439 \u0437\u0430 \u043D\u0438\u0445 \u0431\u043E\u043D\u0443\u0441 \u0437\u0430 \u043F\u043E\u0431\u0435\u0434\u0443 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438."),
            rule_section(:table_fu, "\u0420\u0438\u0438\u0447\u0438: \u0444\u0443 \u0437\u0430 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u044F",
              "\u0425\u0430\u043D \u043E\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u044E\u0442 \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u044F\u043A\u0443 \u0438 \u0431\u043E\u043D\u0443\u0441\u043E\u0432, \u0444\u0443 \u2014 \u043E\u0441\u043E\u0431\u0435\u043D\u043D\u043E\u0441\u0442\u0438 \u0441\u0442\u0440\u043E\u0435\u043D\u0438\u044F \u0440\u0443\u043A\u0438. \u0427\u043E\u0443 \u0434\u0430\u0451\u0442 0 \u0444\u0443. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u043F\u0430\u0440\u0430 \u0442\u043E\u0436\u0435 \u0434\u0430\u0451\u0442 0; \u043F\u0430\u0440\u0430 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432, \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430 \u0438\u043B\u0438 \u0432\u0435\u0442\u0440\u0430 \u0440\u0430\u0443\u043D\u0434\u0430 \u2014 2. \u0412 \u044D\u0442\u043E\u0439 \u0438\u0433\u0440\u0435 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0435 \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430 \u0441 \u0432\u0435\u0442\u0440\u043E\u043C \u0440\u0430\u0443\u043D\u0434\u0430 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u0434\u0430\u0451\u0442 \u043F\u0430\u0440\u0435 \u0442\u043E\u043B\u044C\u043A\u043E 2 \u0444\u0443.",
              "\u0426\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u043F\u0430\u043D\u0433\u043E\u0432 \u0438 \u043A\u043E\u043D\u0433\u043E\u0432 \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043E\u0442 \u0432\u0438\u0434\u0430 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0441\u0442\u0438:",
              "- \u041F\u0430\u043D\u0433 \u043F\u0440\u043E\u0441\u0442\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439, \u0447\u0438\u0441\u0435\u043B 2\u20138: \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 2 \u0444\u0443, \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 4 \u0444\u0443.",
              "- \u041F\u0430\u043D\u0433 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u043E\u0432 \u0438\u043B\u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439: \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 4 \u0444\u0443, \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 8 \u0444\u0443.",
              "- \u041A\u043E\u043D\u0433 \u043F\u0440\u043E\u0441\u0442\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439: \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 8 \u0444\u0443, \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 16 \u0444\u0443.",
              "- \u041A\u043E\u043D\u0433 \u0442\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u043E\u0432 \u0438\u043B\u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439: \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 16 \u0444\u0443, \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 32 \u0444\u0443.",
              "\u041F\u0430\u043D\u0433, \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u044B\u043C \u0447\u0443\u0436\u0438\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C, \u0434\u043B\u044F \u0444\u0443 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u043F\u0430\u043D\u0433\u0438 \u0432 \u0440\u0443\u043A\u0435 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u043A \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C\u0443 \u043F\u0430\u043D\u0433\u0443 \u043E\u0431\u0440\u0430\u0437\u0443\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433.",
              "\u041E\u0431\u044B\u0447\u043D\u044B\u0439 \u0440\u0430\u0441\u0447\u0451\u0442 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442\u0441\u044F \u0441 20 \u0444\u0443. \u041F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u0441 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u043E\u0439 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 10, \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u2014 2. \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u043F\u0430\u0440\u044B, \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u044B \u0438\u043B\u0438 \u043A\u0440\u0430\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 2. \u041A\u0440\u0430\u0439 \u2014 \u044D\u0442\u043E 3 \u043A 1\u20132 \u0438\u043B\u0438 7 \u043A 8\u20139, \u0441\u0435\u0440\u0435\u0434\u0438\u043D\u0430 \u2014 \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 5 \u043A 4\u20136. \u0414\u0432\u0443\u0441\u0442\u043E\u0440\u043E\u043D\u043D\u0435\u0435 \u043E\u0436\u0438\u0434\u0430\u043D\u0438\u0435, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 3 \u0438\u043B\u0438 6 \u043A 4\u20135, \u0444\u0443 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442.",
              "\u0421\u0443\u043C\u043C\u0443 \u043E\u043A\u0440\u0443\u0433\u043B\u044F\u044E\u0442 \u0432\u0432\u0435\u0440\u0445 \u0434\u043E \u0434\u0435\u0441\u044F\u0442\u043A\u043E\u0432: 32 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F 40 \u0444\u0443. \u0421\u0435\u043C\u044C \u043F\u0430\u0440 \u0432\u0441\u0435\u0433\u0434\u0430 \u0434\u0430\u0451\u0442 25 \u0444\u0443. \u041F\u0438\u043D\u0444\u0443 \u0441 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u043C \u0432\u0437\u044F\u0442\u0438\u0435\u043C \u0434\u0430\u0451\u0442 20 \u0444\u0443 \u0431\u0435\u0437 \u0434\u043E\u0431\u0430\u0432\u043E\u0447\u043D\u044B\u0445 2 \u0437\u0430 \u0432\u0437\u044F\u0442\u0438\u0435. \u041B\u044E\u0431\u0430\u044F \u0434\u0440\u0443\u0433\u0430\u044F \u0440\u0443\u043A\u0430, \u0443 \u043A\u043E\u0442\u043E\u0440\u043E\u0439 \u0431\u044B\u043B\u043E \u0431\u044B \u0442\u043E\u043B\u044C\u043A\u043E 20, \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043C\u0438\u043D\u0438\u043C\u0443\u043C 30 \u0444\u0443.",
              "\u041D\u0430\u043F\u0440\u0438\u043C\u0435\u0440, 20 \u043E\u0441\u043D\u043E\u0432\u044B, 10 \u0437\u0430 \u0437\u0430\u043A\u0440\u044B\u0442\u0443\u044E \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435, 4 \u0437\u0430 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u043F\u0430\u043D\u0433 \u043F\u044F\u0442\u0451\u0440\u043E\u043A \u0438 2 \u0437\u0430 \u043F\u0430\u0440\u0443 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432 \u0434\u0430\u044E\u0442 36, \u0442\u043E \u0435\u0441\u0442\u044C 40 \u0444\u0443. \u042F\u043A\u0443 \u0432\u0441\u0451 \u0440\u0430\u0432\u043D\u043E \u043D\u0435\u043E\u0431\u0445\u043E\u0434\u0438\u043C\u043E: \u043E\u0434\u043D\u0438\u0445 \u0444\u0443 \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E."),
            rule_section(:table_riichi_payments, "\u0420\u0438\u0438\u0447\u0438: \u043F\u0435\u0440\u0435\u0432\u043E\u0434 \u0445\u0430\u043D \u0438 \u0444\u0443 \u0432 \u043E\u0447\u043A\u0438",
              "\u0414\u043B\u044F \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u043E\u0441\u043D\u043E\u0432\u0430 \u0440\u0430\u0432\u043D\u0430 \u0444\u0443, \u0443\u043C\u043D\u043E\u0436\u0435\u043D\u043D\u044B\u043C \u043D\u0430 2 \u0432 \u0441\u0442\u0435\u043F\u0435\u043D\u0438 \u0445\u0430\u043D \u043F\u043B\u044E\u0441 2, \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C 2000. \u041F\u0440\u0438 1 \u0445\u0430\u043D \u0438 30 \u0444\u0443 \u044D\u0442\u043E 30 \u043D\u0430 8, \u0442\u043E \u0435\u0441\u0442\u044C 240. \u041A\u0430\u0436\u0434\u0443\u044E \u0438\u0442\u043E\u0433\u043E\u0432\u0443\u044E \u0432\u044B\u043F\u043B\u0430\u0442\u0443 \u043E\u043A\u0440\u0443\u0433\u043B\u044F\u044E\u0442 \u0432\u0432\u0435\u0440\u0445 \u0434\u043E \u0441\u043E\u0442\u0435\u043D.",
              "\u041F\u0440\u0438 \u043F\u043E\u0431\u0435\u0434\u0435 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043D\u0435 \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043E\u0442 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0435\u0433\u043E \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0441\u043D\u043E\u0432\u044B, \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u2014 \u0448\u0435\u0441\u0442\u044C. \u041F\u0440\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u043C \u0432\u0437\u044F\u0442\u0438\u0438 \u043D\u0435 \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u0434\u0432\u0435 \u043E\u0441\u043D\u043E\u0432\u044B \u043E\u0442 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u043F\u043E \u043E\u0434\u043D\u043E\u0439 \u043E\u0442 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0415\u0441\u043B\u0438 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u0441\u0434\u0430\u044E\u0449\u0438\u0439, \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043B\u0430\u0442\u0438\u0442 \u0434\u0432\u0435 \u043E\u0441\u043D\u043E\u0432\u044B.",
              "\u041F\u0440\u0438 1 \u0445\u0430\u043D 30 \u0444\u0443 \u0431\u0435\u0437 \u0431\u043E\u043D\u0443\u0441\u043E\u0432 \u043D\u0435 \u0441\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 1000 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u0438\u043B\u0438 500 \u043E\u0442 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u043F\u043E 300 \u043E\u0442 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F, \u0432\u0441\u0435\u0433\u043E 1100. \u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 1500 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u0438\u043B\u0438 \u043F\u043E 500 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E, \u0442\u043E\u0436\u0435 1500.",
              "- \u041C\u0430\u043D\u0433\u0430\u043D: 5 \u0445\u0430\u043D \u0438\u043B\u0438 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u0435 \u043F\u0440\u0435\u0434\u0435\u043B\u0430 \u043E\u0441\u043D\u043E\u0432\u044B; \u0437\u0434\u0435\u0441\u044C \u0442\u0430\u043A\u0436\u0435 3 \u0445\u0430\u043D 60 \u0444\u0443 \u0438 4 \u0445\u0430\u043D 30 \u0444\u0443. \u041D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u044D\u0442\u043E 8000 \u0434\u043B\u044F \u043D\u0435 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438\u043B\u0438 12 000 \u0434\u043B\u044F \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E.",
              "- \u0425\u0430\u043D\u044D\u043C\u0430\u043D: 6\u20137 \u0445\u0430\u043D, \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0435\u043D\u043D\u043E 12 000 \u0438\u043B\u0438 18 000 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435.",
              "- \u0411\u0430\u0439\u043C\u0430\u043D: 8\u201310 \u0445\u0430\u043D, 16 000 \u0438\u043B\u0438 24 000.",
              "- \u0421\u0430\u043D\u0431\u0430\u0439\u043C\u0430\u043D: 11\u201312 \u0445\u0430\u043D, 24 000 \u0438\u043B\u0438 36 000.",
              "- \u042F\u043A\u0443\u043C\u0430\u043D \u0438\u043B\u0438 \u043C\u0438\u043D\u0438\u043C\u0443\u043C 13 \u0445\u0430\u043D: 32 000 \u0438\u043B\u0438 48 000. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0445 \u044F\u043A\u0443\u043C\u0430\u043D\u043E\u0432 \u0443\u043C\u043D\u043E\u0436\u0430\u044E\u0442 \u0432\u044B\u043F\u043B\u0430\u0442\u0443.",
              "\u041A\u0430\u0436\u0434\u0430\u044F \u0445\u043E\u043D\u0431\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 300 \u043A \u0432\u044B\u043F\u043B\u0430\u0442\u0435 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043B\u0438\u0431\u043E \u043F\u043E 100 \u043E\u0442 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430 \u043F\u0440\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u043C \u0432\u0437\u044F\u0442\u0438\u0438. \u0414\u0435\u043F\u043E\u0437\u0438\u0442\u044B \u0440\u0438\u0438\u0447\u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u0442 \u043F\u043E\u0431\u0435\u0434\u0438\u0442\u0435\u043B\u044C \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E. \u0425\u043E\u043D\u0431\u0430 \u0440\u0430\u0441\u0442\u0451\u0442 \u043F\u043E\u0441\u043B\u0435 \u043D\u0438\u0447\u044C\u0435\u0439 \u0438\u043B\u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0430 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0438 \u043E\u0431\u043D\u0443\u043B\u044F\u0435\u0442\u0441\u044F \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0431\u0435\u0434\u044B \u0434\u0440\u0443\u0433\u043E\u0433\u043E \u0438\u0433\u0440\u043E\u043A\u0430."),
            rule_section(:table_riichi_match, "Riichi \u2014 \u0420\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u0434\u043B\u0438\u043D\u0430 \u043C\u0430\u0442\u0447\u0430",
              "\u041F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u0433\u0440\u0430\u044E\u0442 \u0447\u0435\u0442\u0432\u0435\u0440\u043E \u0441 30 000 \u043E\u0447\u043A\u043E\u0432, \u0440\u0430\u0443\u043D\u0434\u044B \u0412\u043E\u0441\u0442\u043E\u043A \u0438 \u042E\u0433. \u0412\u0441\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u043F\u0435\u0440\u0438\u043E\u0434 \u0441\u0434\u0430\u0447\u0438 \u0432 \u043E\u0431\u043E\u0438\u0445: \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0432\u043E\u0441\u0435\u043C\u044C \u0440\u0430\u0437\u0434\u0430\u0447, \u0441 \u043F\u043E\u0432\u0442\u043E\u0440\u0430\u043C\u0438 \u0431\u043E\u043B\u044C\u0448\u0435. \u0412\u044B\u043F\u043B\u0430\u0442\u044B \u0438 \u043F\u0440\u0438\u043D\u044F\u0442\u044B\u0435 \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B \u0440\u0438\u0438\u0447\u0438 \u043C\u0435\u043D\u044F\u044E\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441.",
              "\u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0441\u0432\u043E\u0435\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043F\u043E \u0441\u0442\u0435\u043D\u0435, \u0435\u0441\u043B\u0438 \u0443 \u043D\u0435\u0433\u043E \u0442\u0435\u043C\u043F\u0430\u0439.",
              "\u041F\u0440\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043F\u043E \u0441\u0442\u0435\u043D\u0435 3000 \u043E\u0447\u043A\u043E\u0432 \u043F\u0435\u0440\u0435\u0445\u043E\u0434\u044F\u0442 \u043E\u0442 \u043D\u043E\u0442\u0435\u043D\u0430 \u043A \u0442\u0435\u043C\u043F\u0430\u044E, \u0435\u0441\u043B\u0438 \u043D\u0435 \u0433\u043E\u0442\u043E\u0432\u044B \u0432\u0441\u0435 \u0438\u043B\u0438 \u043D\u0438\u043A\u0442\u043E. \u0417\u0430\u0442\u0435\u043C \u043A\u0430\u0436\u0434\u044B\u0439 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0443\u044E \u0440\u0430\u0437\u0434\u0430\u0447\u0443. \u041C\u0430\u0442\u0447 \u0434\u043B\u0438\u0442\u0441\u044F \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0440\u0430\u0443\u043D\u0434\u044B; \u043E\u0442\u0440\u0438\u0446\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0439 \u0441\u0447\u0451\u0442 \u0438\u043B\u0438 \u043B\u0438\u0434\u0435\u0440\u0441\u0442\u0432\u043E \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E \u0437\u0434\u0435\u0441\u044C \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0442 \u0435\u0433\u043E \u0440\u0430\u043D\u044C\u0448\u0435. \u041F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0438\u0442\u043E\u0433, \u0440\u0430\u0432\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C\u044B \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E."),
            rule_section(:table_riichi_variants, "\u0420\u0438\u0438\u0447\u0438 \u2014 \u0438\u0433\u0440\u0430 \u0432\u0442\u0440\u043E\u0451\u043C \u0438 \u0434\u043B\u0438\u043D\u0430 \u043C\u0430\u0442\u0447\u0430",
              "\u0414\u043B\u0438\u043D\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u0430. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u043C\u0435\u043D\u044F\u044E\u0442 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447, \u0430 \u043D\u0435 \u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u043E\u0439 \u0440\u0443\u043A\u0438.",
              "\u041E\u0434\u043D\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u0437\u0430\u043A\u0430\u043D\u0447\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u043E\u0439 \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043F\u043E \u0441\u0442\u0435\u043D\u0435. \u0412\u043E\u0441\u0442\u043E\u0447\u043D\u044B\u0439 \u0440\u0430\u0443\u043D\u0434 \u0434\u0430\u0451\u0442 \u043A\u0430\u0436\u0434\u043E\u043C\u0443 \u043F\u0435\u0440\u0438\u043E\u0434 \u0441\u0434\u0430\u0447\u0438: \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C \u0438\u043B\u0438 \u0442\u0440\u0438 \u0432 \u0441\u0430\u043D\u043C\u0435. \u0412\u043E\u0441\u0442\u043E\u043A \u0438 \u042E\u0433 \u2014 \u0434\u0432\u0430 \u0440\u0430\u0443\u043D\u0434\u0430: \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u0432\u043E\u0441\u0435\u043C\u044C \u0438\u043B\u0438 \u0448\u0435\u0441\u0442\u044C. \u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0431\u0435\u0434\u044B \u043B\u0438\u0431\u043E \u043D\u0438\u0447\u044C\u0435\u0439 \u0432 \u0442\u0435\u043C\u043F\u0430\u0435, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0440\u0430\u0437\u0434\u0430\u0447 \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0431\u043E\u043B\u044C\u0448\u0435.",
              "\u0421\u0432\u043E\u0438 \u0432\u0435\u0442\u0440\u044B \u0438\u0434\u0443\u0442 \u043E\u0442 \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E: \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434 \u0438 \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C \u0421\u0435\u0432\u0435\u0440. \u041E\u0431\u0449\u0438\u0439 \u0432\u0435\u0442\u0435\u0440 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0412\u043E\u0441\u0442\u043E\u043A\u043E\u043C \u0434\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044F \u0432\u0441\u0435\u043C\u0438 \u043F\u0435\u0440\u0438\u043E\u0434\u0430 \u0441\u0434\u0430\u0447\u0438, \u0437\u0430\u0442\u0435\u043C \u0432 \u0434\u043B\u0438\u043D\u043D\u043E\u043C \u043C\u0430\u0442\u0447\u0435 \u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0441\u044F \u042E\u0433\u043E\u043C. \u0426\u0435\u043D\u043D\u044B\u0435 \u0432\u0435\u0442\u0440\u044B \u043C\u043E\u0433\u0443\u0442 \u043C\u0435\u043D\u044F\u0442\u044C\u0441\u044F. \u0421\u0430\u043D\u043C\u0430 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u0438\u043C\u0432\u043E\u043B\u044B 2\u20138, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u043D\u0438\u044F \u0421\u0435\u0432\u0435\u0440\u0430 \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0442.",
              "\u0412 \u0441\u0430\u043D\u043C\u0435 \u043D\u0435\u043B\u044C\u0437\u044F \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0442\u044C \u0447\u043E\u0443 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435, \u043D\u043E \u0441\u0432\u043E\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0438 \u0441\u043E\u0431\u0438\u0440\u0430\u0442\u044C \u043C\u043E\u0436\u043D\u043E.",
              "\u0412 \u0441\u0430\u043D\u043C\u0435 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u0439 \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u044B\u0439 \u0438\u0433\u0440\u043E\u043A \u043D\u0435 \u043F\u043B\u0430\u0442\u0438\u0442, \u0438 \u0435\u0433\u043E \u0447\u0430\u0441\u0442\u044C \u043D\u0435 \u0440\u0430\u0441\u043F\u0440\u0435\u0434\u0435\u043B\u044F\u0435\u0442\u0441\u044F \u043C\u0435\u0436\u0434\u0443 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u043C\u0438. \u041F\u043E\u044D\u0442\u043E\u043C\u0443 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u0435 \u0432\u0437\u044F\u0442\u0438\u0435 \u043C\u043E\u0436\u0435\u0442 \u043F\u0440\u0438\u043D\u0435\u0441\u0442\u0438 \u043C\u0435\u043D\u044C\u0448\u0435, \u0447\u0435\u043C \u0432\u0447\u0435\u0442\u0432\u0435\u0440\u043E\u043C. \u041F\u0440\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043C\u0435\u0436\u0434\u0443 \u0442\u0435\u043C\u043F\u0430\u0435\u043C \u0438 \u043D\u043E\u0442\u0435\u043D\u043E\u043C \u0434\u0435\u043B\u0438\u0442\u0441\u044F 2000 \u0432\u043C\u0435\u0441\u0442\u043E 3000 \u043E\u0447\u043A\u043E\u0432."),
            rule_section(:table_mcr_aim, "MCR \u2014 \u0426\u0435\u043B\u044C \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u0427\u0435\u0442\u0432\u0435\u0440\u043E \u0441\u0442\u0430\u0440\u0430\u044E\u0442\u0441\u044F \u043F\u0435\u0440\u0432\u044B\u043C\u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043F\u0430\u0440\u0430 \u043C\u0438\u043D\u0438\u043C\u0443\u043C \u043D\u0430 8 \u0444\u0430\u043D\u044C \u0431\u0435\u0437 \u0446\u0432\u0435\u0442\u043E\u0432. \u0424\u0430\u043D\u044C \u0438\u0437\u043C\u0435\u0440\u044F\u044E\u0442 \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0445 \u0443\u0437\u043E\u0440\u043E\u0432. \u041F\u043E\u0431\u0435\u0434\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043F\u0440\u0438\u043D\u043E\u0441\u0438\u0442 \u0432\u044B\u043F\u043B\u0430\u0442\u0443, \u043C\u0430\u0442\u0447 \u0432\u044B\u0438\u0433\u0440\u044B\u0432\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u043E\u0431\u0449\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441."),
            rule_section(:table_mcr_terms, "MCR \u2014 \u0417\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0442\u0435\u0440\u043C\u0438\u043D\u043E\u0432",
              "\u0422\u044B \u0438\u0433\u0440\u0430\u0435\u0448\u044C \u043F\u0440\u043E\u0442\u0438\u0432 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445. \u0418\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0441\u043E\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0443\u044E \u0440\u0443\u043A\u0443, \u0430 \u043D\u0435 \u0443\u0431\u0438\u0440\u0430\u0435\u0448\u044C \u043F\u0430\u0440\u044B \u0441 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0438, \u043A\u0430\u043A \u0432 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435. \u0420\u0443\u043A\u0430 \u2014 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438; \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u2014 \u0438\u0433\u0440\u0430 \u043E\u0442 \u0432\u044B\u0434\u0430\u0447\u0438 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439. \u041C\u0430\u0442\u0447 \u043C\u043E\u0436\u0435\u0442 \u0441\u043E\u0441\u0442\u043E\u044F\u0442\u044C \u0438\u0437 \u043C\u043D\u043E\u0433\u0438\u0445 \u0440\u0430\u0437\u0434\u0430\u0447.",
              "- \u041A\u043E\u0441\u0442\u044C \u2014 \u043E\u0434\u043D\u0430 \u0448\u0442\u0443\u043A\u0430, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0431\u0430\u043C\u0431\u0443\u043A 5. \u0415\u0451 \u0432\u0438\u0434 \u0437\u0430\u0434\u0430\u0451\u0442\u0441\u044F \u043C\u0430\u0441\u0442\u044C\u044E \u0438 \u0447\u0438\u0441\u043B\u043E\u043C \u043B\u0438\u0431\u043E \u043A\u043E\u043D\u043A\u0440\u0435\u0442\u043D\u044B\u043C \u0432\u0435\u0442\u0440\u043E\u043C \u0438\u043B\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u043C. \u041E\u0431\u044B\u0447\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u0432\u0438\u0434\u0430 \u0447\u0435\u0442\u044B\u0440\u0435.",
              "- \u041C\u0430\u0441\u0442\u0438 \u2014 \u0441\u0438\u043C\u0432\u043E\u043B\u044B, \u0431\u0430\u043C\u0431\u0443\u043A\u0438 \u0438 \u043A\u0440\u0443\u0433\u0438, \u0441 \u0447\u0438\u0441\u043B\u0430\u043C\u0438 1\u20139. \u041E\u0434\u043D\u0430 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C \u043D\u0435 \u0441\u043C\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u043C\u0430\u0441\u0442\u0438. \u0422\u0435\u0440\u043C\u0438\u043D\u0430\u043B\u044B \u2014 1 \u0438 9, \u043F\u0440\u043E\u0441\u0442\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 2\u20138.",
              "- \u0411\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 \u0432\u0435\u0442\u0440\u044B \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434, \u0421\u0435\u0432\u0435\u0440 \u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u044B \u0431\u0435\u043B\u044B\u0439, \u0437\u0435\u043B\u0451\u043D\u044B\u0439, \u043A\u0440\u0430\u0441\u043D\u044B\u0439. \u0423 \u043D\u0438\u0445 \u043D\u0435\u0442 \u0447\u0438\u0441\u0435\u043B, \u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u0435\u0439 \u043E\u043D\u0438 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442.",
              "- \u0427\u043E\u0443, \u0438\u043B\u0438 \u0447\u0438, \u2014 \u0442\u0440\u0438 \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u0447\u0438\u0441\u043B\u0430 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438: \u0431\u0430\u043C\u0431\u0443\u043A\u0438 3, 4 \u0438 5. \u0411\u0430\u043C\u0431\u0443\u043A 3, \u043A\u0440\u0443\u0433 4 \u0438 \u0431\u0430\u043C\u0431\u0443\u043A 5 \u043D\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0442; 8, 9 \u0438 1 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0442\u043E\u0436\u0435 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u0447\u043E\u0443.",
              "- \u041F\u0430\u043D\u0433, \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043D \u0438\u043B\u0438 pong, \u2014 \u0442\u0440\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u043D\u0430\u043F\u0440\u0438\u043C\u0435\u0440 \u0442\u0440\u0438 \u043A\u0440\u0430\u0441\u043D\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430. \u0422\u0440\u0438 \u043F\u044F\u0442\u0451\u0440\u043A\u0438 \u0440\u0430\u0437\u043D\u044B\u0445 \u043C\u0430\u0441\u0442\u0435\u0439 \u043D\u0435 \u043E\u0431\u0440\u0430\u0437\u0443\u044E\u0442 \u043F\u0430\u043D\u0433.",
              "- \u041A\u043E\u043D\u0433, \u0438\u043B\u0438 \u043A\u0430\u043D, \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0415\u0433\u043E \u043D\u0443\u0436\u043D\u043E \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0438\u043C \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435\u043C; \u043D\u0430\u043B\u0438\u0447\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0432 \u0440\u0443\u043A\u0435 \u0441\u0430\u043C\u043E \u043F\u043E \u0441\u0435\u0431\u0435 \u043A\u043E\u043D\u0433 \u043D\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u044F\u0435\u0442. \u041E\u043D \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0434\u043D\u043E\u0439 \u0433\u0440\u0443\u043F\u043F\u043E\u0439 \u0438 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F.",
              "- \u041F\u0430\u0440\u0430 \u2014 \u0434\u0432\u0435 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438. \u0413\u0440\u0443\u043F\u043F\u0430 \u2014 \u0447\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433. \u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043E\u0434\u043D\u0443 \u043F\u0430\u0440\u0443, \u0430 \u043D\u0435 \u043F\u0440\u043E\u0441\u0442\u043E \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u043F\u0430\u0440 \u0438\u043B\u0438 \u043C\u043D\u043E\u0433\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438.",
              "- \u0421\u0442\u0435\u043D\u0430 \u2014 \u0437\u0430\u043F\u0430\u0441 \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F. \u0412\u0437\u044F\u0442\u0438\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 \u043A\u043E\u0441\u0442\u044C \u0432 \u0440\u0443\u043A\u0443; \u0441\u0431\u0440\u043E\u0441 \u0443\u0431\u0438\u0440\u0430\u0435\u0442 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0438\u0437 \u0440\u0443\u043A\u0438 \u0438 \u043F\u043E\u0437\u0432\u043E\u043B\u044F\u0435\u0442 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C \u0435\u0451 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C.",
              "- \u0412 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435\u0442 \u0433\u0440\u0443\u043F\u043F, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043D\u0430 \u0447\u0443\u0436\u0438\u0445 \u043A\u043E\u0441\u0442\u044F\u0445. \u0427\u043E\u0443, \u043F\u0430\u043D\u0433 \u0438\u043B\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0440\u0443\u043A\u0443. \u0413\u0440\u0443\u043F\u043F\u044B \u0438\u0437 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u043C\u043E\u0433\u0443\u0442 \u043E\u0441\u0442\u0430\u0432\u0430\u0442\u044C\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u043D\u044B\u0439 \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0439 \u043A\u043E\u043D\u0433 \u0440\u0443\u043A\u0443 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442.",
              "- \u041F\u043E\u0431\u0435\u0434\u0430 \u0441\u043E \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0442\u043E \u0432\u0437\u044F\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C; \u043F\u043E\u0431\u0435\u0434\u0430 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u2014 \u043A\u043E\u0441\u0442\u044C \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430; \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C.",
              "- \u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u2014 \u0432\u0438\u0434 \u043A\u043E\u0441\u0442\u0438, \u043A\u043E\u0442\u043E\u0440\u044B\u0439 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442 \u0440\u0443\u043A\u0443. \u0421 \u0431\u0430\u043C\u0431\u0443\u043A\u0430\u043C\u0438 4\u20135 \u043C\u043E\u0436\u043D\u043E \u0436\u0434\u0430\u0442\u044C 3 \u0438\u043B\u0438 6. \u0422\u0435\u043C\u043F\u0430\u0439 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442, \u0447\u0442\u043E \u0434\u043E \u043F\u043E\u043B\u043D\u043E\u0439 \u0444\u043E\u0440\u043C\u044B \u043D\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438. \u0414\u043B\u044F \u0437\u0430\u043A\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0442\u0430\u043A\u0436\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u0432\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C \u0443\u0441\u043B\u043E\u0432\u0438\u0435 \u043F\u043E \u043E\u0447\u043A\u0430\u043C \u044D\u0442\u043E\u0433\u043E \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u0430.",
              "- MCR \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 Mahjong Competition Rules. \u0424\u0430\u043D\u044C \u0438\u0437\u043C\u0435\u0440\u044F\u044E\u0442 \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0443\u0437\u043E\u0440\u043E\u0432. \u041D\u0443\u0436\u043D\u043E \u043C\u0438\u043D\u0438\u043C\u0443\u043C 8 \u0444\u0430\u043D\u044C \u0431\u0435\u0437 \u0446\u0432\u0435\u0442\u043E\u0447\u043D\u044B\u0445 \u0431\u043E\u043D\u0443\u0441\u043E\u0432. \u0417\u0430\u0442\u0435\u043C \u0438\u0437 \u043D\u0438\u0445 \u0432\u044B\u0447\u0438\u0441\u043B\u044F\u0435\u0442\u0441\u044F \u0432\u044B\u043F\u043B\u0430\u0442\u0430; \u044D\u0442\u043E \u043D\u0435 \u0442\u043E \u0436\u0435 \u0441\u0430\u043C\u043E\u0435, \u0447\u0442\u043E \u043E\u0431\u0449\u0438\u0439 \u0441\u0447\u0451\u0442 \u043C\u0430\u0442\u0447\u0430.",
              "- \u041E\u0447\u043A\u043E\u0432\u044B\u0439 \u0443\u0437\u043E\u0440 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u044E \u0440\u0443\u043A\u0443 \u0438\u043B\u0438 \u0435\u0451 \u0433\u0440\u0443\u043F\u043F\u044B. \u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u0441\u043E\u0447\u0435\u0442\u0430\u044E\u0442\u0441\u044F, \u0434\u0440\u0443\u0433\u0438\u0435 \u0443\u0436\u0435 \u0432\u043A\u043B\u044E\u0447\u0430\u044E\u0442 \u043C\u0435\u043D\u044C\u0448\u0438\u0439 \u0443\u0437\u043E\u0440 \u0438 \u0438\u0441\u043A\u043B\u044E\u0447\u0430\u044E\u0442 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u044B\u0435 \u043E\u0447\u043A\u0438. \u041D\u0435 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0439 \u0432\u0441\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
              "- \u0426\u0432\u0435\u0442\u044B \u0438 \u0441\u0435\u0437\u043E\u043D\u044B \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u044E\u0442\u0441\u044F \u0438 \u0437\u0430\u043C\u0435\u043D\u044F\u044E\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438. \u041A\u0430\u0436\u0434\u044B\u0439 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u0442 1 \u0444\u0430\u043D\u044C \u043A \u0437\u0430\u043A\u043E\u043D\u043D\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u0435, \u043D\u043E \u043D\u0435 \u043F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u043D\u0430\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0435 8. \u0421\u0435\u043C\u044C \u0444\u0430\u043D\u044C \u0441 \u0446\u0432\u0435\u0442\u043A\u043E\u043C \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u0442\u043E\u0447\u043D\u043E.",
              "- \u0421\u0432\u043E\u0439 \u0432\u0435\u0442\u0435\u0440 \u2014 \u0440\u043E\u043B\u044C \u043E\u0442\u043D\u043E\u0441\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u0441\u0434\u0430\u044E\u0449\u0435\u0433\u043E, \u0432\u0435\u0442\u0435\u0440 \u0440\u0430\u0443\u043D\u0434\u0430 \u043E\u0431\u0449\u0438\u0439 \u0434\u043B\u044F \u0432\u0441\u0435\u0445. \u041F\u0430\u043D\u0433 \u0441\u0432\u043E\u0435\u0433\u043E \u0432\u0435\u0442\u0440\u0430 \u0438\u043B\u0438 \u0432\u0435\u0442\u0440\u0430 \u0440\u0430\u0443\u043D\u0434\u0430 \u2014 \u043E\u0447\u043A\u043E\u0432\u044B\u0439 \u0443\u0437\u043E\u0440. \u0421\u0435\u0437\u043E\u043D\u044B \u044F\u0432\u043B\u044F\u044E\u0442\u0441\u044F \u0431\u043E\u043D\u0443\u0441\u0430\u043C\u0438, \u0430 \u043D\u0435 \u0447\u0435\u0442\u044B\u0440\u044C\u043C\u044F \u0440\u0430\u0443\u043D\u0434\u0430\u043C\u0438 \u0432\u0435\u0442\u0440\u043E\u0432."),
            rule_section(:table_mcr_start, "MCR \u2014 \u041D\u0430\u0447\u0430\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447\u0438",
              "\u0411\u0430\u043B\u0430\u043D\u0441\u044B \u043D\u0430\u0447\u0438\u043D\u0430\u044E\u0442\u0441\u044F \u0441 \u043D\u0443\u043B\u044F; \u0432\u044B\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0432\u044B\u043F\u043B\u0430\u0442\u044B \u043F\u0440\u0438\u0431\u0430\u0432\u043B\u044F\u044E\u0442 \u043E\u0447\u043A\u0438, \u043F\u0440\u043E\u0438\u0433\u0440\u0430\u043D\u043D\u044B\u0435 \u0432\u044B\u0447\u0438\u0442\u0430\u044E\u0442.",
              "\u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u043D\u0430\u0447\u0438\u043D\u0430\u0435\u0442 \u0441 14 \u043A\u043E\u0441\u0442\u044F\u043C\u0438 \u0438 \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u2014 \u0441 13. \u0412 \u043E\u0431\u044B\u0447\u043D\u044B\u0439 \u0445\u043E\u0434 \u0432\u044B\u0431\u0435\u0440\u0438 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u041F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0441\u043F\u0438\u0441\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0431\u0435\u0440\u0451\u0442. \u0415\u0441\u043B\u0438 \u0442\u044B \u0441\u0434\u0430\u044E\u0449\u0438\u0439, \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u0430\u044F \u043A\u043E\u0441\u0442\u044C \u0443\u0436\u0435 \u0435\u0441\u0442\u044C, \u0435\u0449\u0451 \u043E\u0434\u043D\u043E \u0432\u0437\u044F\u0442\u0438\u0435 \u0432 \u043D\u0430\u0447\u0430\u043B\u0435 \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F."),
            rule_section(:table_mcr_play, "MCR \u2014 \u041F\u0435\u0440\u0432\u044B\u0435 \u0445\u043E\u0434\u044B \u043F\u043E \u0448\u0430\u0433\u0430\u043C",
              "\u041F\u0435\u0440\u0435\u0434 \u043F\u0435\u0440\u0432\u044B\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440\u0438 \u0440\u0443\u043A\u0443 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u0432\u0432\u0435\u0440\u0445 \u0438 \u0432\u043D\u0438\u0437. \u0418\u0449\u0438 \u0441\u043E\u0441\u0435\u0434\u043D\u0438\u0435 \u0447\u0438\u0441\u043B\u0430 \u0434\u043B\u044F \u0447\u043E\u0443, \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u0434\u043B\u044F \u043F\u0430\u043D\u0433\u043E\u0432 \u0438 \u043E\u0434\u043D\u0443 \u0431\u0443\u0434\u0443\u0449\u0443\u044E \u043F\u0430\u0440\u0443. \u0413\u0440\u0443\u043F\u043F\u044B, \u043E\u0441\u0442\u0430\u0432\u0448\u0438\u0435\u0441\u044F \u0432 \u0440\u0443\u043A\u0435, \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u043E \u043E\u0442\u043C\u0435\u0447\u0430\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u043E: \u0438\u0433\u0440\u0430 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u0451\u0442 \u0438\u0445 \u043F\u0440\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0438 \u043F\u043E\u0431\u0435\u0434\u044B.",
              "\u0415\u0441\u043B\u0438 \u0442\u044B \u0432 \u0438\u0433\u0440\u043E\u0432\u044B\u0445 \u043F\u043E\u043B\u044F\u0445, \u043D\u043E\u0432\u044B\u0439 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0445\u043E\u0434 \u043F\u0435\u0440\u0435\u0432\u043E\u0434\u0438\u0442 \u0444\u043E\u043A\u0443\u0441 \u043D\u0430 \u0432\u0437\u044F\u0442\u0438\u0435 \u043A\u043E\u0441\u0442\u0438. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0444\u043E\u043A\u0443\u0441 \u043F\u043E\u043F\u0430\u0434\u0430\u0435\u0442 \u043D\u0430 \u043D\u043E\u0432\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0441 \u0441\u043E\u043E\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044E\u0449\u0435\u0439 \u043F\u043E\u043C\u0435\u0442\u043A\u043E\u0439. \u042D\u0442\u043E \u0435\u0449\u0451 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441: \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0439\u0442\u0438 \u0441\u0442\u0440\u0435\u043B\u043A\u0430\u043C\u0438 \u043A \u0434\u0440\u0443\u0433\u0438\u043C \u043A\u043E\u0441\u0442\u044F\u043C, \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u043D\u043E\u0432\u0443\u044E \u0438 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u0443\u044E.",
              "\u0414\u043B\u044F \u0441\u0431\u0440\u043E\u0441\u0430 \u0432\u044B\u0431\u0435\u0440\u0438 \u043E\u0434\u043D\u0443 \u043A\u043E\u0441\u0442\u044C \u0432 \u0441\u043F\u0438\u0441\u043A\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0445 \u0441\u0431\u0440\u043E\u0441\u043E\u0432 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0423\u0445\u043E\u0434\u0438\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u044D\u0442\u043E\u0442 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440. \u0415\u0441\u043B\u0438 \u043E\u0434\u0438\u043D\u0430\u043A\u043E\u0432\u044B\u0445 \u043A\u043E\u0441\u0442\u0435\u0439 \u0431\u044B\u043B\u043E \u0442\u0440\u0438, \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0434\u0432\u0435 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F.",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0442\u044B \u0443\u0441\u043B\u044B\u0448\u0438\u0448\u044C \u043A\u043E\u0441\u0442\u044C \u0438 \u0443\u0432\u0438\u0434\u0438\u0448\u044C \u043E\u0442\u0432\u0435\u0442\u044B. \u041F\u0430\u0441 \u043E\u0437\u043D\u0430\u0447\u0430\u0435\u0442 \u043B\u0438\u0448\u044C \u043E\u0442\u043A\u0430\u0437 \u043E\u0442 \u044D\u0442\u043E\u0439 \u043A\u043E\u0441\u0442\u0438, \u0430 \u043D\u0435 \u0432\u044B\u0445\u043E\u0434 \u0438\u043B\u0438 \u043F\u0440\u043E\u0438\u0433\u0440\u044B\u0448. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u043F\u0430\u0441\u0443\u044E\u0442, \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0438\u0433\u0440\u043E\u043A \u0431\u0435\u0440\u0451\u0442 \u043A\u043E\u0441\u0442\u044C. \u0414\u043E \u0442\u0432\u043E\u0435\u0433\u043E \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u043D\u043E\u0433\u0434\u0430 \u043F\u0440\u0438\u0445\u043E\u0434\u0438\u0442\u0441\u044F \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0440\u0430\u0437 \u0432\u044B\u0431\u0440\u0430\u0442\u044C \u043F\u0430\u0441.",
              "\u041F\u0435\u0440\u0432\u043E\u0435 \u043F\u043E\u043B\u0435 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0421\u0440\u0430\u0437\u0443 \u0437\u0430 \u043D\u0438\u043C \u0432\u0441\u0435 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F: \u043E\u0442\u0432\u0435\u0442\u044B, \u0432\u0437\u044F\u0442\u0438\u0435, \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u043A\u043E\u043D\u0433\u0438 \u0438\u043B\u0438 \u0440\u0438\u0438\u0447\u0438, \u0435\u0441\u043B\u0438 \u0432\u0430\u0440\u0438\u0430\u043D\u0442 \u0438\u0445 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442. \u0417\u0430\u0442\u0435\u043C \u0438\u0434\u0443\u0442 \u0442\u0432\u043E\u0438 \u043A\u043E\u0441\u0442\u0438. Tab \u0438 Shift+Tab \u043C\u0435\u043D\u044F\u044E\u0442 \u043F\u043E\u043B\u0435, \u0441\u0442\u0440\u0435\u043B\u043A\u0438 \u0432\u044B\u0431\u0438\u0440\u0430\u044E\u0442 \u043F\u0443\u043D\u043A\u0442, Enter \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442. \u041D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F.",
              "\u041F\u043E\u043B\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0445 \u0433\u0440\u0443\u043F\u043F \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0433\u0440\u0443\u043F\u043F\u044B \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432 \u0441 \u0438\u043C\u0435\u043D\u0430\u043C\u0438 \u0432\u043B\u0430\u0434\u0435\u043B\u044C\u0446\u0435\u0432. \u0421\u0431\u0440\u043E\u0441\u044B \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u044E\u0442, \u043A\u0442\u043E \u043A\u0430\u043A\u0438\u0435 \u043A\u043E\u0441\u0442\u0438 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u043B. \u0422\u0430\u043A \u043C\u043E\u0436\u043D\u043E \u043F\u043E\u043D\u044F\u0442\u044C, \u0447\u0442\u043E \u0443\u0436\u0435 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u043E \u0438 \u0447\u0442\u043E \u043D\u0443\u0436\u043D\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430\u043C. \u0421\u0430\u043C \u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u0445\u043E\u0434 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442.",
              "\u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B \u0440\u0443\u043A\u0443, \u0432\u044B\u0431\u0435\u0440\u0438 \u043C\u0430\u0434\u0436\u043E\u043D\u0433, \u0430 \u043D\u0435 \u0441\u0431\u0440\u043E\u0441 \u0438\u043B\u0438 \u043F\u0430\u0441. \u0418\u0433\u0440\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0444\u043E\u0440\u043C\u0443 \u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u044F \u043F\u043E \u043E\u0447\u043A\u0430\u043C. \u0415\u0441\u043B\u0438 \u0440\u0430\u043D\u044C\u0448\u0435 \u0437\u0430\u043A\u043E\u043D\u0447\u0438\u0442\u0441\u044F \u0441\u0442\u0435\u043D\u0430, \u0431\u0443\u0434\u0435\u0442 \u043D\u0438\u0447\u044C\u044F; \u0431\u043B\u0438\u0436\u0430\u0439\u0448\u0430\u044F \u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u044E \u0440\u0443\u043A\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u043D\u0435 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442.",
              "S \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u043E\u0447\u043A\u0438 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432. M \u0441\u043E\u043E\u0431\u0449\u0430\u0435\u0442 \u0447\u0438\u0441\u043B\u043E \u043A\u043E\u0441\u0442\u0435\u0439 \u0434\u043B\u044F \u0432\u0437\u044F\u0442\u0438\u044F \u0432 \u0441\u0442\u0435\u043D\u0435. \u041E\u043D\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0441\u043E\u043E\u0431\u0449\u0430\u044E\u0442: \u043D\u0435 \u0431\u0435\u0440\u0443\u0442, \u043D\u0435 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442, \u043D\u0435 \u043F\u0430\u0441\u0443\u044E\u0442 \u0438 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u044E\u0442 \u0447\u0443\u0436\u0438\u0435 \u0440\u0443\u043A\u0438.",
              "W \u0447\u0438\u0442\u0430\u0435\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u043E\u0439 \u0440\u0443\u043A\u0438: \u0444\u0430\u043D \u043B\u0438\u0431\u043E \u0445\u0430\u043D \u0438 \u0444\u0443, \u0430 \u0442\u0430\u043A\u0436\u0435 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u043C\u044B\u0435 \u043E\u0447\u043A\u0438. \u0411\u0435\u0437 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0443\u043A\u0438 \u043D\u0435 \u0443\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442\u0441\u044F. \u0414\u043E \u043F\u043E\u0431\u0435\u0434\u044B \u0432 \u0440\u0438\u0438\u0447\u0438 \u0441\u043A\u0440\u044B\u0442\u044B\u0435 \u0443\u0440\u0430-\u0434\u043E\u0440\u0430 \u043D\u0435 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0438\u0442\u043E\u0433\u043E\u0432\u0430\u044F \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u043C\u043E\u0436\u0435\u0442 \u0431\u044B\u0442\u044C \u0432\u044B\u0448\u0435. U \u0447\u0438\u0442\u0430\u0435\u0442 \u0442\u0432\u043E\u0438 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438, Shift+U \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445, R \u043D\u043E\u043C\u0435\u0440 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0432\u0435\u0442\u0440\u044B \u0438 \u0442\u0435\u043A\u0443\u0449\u0443\u044E \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044E. \u0412 \u0440\u0438\u0438\u0447\u0438 I \u0447\u0438\u0442\u0430\u0435\u0442 \u0438\u043D\u0434\u0438\u043A\u0430\u0442\u043E\u0440\u044B \u0438 \u043A\u0430\u043C\u043D\u0438 \u0434\u043E\u0440\u0430, \u0447\u0438\u0441\u043B\u043E \u0442\u0432\u043E\u0438\u0445 \u0434\u043E\u0440\u0430, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u0440\u0438\u0438\u0447\u0438, \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B, \u0445\u043E\u043D\u0431\u0430 \u0438 \u0442\u0432\u043E\u0439 \u0444\u0443\u0440\u0438\u0442\u0435\u043D. \u042D\u0442\u0438 \u043A\u043B\u0430\u0432\u0438\u0448\u0438 \u0442\u043E\u043B\u044C\u043A\u043E \u0447\u0438\u0442\u0430\u044E\u0442 \u0438\u043D\u0444\u043E\u0440\u043C\u0430\u0446\u0438\u044E."),
            rule_section(:table_mcr_build, "MCR \u2014 \u0427\u0442\u043E \u0441\u043E\u0431\u0440\u0430\u0442\u044C \u0434\u043B\u044F \u043F\u043E\u0431\u0435\u0434\u044B",
              "\u041E\u0431\u044B\u0447\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u2014 \u0447\u0435\u0442\u044B\u0440\u0435 \u0433\u0440\u0443\u043F\u043F\u044B \u0438 \u043F\u0430\u0440\u0430; MCR \u0442\u0430\u043A\u0436\u0435 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442 \u0441\u0435\u043C\u044C \u043F\u0430\u0440, \u0442\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0438\u0440\u043E\u0442 \u0438 \u043F\u0435\u0440\u0435\u043F\u043B\u0435\u0442\u0451\u043D\u043D\u044B\u0435 \u0440\u0443\u043A\u0438 \u0438\u0437 \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0430. \u041D\u0443\u0436\u043D\u044B \u0445\u043E\u0442\u044F \u0431\u044B 8 \u0444\u0430\u043D \u0431\u0435\u0437 \u0446\u0432\u0435\u0442\u043E\u0432. \u041F\u0440\u0438 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u0438 \u0443\u0441\u043B\u043E\u0432\u0438\u0439 \u0432\u044B\u0431\u0435\u0440\u0438 \u041E\u0431\u044A\u044F\u0432\u0438\u0442\u044C Mahjong \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0414\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E \u043F\u0443\u043D\u043A\u0442\u0430 \u0443\u043A\u0430\u0437\u0430\u043D\u044B \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u0435, \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0438 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u043A \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0441\u0442\u0438."),
            rule_section(:table_mcr_claims, "MCR \u2014 \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u0441\u0442\u0435\u0439 \u0438 \u043A\u043E\u043D\u0433\u043E\u0432",
              "\u041F\u043E\u0441\u043B\u0435 \u0447\u0443\u0436\u043E\u0433\u043E \u0441\u0431\u0440\u043E\u0441\u0430 \u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0442\u0432\u0435\u0442\u043E\u0432 \u043F\u0440\u0435\u0434\u043B\u0430\u0433\u0430\u0435\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0451\u043D\u043D\u044B\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F. \u0415\u0441\u043B\u0438 \u043A\u043E\u0441\u0442\u044C \u043D\u0435 \u043D\u0443\u0436\u043D\u0430, \u0432\u044B\u0431\u0435\u0440\u0438 \u043F\u0440\u043E\u043F\u0443\u0441\u043A. \u0418\u043D\u0430\u0447\u0435 \u0432\u044B\u0431\u0435\u0440\u0438 \u0447\u043E\u0443, \u043F\u043E\u043D\u0433, \u043A\u043E\u043D\u0433 \u0438\u043B\u0438 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u043C\u0430\u0434\u0436\u043E\u043D\u0433\u0430 \u0438 \u043D\u0430\u0436\u043C\u0438 Enter. \u0427\u043E\u0443 \u043C\u043E\u0436\u043D\u043E \u0437\u0430\u0431\u0440\u0430\u0442\u044C \u043B\u0438\u0448\u044C \u0443 \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0433\u043E \u043F\u043E \u0445\u043E\u0434\u0443 \u0438\u0433\u0440\u043E\u043A\u0430. \u0414\u043B\u044F \u043F\u043E\u043D\u0433\u0430 \u0438\u043B\u0438 \u043A\u043E\u043D\u0433\u0430 \u043F\u043E\u0434\u043E\u0439\u0434\u0451\u0442 \u0441\u0431\u0440\u043E\u0441 \u043B\u044E\u0431\u043E\u0433\u043E \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0430.",
              "\u041F\u043E\u0431\u0435\u0434\u0430 \u0432\u0430\u0436\u043D\u0435\u0435 \u0437\u0430\u044F\u0432\u043A\u0438 \u043D\u0430 \u0433\u0440\u0443\u043F\u043F\u0443, \u0430 \u043F\u043E\u043D\u0433 \u0438 \u043A\u043E\u043D\u0433 \u0432\u0430\u0436\u043D\u0435\u0435 \u0447\u043E\u0443. \u0415\u0441\u043B\u0438 \u043D\u0430 \u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u0441\u0442\u0438 \u043C\u043E\u0433\u0443\u0442 \u0432\u044B\u0438\u0433\u0440\u0430\u0442\u044C \u043D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u043E\u043A\u043E\u0432, \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043F\u0435\u0440\u0432\u044B\u0439 \u043F\u043E \u043E\u0447\u0435\u0440\u0435\u0434\u0438 \u043F\u043E\u0441\u043B\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0435\u0433\u043E. \u0418\u0433\u0440\u0430 \u0436\u0434\u0451\u0442 \u0432\u0441\u0435\u0445 \u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043E\u0442\u0432\u0435\u0442\u043E\u0432. \u041F\u043E\u0441\u043B\u0435 \u0432\u0437\u044F\u0442\u0438\u044F \u0447\u043E\u0443 \u0438\u043B\u0438 \u043F\u043E\u043D\u0433\u0430 \u0441\u0431\u0440\u043E\u0441\u044C \u043A\u043E\u0441\u0442\u044C \u0431\u0435\u0437 \u0432\u0437\u044F\u0442\u0438\u044F \u0438\u0437 \u0441\u0442\u0435\u043D\u044B; \u0433\u0440\u0443\u043F\u043F\u0430 \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439.",
              "\u041F\u043E\u0441\u043B\u0435 \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F \u043A\u043E\u043D\u0433\u0430 \u0432\u043E\u0437\u044C\u043C\u0438 \u0437\u0430\u043C\u0435\u0449\u0430\u044E\u0449\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438 \u043B\u0438\u0448\u044C \u0437\u0430\u0442\u0435\u043C \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0439. \u0415\u0441\u043B\u0438 \u0432\u0441\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u044D\u043A\u0437\u0435\u043C\u043F\u043B\u044F\u0440\u0430 \u0443 \u0442\u0435\u0431\u044F, \u043E\u0431\u044A\u044F\u0432\u0438 \u0438\u0445 \u0447\u0435\u0440\u0435\u0437 \u0441\u043F\u0438\u0441\u043E\u043A \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u043A\u043E\u043D\u0433\u043E\u0432. \u041C\u043E\u0436\u043D\u043E \u0442\u0430\u043A\u0436\u0435 \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0447\u0435\u0442\u0432\u0451\u0440\u0442\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u043A \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u043C\u0443 \u043F\u043E\u043D\u0433\u0443. \u041F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0442\u0430\u043A\u043E\u0439 \u043A\u043E\u043D\u0433 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F, \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438 \u043C\u043E\u0433\u0443\u0442 \u043E\u0431\u044A\u044F\u0432\u0438\u0442\u044C \u043F\u043E\u0431\u0435\u0434\u0443 \u043D\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u0435\u043C\u043E\u0439 \u043A\u043E\u0441\u0442\u0438.",
              "\u0415\u0441\u043B\u0438 \u0443 \u0442\u0435\u0431\u044F \u0434\u0432\u0430 \u0431\u0435\u043B\u044B\u0445 \u0434\u0440\u0430\u043A\u043E\u043D\u0430 \u0438 \u0441\u0431\u0440\u043E\u0448\u0435\u043D \u0442\u0440\u0435\u0442\u0438\u0439, \u041F\u0430\u043D\u0433 \u0432\u044B\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0435\u0442 \u0438\u0445 \u0438 \u043E\u0431\u0435\u0441\u043F\u0435\u0447\u0438\u0432\u0430\u0435\u0442 \u0443\u0437\u043E\u0440 \u0437\u0430 2 \u0444\u0430\u043D\u044C. \u041E\u0441\u0442\u0430\u043B\u044C\u043D\u0430\u044F \u0440\u0443\u043A\u0430 \u0435\u0449\u0451 \u0434\u043E\u043B\u0436\u043D\u0430 \u043F\u043E\u043C\u043E\u0447\u044C \u0434\u043E\u0439\u0442\u0438 \u0434\u043E 8. \u041E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0442\u0430\u043A\u0436\u0435 \u043C\u0435\u043D\u044F\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0441\u0442\u044C \u0437\u0430\u043A\u0440\u044B\u0442\u044B\u0445 \u0443\u0437\u043E\u0440\u043E\u0432. \u0414\u043E\u0441\u0442\u0443\u043F\u043D\u044B\u0439 \u041F\u0430\u043D\u0433 \u043D\u0435 \u0433\u0430\u0440\u0430\u043D\u0442\u0438\u0440\u0443\u0435\u0442 \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043E \u043C\u0438\u043D\u0438\u043C\u0443\u043C\u0430."),
            rule_section(:table_mcr_sets, "MCR \u2014 \u043A\u0430\u043A \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C\u0441\u044F \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u043E\u043C \u0438\u0437 81 \u043F\u0443\u043D\u043A\u0442\u0430",
              "\u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 81 \u043F\u0443\u043D\u043A\u0442 \u043E\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043E\u0447\u043A\u043E\u0432\u044B\u0435 \u044D\u043B\u0435\u043C\u0435\u043D\u0442\u044B MCR. \u041D\u0443\u0436\u043D\u0430 \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u0430\u044F \u0444\u043E\u0440\u043C\u0430 \u0440\u0443\u043A\u0438 \u0438 \u043D\u0435 \u043C\u0435\u043D\u0435\u0435 8 \u0444\u0430\u043D \u0431\u0435\u0437 \u0446\u0432\u0435\u0442\u043E\u0432. \u041A\u043E\u043D\u0433 \u0442\u0430\u043A\u0436\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0435 \u043F\u0443\u043D\u0433\u0430 \u0442\u043E\u0433\u043E \u0436\u0435 \u0432\u0438\u0434\u0430. \u0427\u0438\u0441\u043B\u043E\u0432\u044B\u0435 \u043C\u0430\u0441\u0442\u0438 \u2014 \u0437\u043D\u0430\u043A\u0438, \u043A\u0440\u0443\u0433\u0438 \u0438 \u0431\u0430\u043C\u0431\u0443\u043A; \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438 \u2014 \u0432\u0435\u0442\u0440\u044B \u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u044B.",
              "\u0412 \u0437\u0430\u043A\u0440\u044B\u0442\u043E\u0439 \u0440\u0443\u043A\u0435 \u043D\u0435\u0442 \u0433\u0440\u0443\u043F\u043F, \u043F\u043E\u043B\u0443\u0447\u0435\u043D\u043D\u044B\u0445 \u0441\u043E \u0441\u0431\u0440\u043E\u0441\u043E\u0432; \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u0435 \u0441\u043A\u0440\u044B\u0442\u043E\u0433\u043E \u043A\u043E\u043D\u0433\u0430 \u0435\u0451 \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442. \u041F\u0443\u043D\u0433, \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D\u043D\u044B\u0439 \u043F\u043E\u0431\u0435\u0434\u043D\u044B\u043C \u0447\u0443\u0436\u0438\u043C \u0441\u0431\u0440\u043E\u0441\u043E\u043C, \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044F \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u043C; \u0434\u0440\u0443\u0433\u0438\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0451\u043D\u043D\u044B\u0435 \u043F\u0443\u043D\u0433\u0438 \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u0441\u043A\u0440\u044B\u0442\u044B\u043C\u0438. \u041F\u0435\u0440\u0435\u043F\u043B\u0435\u0442\u0451\u043D\u043D\u0430\u044F \u043E\u0441\u043D\u043E\u0432\u0430 \u2014 147 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438, 258 \u0434\u0440\u0443\u0433\u043E\u0439 \u0438 369 \u0442\u0440\u0435\u0442\u044C\u0435\u0439; \u043C\u0430\u0441\u0442\u0438 \u043C\u043E\u0436\u043D\u043E \u043F\u0435\u0440\u0435\u0441\u0442\u0430\u0432\u0438\u0442\u044C.",
              "\u041D\u0435 \u0441\u043A\u043B\u0430\u0434\u044B\u0432\u0430\u0439 \u0432\u0441\u0435 \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0438\u0435 \u043D\u0430\u0437\u0432\u0430\u043D\u0438\u044F \u0431\u0435\u0437 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u0438\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0439. \u0411\u043E\u043B\u0435\u0435 \u043A\u0440\u0443\u043F\u043D\u0430\u044F \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u044F \u043C\u043E\u0436\u0435\u0442 \u0432\u043A\u043B\u044E\u0447\u0430\u0442\u044C \u043C\u0435\u043D\u044C\u0448\u0443\u044E, \u0430 \u043E\u0434\u043D\u0438 \u0433\u0440\u0443\u043F\u043F\u044B \u043D\u0435\u043B\u044C\u0437\u044F \u043F\u0440\u043E\u0438\u0437\u0432\u043E\u043B\u044C\u043D\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0434\u043B\u044F \u0441\u043E\u0441\u0442\u0430\u0432\u043D\u044B\u0445 \u043F\u0440\u0435\u043C\u0438\u0439. \u0418\u0433\u0440\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442 \u0441\u043E\u0432\u043C\u0435\u0441\u0442\u0438\u043C\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438. \u041D\u043E\u043C\u0435\u0440\u0430 \u0432 \u043F\u0435\u0440\u0435\u0447\u043D\u0435 \u0438\u0441\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0439 \u043E\u0442\u043D\u043E\u0441\u044F\u0442\u0441\u044F \u043A \u043A\u0430\u0442\u0430\u043B\u043E\u0433\u0443 MCR, \u0430 \u043D\u0435 \u043A \u043F\u043E\u0440\u044F\u0434\u043A\u0443 \u0445\u043E\u0434\u043E\u0432."),
            rule_section(:table_mcr_fan_88, "MCR: 88 \u0444\u0430\u043D",
              "- MCR 1: 88 \u0444\u0430\u043D \u2014 \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u0447\u0435\u0442\u044B\u0440\u0435 \u0432\u0435\u0442\u0440\u0430: \u0447\u0435\u0442\u044B\u0440\u0435 \u043F\u0443\u043D\u0433\u0430 \u0432\u0435\u0442\u0440\u043E\u0432. \u041E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u0438\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 2: 88 \u0444\u0430\u043D \u2014 \u0411\u043E\u043B\u044C\u0448\u0438\u0435 \u0442\u0440\u0438 \u0434\u0440\u0430\u043A\u043E\u043D\u0430: \u0442\u0440\u0438 \u043F\u0443\u043D\u0433\u0430 \u0434\u0440\u0430\u043A\u043E\u043D\u043E\u0432. \u041E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u0438\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 3: 88 \u0444\u0430\u043D \u2014 \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0435\u043B\u0451\u043D\u044B\u0435: \u0431\u0430\u043C\u0431\u0443\u043A 2, 3, 4, 6, 8 \u0438 \u0437\u0435\u043B\u0451\u043D\u044B\u0435 \u0434\u0440\u0430\u043A\u043E\u043D\u044B. \u041E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u0438\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 4: 88 \u0444\u0430\u043D \u2014 \u0414\u0435\u0432\u044F\u0442\u044C \u0432\u0440\u0430\u0442: \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u043E\u0441\u043D\u043E\u0432\u0430 1112345678999 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438 \u0438 \u0435\u0449\u0451 \u043E\u0434\u043D\u0430 \u043A\u043E\u0441\u0442\u044C \u044D\u0442\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 5: 88 \u0444\u0430\u043D \u2014 \u0427\u0435\u0442\u044B\u0440\u0435 \u043A\u043E\u043D\u0433\u0430. \u041E\u0442\u043A\u0440\u044B\u0442\u0430\u044F \u0438\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 6: 88 \u0444\u0430\u043D \u2014 \u0421\u0435\u043C\u044C \u043F\u043E\u0441\u043B\u0435\u0434\u043E\u0432\u0430\u0442\u0435\u043B\u044C\u043D\u044B\u0445 \u043F\u0430\u0440 \u043E\u0434\u043D\u043E\u0439 \u043C\u0430\u0441\u0442\u0438. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430.",
              "- MCR 7: 88 \u0444\u0430\u043D \u2014 \u0422\u0440\u0438\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0441\u0438\u0440\u043E\u0442: \u0432\u0441\u0435 \u0440\u0430\u0437\u043D\u044B\u0435 \u0435\u0434\u0438\u043D\u0438\u0446\u044B, \u0434\u0435\u0432\u044F\u0442\u043A\u0438 \u0438 \u0431\u043B\u0430\u0433\u043E\u0440\u043E\u0434\u043D\u044B\u0435 \u043A\u043E\u0441\u0442\u0438, \u043E\u0434\u043D\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u044F\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u043F\u0430\u0440\u044B. \u0422\u043E\u043B\u044C\u043A\u043E \u0437\u0430\u043A\u0440\u044B\u0442\u0430\u044F \u0440\u0443\u043A\u0430."),
            rule_section(:table_mcr_fan_64, "MCR: 64 \u0444\u0430\u043D",
