              "\u041A\u0430\u0436\u0434\u044B\u0439 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A \u043F\u043B\u0430\u0442\u0438\u0442 \u043E\u0441\u043D\u043E\u0432\u0443 8 \u043E\u0447\u043A\u043E\u0432. \u041F\u0440\u0438 \u043F\u043E\u0431\u0435\u0434\u0435 \u043D\u0430 \u0441\u0431\u0440\u043E\u0441\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0432\u0448\u0438\u0439 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u043E \u043F\u043B\u0430\u0442\u0438\u0442 \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0440\u0443\u043A\u0438 \u0441 \u0446\u0432\u0435\u0442\u0430\u043C\u0438; \u043F\u0440\u0438 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u043E\u043C \u0432\u0437\u044F\u0442\u0438\u0438 \u0435\u0451 \u0434\u043E\u043F\u043B\u0430\u0447\u0438\u0432\u0430\u044E\u0442 \u0432\u0441\u0435 \u0441\u043E\u043F\u0435\u0440\u043D\u0438\u043A\u0438. \u041A\u0430\u0436\u0434\u044B\u0439 \u0446\u0432\u0435\u0442\u043E\u043A \u0438 \u0432\u0440\u0435\u043C\u044F \u0433\u043E\u0434\u0430 \u0434\u043E\u0431\u0430\u0432\u043B\u044F\u044E\u0442 1 \u0444\u0430\u043D \u043A \u0432\u044B\u043F\u043B\u0430\u0442\u0435, \u043D\u043E \u043D\u0435 \u043A \u043C\u0438\u043D\u0438\u043C\u0443\u043C\u0443 8 \u0444\u0430\u043D."),
            rule_section(:table_mcr_match, "MCR \u2014 \u0420\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u0434\u043B\u0438\u043D\u0430 \u043C\u0430\u0442\u0447\u0430",
              "\u041C\u0430\u0442\u0447 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E \u0438\u043C\u0435\u0435\u0442 \u0447\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u0438 \u0440\u043E\u0432\u043D\u043E \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u0430\u0437\u0434\u0430\u0447 \u0441 \u043D\u0443\u043B\u0435\u0432\u044B\u043C\u0438 \u043D\u0430\u0447\u0430\u043B\u044C\u043D\u044B\u043C\u0438 \u0431\u0430\u043B\u0430\u043D\u0441\u0430\u043C\u0438. \u0412\u043E\u0441\u0442\u043E\u043A, \u042E\u0433, \u0417\u0430\u043F\u0430\u0434 \u0438 \u0421\u0435\u0432\u0435\u0440 \u0434\u043B\u044F\u0442\u0441\u044F \u043F\u043E \u0447\u0435\u0442\u044B\u0440\u0435. \u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u0432\u0441\u0435\u0433\u0434\u0430 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F, \u0431\u0435\u0437 \u043F\u043E\u0432\u0442\u043E\u0440\u043E\u0432 \u043F\u043E\u0441\u043B\u0435 \u0441\u0432\u043E\u0435\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439.",
              "\u0421\u0432\u043E\u0439 \u0432\u0435\u0442\u0435\u0440 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u043E \u0441\u0434\u0430\u044E\u0449\u0438\u043C, \u043E\u0431\u0449\u0438\u0439 \u2014 \u043F\u043E\u0441\u043B\u0435 \u0447\u0435\u0442\u044B\u0440\u0451\u0445 \u043F\u0435\u0440\u0438\u043E\u0434\u043E\u0432 \u0441\u0434\u0430\u0447\u0438. \u042D\u0442\u043E \u043C\u0435\u043D\u044F\u0435\u0442 \u0446\u0435\u043D\u043D\u043E\u0441\u0442\u044C \u0432\u0435\u0442\u0440\u043E\u0432. \u0421\u0435\u0437\u043E\u043D\u044B \u043E\u0441\u0442\u0430\u044E\u0442\u0441\u044F \u043E\u0442\u0434\u0435\u043B\u044C\u043D\u044B\u043C\u0438 \u0431\u043E\u043D\u0443\u0441\u0430\u043C\u0438. \u041F\u043E\u0441\u043B\u0435 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044C \u0440\u0435\u0437\u0443\u043B\u044C\u0442\u0430\u0442 \u0438 \u0431\u0430\u043B\u0430\u043D\u0441; \u043F\u0435\u0440\u0435\u0434 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0439 \u0432\u0441\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u044E\u0442 \u0433\u043E\u0442\u043E\u0432\u043D\u043E\u0441\u0442\u044C.",
              "\u041D\u0438\u0447\u044C\u044F \u0432 MCR \u043E\u0447\u043A\u043E\u0432 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u043D\u0435 \u0434\u0430\u0451\u0442. \u041F\u043E\u0441\u043B\u0435 \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u043D\u0430\u0438\u0431\u043E\u043B\u044C\u0448\u0438\u0439 \u0431\u0430\u043B\u0430\u043D\u0441, \u0440\u0430\u0432\u043D\u044B\u0435 \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C\u044B \u0434\u0430\u044E\u0442 \u043D\u0438\u0447\u044C\u044E. \u041D\u0435\u0441\u043A\u043E\u043B\u044C\u043A\u043E \u0434\u0435\u0448\u0451\u0432\u044B\u0445 \u043F\u043E\u0431\u0435\u0434 \u043C\u043E\u0433\u0443\u0442 \u043D\u0435 \u043F\u043E\u043A\u0440\u044B\u0442\u044C \u043E\u0434\u043D\u043E \u0434\u043E\u0440\u043E\u0433\u043E\u0435 \u043F\u043E\u0440\u0430\u0436\u0435\u043D\u0438\u0435. \u041F\u043E\u0431\u0435\u0434\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0438 \u0438 \u043C\u0430\u0442\u0447\u0430 \u2014 \u0440\u0430\u0437\u043D\u044B\u0435 \u0446\u0435\u043B\u0438."),
            rule_section(:table_mcr_variants, "MCR \u2014 \u0412\u044B\u0431\u043E\u0440 \u0434\u043B\u0438\u043D\u044B \u0438\u0433\u0440\u044B",
              "\u0414\u043B\u0438\u043D\u0430 \u0432\u044B\u0431\u0438\u0440\u0430\u0435\u0442\u0441\u044F \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0434\u043E \u043D\u0430\u0447\u0430\u043B\u0430. \u0421\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0435 \u043A\u043E\u0440\u043E\u0442\u043A\u0438\u0435 \u0432\u0430\u0440\u0438\u0430\u043D\u0442\u044B \u043C\u0435\u043D\u044F\u044E\u0442 \u0447\u0438\u0441\u043B\u043E \u0440\u0430\u0437\u0434\u0430\u0447, \u0430 \u043D\u0435 \u043F\u043E\u0441\u0442\u0440\u043E\u0435\u043D\u0438\u0435 \u0432\u044B\u0438\u0433\u0440\u044B\u0448\u043D\u043E\u0439 \u0440\u0443\u043A\u0438.",
              "\u041E\u0434\u043D\u0430 \u0440\u0430\u0437\u0434\u0430\u0447\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0431\u0435\u0434\u043E\u0439 \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439 \u043F\u043E \u0441\u0442\u0435\u043D\u0435. \u0427\u0435\u0442\u044B\u0440\u0435 \u0440\u0430\u0443\u043D\u0434\u0430 \u2014 \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C \u0440\u0430\u0437\u0434\u0430\u0447: \u0447\u0435\u0442\u044B\u0440\u0435 \u0441 \u043E\u0431\u0449\u0438\u043C \u0412\u043E\u0441\u0442\u043E\u043A\u043E\u043C, \u0447\u0435\u0442\u044B\u0440\u0435 \u0441 \u042E\u0433\u043E\u043C, \u0447\u0435\u0442\u044B\u0440\u0435 \u0441 \u0417\u0430\u043F\u0430\u0434\u043E\u043C, \u0447\u0435\u0442\u044B\u0440\u0435 \u0441 \u0421\u0435\u0432\u0435\u0440\u043E\u043C. \u0412 \u043A\u0430\u0436\u0434\u043E\u043C \u043A\u0430\u0436\u0434\u044B\u0439 \u0441\u0434\u0430\u0451\u0442 \u043E\u0434\u0438\u043D \u0440\u0430\u0437. \u0421\u0434\u0430\u044E\u0449\u0438\u0439 \u0432\u0441\u0435\u0433\u0434\u0430 \u043C\u0435\u043D\u044F\u0435\u0442\u0441\u044F \u0434\u0430\u0436\u0435 \u043F\u043E\u0441\u043B\u0435 \u043F\u043E\u0431\u0435\u0434\u044B \u0438\u043B\u0438 \u043D\u0438\u0447\u044C\u0435\u0439, \u0431\u0435\u0437 \u043F\u043E\u0432\u0442\u043E\u0440\u043E\u0432, \u0443\u0434\u043B\u0438\u043D\u044F\u044E\u0449\u0438\u0445 \u044D\u0442\u0438 \u0448\u0435\u0441\u0442\u043D\u0430\u0434\u0446\u0430\u0442\u044C."),
            rule_section(:controls, "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u0441 \u043A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u044B",
              "Tab: \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0435 \u043F\u043E\u043B\u0435.",
              "Shift+Tab: \u043F\u0440\u0435\u0434\u044B\u0434\u0443\u0449\u0435\u0435 \u043F\u043E\u043B\u0435.",
              "\u0412\u0432\u0435\u0440\u0445/\u0432\u043D\u0438\u0437: \u0432\u044B\u0431\u043E\u0440 \u043A\u043E\u0441\u0442\u0438 \u0438\u043B\u0438 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0432 \u0441\u043F\u0438\u0441\u043A\u0435.",
              "Enter: \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043D\u0438\u0435 \u0434\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u0430.",
              "S: \u0442\u0435\u043A\u0443\u0449\u0438\u0435 \u043E\u0447\u043A\u0438 \u0432\u0441\u0435\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "M: \u043E\u0441\u0442\u0430\u0442\u043E\u043A \u043A\u043E\u0441\u0442\u0435\u0439 \u0432 \u0441\u0442\u0435\u043D\u0435; \u0432 \u043F\u0430\u0441\u044C\u044F\u043D\u0441\u0435 \u2014 \u0432 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0435.",
              "\u0432\u043B\u0435\u0432\u043E/\u0432\u043F\u0440\u0430\u0432\u043E (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u0441\u043C\u0435\u043D\u0430 \u0441\u0442\u043E\u043B\u0431\u0446\u0430.",
              "\u0432\u0432\u0435\u0440\u0445/\u0432\u043D\u0438\u0437 (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u0441\u043C\u0435\u043D\u0430 \u0440\u044F\u0434\u0430.",
              "1 (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u043D\u0438\u0436\u043D\u0438\u0439 \u0441\u043B\u043E\u0439.",
              "2 (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u0432\u0442\u043E\u0440\u043E\u0439 \u0441\u043B\u043E\u0439 \u0422\u0435\u0440\u0440\u0430\u0441.",
              "3 (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u0432\u0435\u0440\u0445\u043D\u0438\u0439 \u0441\u043B\u043E\u0439 \u0422\u0435\u0440\u0440\u0430\u0441.",
              "D (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u0441\u043B\u043E\u0439, \u0440\u044F\u0434 \u0438 \u0441\u0442\u043E\u043B\u0431\u0435\u0446.",
              "Enter (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u043E\u0442\u043C\u0435\u0442\u0438\u0442\u044C \u043F\u0435\u0440\u0432\u0443\u044E \u043A\u043E\u0441\u0442\u044C \u0438\u043B\u0438 \u0443\u0431\u0440\u0430\u0442\u044C \u043F\u043E\u0434\u0445\u043E\u0434\u044F\u0449\u0443\u044E \u0432\u0442\u043E\u0440\u0443\u044E.",
              "Escape (\u043F\u0430\u0441\u044C\u044F\u043D\u0441): \u043E\u0442\u043C\u0435\u043D\u0438\u0442\u044C \u0432\u044B\u0434\u0435\u043B\u0435\u043D\u0438\u0435.",
              "D (\u0438\u0433\u0440\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C): \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u043A\u0430\u043C\u0435\u043D\u044C, \u043E\u0436\u0438\u0434\u0430\u044E\u0449\u0438\u0439 \u0442\u0432\u043E\u0435\u0433\u043E \u043E\u0442\u0432\u0435\u0442\u0430.",
              "W (\u0438\u0433\u0440\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C): \u0441\u0442\u043E\u0438\u043C\u043E\u0441\u0442\u044C \u0434\u043E\u043F\u0443\u0441\u0442\u0438\u043C\u043E\u0439 \u043F\u043E\u0431\u0435\u0434\u044B \u0438 \u043F\u043E\u043B\u0443\u0447\u0430\u0435\u043C\u044B\u0435 \u043E\u0447\u043A\u0438.",
              "U (\u0438\u0433\u0440\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C): \u0442\u0432\u043E\u0438 \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438.",
              "Shift+U (\u0438\u0433\u0440\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C): \u0432\u044B\u043B\u043E\u0436\u0435\u043D\u043D\u044B\u0435 \u043A\u043E\u043C\u0431\u0438\u043D\u0430\u0446\u0438\u0438 \u043E\u0441\u0442\u0430\u043B\u044C\u043D\u044B\u0445 \u0438\u0433\u0440\u043E\u043A\u043E\u0432.",
              "R (\u0438\u0433\u0440\u0430 \u0437\u0430 \u0441\u0442\u043E\u043B\u043E\u043C): \u043D\u043E\u043C\u0435\u0440 \u0440\u0430\u0437\u0434\u0430\u0447\u0438, \u0432\u0435\u0442\u0440\u044B \u0438 \u0442\u0435\u043A\u0443\u0449\u0430\u044F \u0441\u0438\u0442\u0443\u0430\u0446\u0438\u044F.",
              "I (\u0440\u0438\u0438\u0447\u0438): \u0434\u043E\u0440\u0430, \u043E\u0431\u044A\u044F\u0432\u043B\u0435\u043D\u0438\u044F, \u0434\u0435\u043F\u043E\u0437\u0438\u0442\u044B, \u0445\u043E\u043D\u0431\u0430 \u0438 \u0442\u0432\u043E\u0439 \u0444\u0443\u0440\u0438\u0442\u0435\u043D.")
          ]
        end
